INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13858, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体里有脊柱（脊梁骨）的动物，包括鱼类、两栖类、爬行类、鸟类和哺乳类。", "primary_collocate": null, "pronunciation": "jǐ zhuī dòng wù", "ipa": "tɕi˨˩ ʈʂweɪ˥ tʊŋ˥˩ wu˥˩", "syllable_count": 4, "sentences": [{"text": "研究人员在一片湿地中调查发现，鱼类、两栖类和鸟类等生物都是脊椎动物，它们的身体里都有脊柱，因而被归为同一大类，在生态系统中占据重要位置。", "target_word": "脊椎动物", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "鱼、鸟和人都是脊椎动物。", "target_word": "脊椎动物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "脊椎动物的身体里都有脊柱。", "target_word": "脊椎动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "青蛙属于两栖类，是一种脊椎动物。", "target_word": "脊椎动物", "complexity_tier": "T3", "furigana": "qīng wā shǔ yú liǎng qī lèi, shì yī zhǒng jǐ zhuī dòng wù。", "sentence_source": "generated"}, {"text": "脊椎动物分为鱼类、两栖类、爬行类、鸟类和哺乳类。", "target_word": "脊椎动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜘蛛不是脊椎动物，因为它没有脊柱。", "target_word": "脊椎动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鲸是海里最大的脊椎动物。", "target_word": "脊椎动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师带学生观察池塘里的脊椎动物。", "target_word": "脊椎动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昆虫的骨骼在体外，脊椎动物的骨骼在体内。", "target_word": "脊椎动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种脊椎动物生活在水里，用鳃呼吸。", "target_word": "脊椎动物", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "无脊椎动物", "label": "复合"}, {"form": "脊椎動物", "label": "繁体"}], "register": "书面", "sense_fingerprint": "身体里有脊柱的动物的总称，含鱼、两栖、爬行、鸟、哺乳五类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2009d73c-bf4e-4a49-ada1-b6ff159c7f51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13858, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脊椎动物", "is_correct": true, "explanation": "正确。鱼类、两栖类和鸟类的身体里都有脊柱，同属“脊椎动物”这一大类。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不是动物，无法概括鱼类、两栖类和鸟类。"}, {"text": "昆虫", "is_correct": false, "explanation": "语义：昆虫没有脊柱，属于无脊椎动物，不能概括有脊柱的鱼类、两栖类和鸟类。"}, {"text": "岩石", "is_correct": false, "explanation": "语义：岩石不是生物，无法概括鱼类、两栖类和鸟类。"}], "explanations": {"脊椎动物": "正确。鱼类、两栖类和鸟类的身体里都有脊柱，同属“脊椎动物”这一大类。", "植物": "语义：植物不是动物，无法概括鱼类、两栖类和鸟类。", "昆虫": "语义：昆虫没有脊柱，属于无脊椎动物，不能概括有脊柱的鱼类、两栖类和鸟类。", "岩石": "语义：岩石不是生物，无法概括鱼类、两栖类和鸟类。"}, "sentence_index": 0, "correct_answer": "脊椎动物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脊椎动物受伤了，今天得去医院拍片。", "explanation": "用错义项：这里指人的脊柱，但“脊椎动物”是动物类群的名称，不能用来指身体的部位。"}, {"text": "这座池塘里住着一座脊椎动物。", "explanation": "量词用错：“座”用于山、楼等大型固定物，不能用来数动物。“脊椎动物”作类别时量词用“种”。"}, {"text": "这只蜘蛛没有脊柱，属于脊椎动物。", "explanation": "这里应该用〈无脊椎动物〉。脊椎动物有脊柱，蜘蛛没有脊柱，不能归入这一类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脊椎动物", "is_correct": true, "explanation": "正确。鲸有脊柱，是海里最大的脊椎动物。"}, {"text": "岛屿", "is_correct": false, "explanation": "语义：鲸是动物，不是岛屿，句中指的是海里的生物。"}, {"text": "建筑", "is_correct": false, "explanation": "语义：鲸是动物，不是建筑物，无法说“海里最大的建筑”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不是可以比较大小的具体事物，不能说“海里最大的天气”。"}], "explanations": {"脊椎动物": "正确。鲸有脊柱，是海里最大的脊椎动物。", "岛屿": "语义：鲸是动物，不是岛屿，句中指的是海里的生物。", "建筑": "语义：鲸是动物，不是建筑物，无法说“海里最大的建筑”。", "天气": "搭配：“天气”不是可以比较大小的具体事物，不能说“海里最大的天气”。"}, "sentence_index": 6, "correct_answer": "脊椎动物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蜜蜂是一种脊椎动物，身体有六条腿。", "explanation": "这里应该用〈昆虫〉。脊椎动物有脊柱，蜜蜂没有脊柱，不能归入这一类。"}, {"text": "这家宠物店卖了三朵脊椎动物。", "explanation": "量词用错：“朵”用于花，不能用来数动物。脊椎动物作为类别，量词要用“种”。"}, {"text": "他的脊椎动物疼得厉害，只能躺着。", "explanation": "用错义项：这里指人的脊柱，但“脊椎动物”是动物类群，不能用来指身体的部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蛇是一座脊椎动物。", "corrected_sentence": "蛇是一种脊椎动物。", "error_description": "量词错误：应把“座”改为“种”。“座”用于大型固定物，不能数动物；表示“脊椎动物”这一类时要用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鲸是海里最大的一条脊椎动物。", "corrected_sentence": "鲸是海里最大的一种脊椎动物。", "error_description": "量词错误：应把“条”改为“种”。“条”可以用于鱼、蛇等具体动物，但“脊椎动物”指一整类动物，计量这一类时要用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13859, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13859, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13859, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容事物像瀑布一样连续地、层层相连地发生或连接。", "primary_collocate": null, "pronunciation": "jí lián", "ipa": "tɕi˧˥ ljɛn˧˥", "syllable_count": 2, "sentences": [{"text": "研究人员发现，一种授粉昆虫减少后，植物结实率随之下降，依赖这些植物的鸟类和哺乳动物也受到影响，这种影响一环接一环地传下去，形成级联的变化。", "target_word": "级联", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这个系统的反应是级联的。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林里的变化是级联的，一个接着一个。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种级联的影响会越来越大。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水池是级联的，水从上面流到下面。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几个电路是级联的，信号一级传给一级。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个小错误引发了级联的变化。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座山上的瀑布是级联的，一层接着一层。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家担心，这里的生态变化会呈级联态势。", "target_word": "级联", "complexity_tier": "T3", "furigana": "zhuān jiā dān xīn, zhè lǐ de shēng tài biàn huà huì chéng jí lián tài shì。", "sentence_source": "generated"}, {"text": "他把三个小水箱设计成级联的。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "级联式", "label": "复合"}, {"form": "级联反应", "label": "复合"}, {"form": "级联效应", "label": "复合"}, {"form": "級聯", "label": "繁体"}], "register": "书面", "sense_fingerprint": "形容事物像瀑布一样层层相连、接连发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2009d73c-bf4e-4a49-ada1-b6ff159c7f51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13859, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "级联", "is_correct": true, "explanation": "正确。“一环接一环地传下去”描述层层相连的变化，应填“级联”。"}, {"text": "分散", "is_correct": false, "explanation": "语义：句中强调影响一环接一环地传递，“分散”与之矛盾。"}, {"text": "孤立", "is_correct": false, "explanation": "语义：“孤立”与“一环接一环地传下去”的描述矛盾。"}, {"text": "静止", "is_correct": false, "explanation": "语义：句中描述的是变化层层传递，“静止”与之矛盾。"}], "explanations": {"级联": "正确。“一环接一环地传下去”描述层层相连的变化，应填“级联”。", "分散": "语义：句中强调影响一环接一环地传递，“分散”与之矛盾。", "孤立": "语义：“孤立”与“一环接一环地传下去”的描述矛盾。", "静止": "语义：句中描述的是变化层层传递，“静止”与之矛盾。"}, "sentence_index": 0, "correct_answer": "级联"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场雨级联下了三天。", "explanation": "这里应该用〈连续〉。级联形容事物像瀑布一样层层相连，不用来说持续的时间。"}, {"text": "他听到这个消息，心情很级联。", "explanation": "用错义项：级联形容事物层层相连的样子，不用来形容人的心情。"}, {"text": "这个学生的成绩很级联，每次都是第一名。", "explanation": "用错对象：级联只形容事物的结构或变化方式，不用来评价成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13859, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "级联", "is_correct": true, "explanation": "正确。“引发”后的变化是一环接一环的，用“级联”。"}, {"text": "独立", "is_correct": false, "explanation": "语义：“引发”说明变化由前一个错误导致，变化不会是独立的。"}, {"text": "平静", "is_correct": false, "explanation": "搭配：“平静”多形容心情或环境，不用来说“引发的变化”。"}, {"text": "无关", "is_correct": false, "explanation": "语义：“引发”说明两者有因果关系，“无关”与之矛盾。"}], "explanations": {"级联": "正确。“引发”后的变化是一环接一环的，用“级联”。", "独立": "语义：“引发”说明变化由前一个错误导致，变化不会是独立的。", "平静": "搭配：“平静”多形容心情或环境，不用来说“引发的变化”。", "无关": "语义：“引发”说明两者有因果关系，“无关”与之矛盾。"}, "sentence_index": 6, "correct_answer": "级联"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这三个选项是级联的，可以同时选。", "explanation": "这里应该用〈并列〉。级联强调一层接一层地相连，不表示并排平等。"}, {"text": "我的心情很级联，一会儿高兴，一会儿难过。", "explanation": "用错义项：级联形容事物的连接方式，不用来形容心情。"}, {"text": "这块石头很级联，形状非常圆。", "explanation": "用错义项：级联不形容物体的形状，只形容层层相连的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次故障的影响是级联地，一步一步扩大。", "corrected_sentence": "这次故障的影响是级联的，一步一步扩大。", "error_description": "“地”用错：“级联”作表语时要用“的”，“地”只修饰动词，不能修饰“是”后的形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几个池子是级联，水一层层往下流。", "corrected_sentence": "这几个池子是级联的，水一层层往下流。", "error_description": "“的”漏掉：“是”后作表语的形容词要加“的”，应为“级联的”，不能直接说“是级联”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
