INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13860, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指精神或情绪上完全失去控制，无法继续支撑。", "primary_collocate": null, "pronunciation": "bēng kuì", "ipa": "pəŋ˥ kʰweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他太累了，精神快要崩溃了。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "压力太大，她一下子崩溃了。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到坏消息，他情绪崩溃，大哭起来。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她再也受不了，当场崩溃了。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别逼他了，他快要崩溃了。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "连续加班一个月，小王终于崩溃了。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试失败后，他的精神差点崩溃。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "压力一直这么大，我会崩溃的。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她失去了孩子，整个人都崩溃了。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，他需要休息，否则精神会崩溃。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "崩溃了", "label": "体标"}, {"form": "崩溃过", "label": "体标"}, {"form": "精神崩溃", "label": "复合"}, {"form": "崩潰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "精神或情绪完全失控、撑不下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2009d73c-bf4e-4a49-ada1-b6ff159c7f51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13860, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "崩溃", "is_correct": true, "explanation": "“精神快要崩溃了”指精神失控、撑不住，与“太累”的语境一致。"}, {"text": "放松", "is_correct": false, "explanation": "语义：“放松”指身心舒缓，与“太累”后精神快要耗竭的语境相反。"}, {"text": "振奋", "is_correct": false, "explanation": "语义：“振奋”指情绪高涨，与“太累”造成的精力耗尽相反。"}, {"text": "集中", "is_correct": false, "explanation": "搭配：“集中”多指注意力，不能用“精神快要集中了”来表示身心耗竭。"}], "explanations": {"崩溃": "“精神快要崩溃了”指精神失控、撑不住，与“太累”的语境一致。", "放松": "语义：“放松”指身心舒缓，与“太累”后精神快要耗竭的语境相反。", "振奋": "语义：“振奋”指情绪高涨，与“太累”造成的精力耗尽相反。", "集中": "搭配：“集中”多指注意力，不能用“精神快要集中了”来表示身心耗竭。"}, "sentence_index": 0, "correct_answer": "崩溃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很用心地听讲，一句话都没漏，笔记也很完整，老师还夸我精神崩溃了。", "explanation": "“崩溃”指精神或情绪完全失控，与被夸奖的专注状态矛盾；这里应该用〈专注〉。"}, {"text": "他的学习计划很完整，每天都按时完成，所以他的精神状态一直很崩溃。", "explanation": "“崩溃”指精神失控、无法支撑，与计划完整、按时完成的状态矛盾；这里应该用〈稳定〉。"}, {"text": "他对记者很礼貌，一直很崩溃地回答问题。", "explanation": "“崩溃”表示情绪失控，不能描述有条理、礼貌的回答；这里应该用〈镇定〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "崩溃", "is_correct": true, "explanation": "“差点崩溃”指精神几乎失去控制，与考试失败的语境相符。"}, {"text": "高涨", "is_correct": false, "explanation": "语义：“高涨”指情绪热烈，与考试失败后的挫败心理相反。"}, {"text": "膨胀", "is_correct": false, "explanation": "语义：“膨胀”指自满或数量扩大，与失败后的挫败心理不符。"}, {"text": "发抖", "is_correct": false, "explanation": "搭配：“发抖”指身体颤动，不说“精神发抖”来表示心理状态。"}], "explanations": {"崩溃": "“差点崩溃”指精神几乎失去控制，与考试失败的语境相符。", "高涨": "语义：“高涨”指情绪热烈，与考试失败后的挫败心理相反。", "膨胀": "语义：“膨胀”指自满或数量扩大，与失败后的挫败心理不符。", "发抖": "搭配：“发抖”指身体颤动，不说“精神发抖”来表示心理状态。"}, "sentence_index": 6, "correct_answer": "崩溃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她听到消息后，平静地崩溃了，一点反应都没有。", "explanation": "“崩溃”指情绪完全失控、无法支撑，与句中的平静反应矛盾；这里应该用〈淡定〉。"}, {"text": "他的精神很好，每天都崩溃一次。", "explanation": "“崩溃”指精神或情绪完全失控，是负面状态，与句中描述的良好状态矛盾；这里应该用〈稳定〉。"}, {"text": "他很崩溃地修好了电脑。", "explanation": "“崩溃”表示情绪失控，不能修饰“修好电脑”这类有条理的行为；这里应该用〈认真〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么多的压力，让她几乎崩溃了了。", "corrected_sentence": "这么多的压力，让她几乎崩溃了。", "error_description": "“崩溃”后只用一个“了”表示完成，多出的“了”是错误；正确说法是“几乎崩溃了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么多事压下来，我真的快崩溃掉了。", "corrected_sentence": "这么多事压下来，我真的快崩溃了。", "error_description": "“崩溃”后不接结果补语“掉”，应直接说“快崩溃了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
