INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13861, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "农业区是指以农业生产为主要功能的区域，通常包含农田、牧场和林地等。", "primary_collocate": null, "pronunciation": "nóng yè qū", "ipa": "nʊŋ˧˥ jɛ˥˩ tɕʰy˥˥", "syllable_count": 3, "sentences": [{"text": "例如，在某些高原农业区，野生蜂类数量锐减已导致本地果树坐果率不足三成，迫使农民转向成本高昂的人工授粉，这不仅增加了农业生产的经济负担，也暴露了食物供应链的脆弱性。", "target_word": "农业区", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个农业区有农田，也有牧场和林地。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车经过这个农业区，两边都是农田。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的人多靠种地和养牛生活，是个农业区。", "target_word": "农业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想保护这个农业区的农田，不让人盖房子。", "target_word": "农业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个农业区夏天雨水多，农民很忙。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在农业区长大，所以很会种地。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市旁边的农业区，每天给城里送菜。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年这个农业区的天气不好，粮食少了。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想去农业区看看农民怎么种田。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "片", "label": "量词"}, {"form": "農業區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "以农业生产为主，包含农田、牧场、林地的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2009d73c-bf4e-4a49-ada1-b6ff159c7f51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13861, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "农业区", "is_correct": true, "explanation": "“农业区”指以农业生产为主的区域，与果树坐果、人工授粉和农民的语境一致。"}, {"text": "城市区", "is_correct": false, "explanation": "语义：“城市区”指城市地带，与果树、农民和农业生产的语境不符。"}, {"text": "工业区", "is_correct": false, "explanation": "语义：“工业区”以工厂为主，与果树坐果和人工授粉的语境冲突。"}, {"text": "矿区", "is_correct": false, "explanation": "搭配：“矿区”指采矿地带，不能与“果树坐果”“农民转向人工授粉”搭配。"}], "explanations": {"农业区": "“农业区”指以农业生产为主的区域，与果树坐果、人工授粉和农民的语境一致。", "城市区": "语义：“城市区”指城市地带，与果树、农民和农业生产的语境不符。", "工业区": "语义：“工业区”以工厂为主，与果树坐果和人工授粉的语境冲突。", "矿区": "搭配：“矿区”指采矿地带，不能与“果树坐果”“农民转向人工授粉”搭配。"}, "sentence_index": 0, "correct_answer": "农业区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的孩子每天请农业区给他上课，学习很多知识。", "explanation": "“农业区”是地区，不会给人上课；这里应该用〈老师〉。"}, {"text": "这个农业区生产了很多钢铁，供应全国。", "explanation": "“农业区”以农业生产为主，不生产钢铁；这里应该用〈工厂〉或〈钢铁厂〉。"}, {"text": "他是个农业区，从小在那里长大。", "explanation": "“农业区”指地区，不能用来指人；这里应该用〈农民〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13861, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "农业区", "is_correct": true, "explanation": "“在农业区长大”与“很会种地”前后呼应，语境通顺。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠不适合农作，与“很会种地”的结果相冲突。"}, {"text": "港口", "is_correct": false, "explanation": "语义：港口是码头，与“很会种地”的成长背景不符。"}, {"text": "图书馆", "is_correct": false, "explanation": "搭配：“长大”的地点多为居住地，图书馆不是可以长大的地方。"}], "explanations": {"农业区": "“在农业区长大”与“很会种地”前后呼应，语境通顺。", "沙漠": "语义：沙漠不适合农作，与“很会种地”的结果相冲突。", "港口": "语义：港口是码头，与“很会种地”的成长背景不符。", "图书馆": "搭配：“长大”的地点多为居住地，图书馆不是可以长大的地方。"}, "sentence_index": 6, "correct_answer": "农业区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想去一把农业区看看农民怎么种田。", "explanation": "“把”用于有柄的器具，不用于地区；农业区应该用“个”或“片”。"}, {"text": "我想请农业区教我种田，今天就出发。", "explanation": "“农业区”是地区，不会教人；这里应该用〈农民〉。"}, {"text": "我想去一棵农业区看看农民怎么种田。", "explanation": "“棵”用于树木和植物，不用于地区；农业区应该用“个”或“片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13861, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们开车经过那只农业区，路两边都是玉米地。", "corrected_sentence": "我们开车经过那个农业区，路两边都是玉米地。", "error_description": "“农业区”是地区，应该用量词“个”或“片”，不用“只”（“只”多用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13861, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想参观农业区地，看看农民怎么种田。", "corrected_sentence": "我想参观农业区，看看农民怎么种田。", "error_description": "“地”用错：“农业区”是名词，后面不能加结构助词“地”；“地”只修饰动词或形容词，应删去，写成“农业区，”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13862, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "锐增", "is_correct": true, "explanation": "锐增：数量在短时间内急剧增加，与“锐减”互为反义词。"}, {"text": "保持", "is_correct": false, "explanation": "保持：维持原状，不表示数量的增减，与“锐减”没有反义关系。"}, {"text": "存在", "is_correct": false, "explanation": "存在：表示事物有或在，与数量的急剧下降没有反义关系。"}, {"text": "生长", "is_correct": false, "explanation": "生长：指生物发育变大，与数量的急剧下降没有反义关系。"}], "correct_answer": "锐增", "explanations": {"锐增": "锐增：数量在短时间内急剧增加，与“锐减”互为反义词。", "保持": "保持：维持原状，不表示数量的增减，与“锐减”没有反义关系。", "存在": "存在：表示事物有或在，与数量的急剧下降没有反义关系。", "生长": "生长：指生物发育变大，与数量的急剧下降没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13862, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "锐增", "is_correct": true, "explanation": "锐增：数量在短时间内急剧增加，与“锐减”互为反义词。"}, {"text": "搬迁", "is_correct": false, "explanation": "搬迁：指迁移住址或单位，与数量的急剧下降没有反义关系。"}, {"text": "建造", "is_correct": false, "explanation": "建造：指修建房屋或设施，与数量的下降没有反义关系。"}, {"text": "结婚", "is_correct": false, "explanation": "结婚：指男女成为夫妻，与数量的减少无关。"}], "correct_answer": "锐增", "explanations": {"锐增": "锐增：数量在短时间内急剧增加，与“锐减”互为反义词。", "搬迁": "搬迁：指迁移住址或单位，与数量的急剧下降没有反义关系。", "建造": "建造：指修建房屋或设施，与数量的下降没有反义关系。", "结婚": "结婚：指男女成为夫妻，与数量的减少无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13862, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指数量、程度等在短时间内急剧下降或减少。", "primary_collocate": null, "pronunciation": "ruì jiǎn", "ipa": "ɻweɪ˥˩ tɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "例如，在某些高原农业区，野生蜂类数量锐减已导致本地果树坐果率不足三成，迫使农民转向成本高昂的人工授粉，这不仅增加了农业生产的经济负担，也暴露了食物供应链的脆弱性。", "target_word": "锐减", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今年雨水太少，河里的鱼锐减了。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年冬天太冷，这里的游客数量锐减。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂关门后，这个小镇的人口锐减了。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气变冷以后，路上的行人锐减。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虫害让这里的粮食产量锐减了一半。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河的水量曾经锐减过。", "target_word": "锐减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们砍了太多树，森林面积锐减。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "野鸟从一千只锐减到一百只。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济不好，今年买车的人锐减了。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "锐减了", "label": "体标"}, {"form": "锐减过", "label": "体标"}, {"form": "銳減", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数量、程度短时间内急剧减少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2009d73c-bf4e-4a49-ada1-b6ff159c7f51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "锐减", "is_correct": true, "explanation": "锐减：指数量在短时间内急剧下降，与“野生蜂类数量”搭配，符合句意。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”表示数量增多，蜂类增多不会导致坐果率不足三成，与句中的因果相反。"}, {"text": "养殖", "is_correct": false, "explanation": "搭配：“养殖”指饲养动物，不能说“数量养殖”。"}, {"text": "减免", "is_correct": false, "explanation": "语义：“减免”指免除费用、税款或责任，不指数量下降。"}], "explanations": {"锐减": "锐减：指数量在短时间内急剧下降，与“野生蜂类数量”搭配，符合句意。", "增加": "语义：“增加”表示数量增多，蜂类增多不会导致坐果率不足三成，与句中的因果相反。", "养殖": "搭配：“养殖”指饲养动物，不能说“数量养殖”。", "减免": "语义：“减免”指免除费用、税款或责任，不指数量下降。"}, "sentence_index": 0, "correct_answer": "锐减"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几年，城里的自行车数量慢慢锐减了。", "explanation": "这里应该用〈减少〉。锐减强调在短时间内急剧下降，不能与“慢慢”这种渐进的变化搭配。"}, {"text": "这个人的名字锐减了。", "explanation": "这里应该用〈改〉。名字不是数量或程度，不能说锐减，应说“改”。"}, {"text": "这学期我们班只转走了一个同学，人数锐减了。", "explanation": "这里应该用〈减少〉。锐减指数量大幅、急剧下降，只少一个人幅度太小，不能用锐减。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "锐减", "is_correct": true, "explanation": "锐减：表示水量曾经急剧下降，与“曾经……过”的经历义相合。"}, {"text": "注销", "is_correct": false, "explanation": "语义：“注销”指取消登记或账户，不用于水量。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”用于动物，不能说“水量饲养过”。"}, {"text": "录取", "is_correct": false, "explanation": "语义：“录取”指接收入学或入伍，与“水量”不搭。"}], "explanations": {"锐减": "锐减：表示水量曾经急剧下降，与“曾经……过”的经历义相合。", "注销": "语义：“注销”指取消登记或账户，不用于水量。", "饲养": "搭配：“饲养”用于动物，不能说“水量饲养过”。", "录取": "语义：“录取”指接收入学或入伍，与“水量”不搭。"}, "sentence_index": 6, "correct_answer": "锐减"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只鸟去年冬天锐减了。", "explanation": "这里应该用〈消失〉。锐减指一批或总量的数量大幅下降，单只鸟不能锐减。"}, {"text": "飞机开始锐减，准备降落。", "explanation": "这里应该用〈下降〉。锐减只用于数量、程度的减少，不指飞机在空中的位置变化。"}, {"text": "这个孩子的生日锐减了。", "explanation": "这里应该用〈推迟〉。生日不是数量或程度，不能说锐减；时间的变动应说“推迟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那场洪水以后，这个镇的人口被锐减了。", "corrected_sentence": "那场洪水以后，这个镇的人口锐减了。", "error_description": "错误在“锐减”前加了“被”。锐减是不及物动词，表示数量自己急剧下降，不能用“被”构成被动；正确说法是“人口锐减了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年以来，这家工厂的订单锐减着。", "corrected_sentence": "今年以来，这家工厂的订单锐减了。", "error_description": "错误在“锐减”后的“着”。锐减是一次完成的急剧下降，应用“了”表示完成；“着”表示持续状态，与“锐减”不搭。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13863, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13863, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13863, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指果实可供食用的树木。", "primary_collocate": null, "pronunciation": "guǒ shù", "ipa": "kwɔ˨˩˦ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "例如，在某些高原农业区，野生蜂类数量锐减已导致本地果树坐果率不足三成，迫使农民转向成本高昂的人工授粉，这不仅增加了农业生产的经济负担，也暴露了食物供应链的脆弱性。", "target_word": "果树", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "院子里有三棵果树，秋天结很多果子。", "target_word": "果树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天，果树上开满了白色的花。", "target_word": "果树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民在果树下面摘苹果。", "target_word": "果树", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些果树今年结的梨又大又甜。", "target_word": "果树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷每年冬天都给果树剪枝。", "target_word": "果树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上种着很多果树，有桃树也有梨树。", "target_word": "果树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把水浇在果树的根上。", "target_word": "果树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天虫子多，要给果树打药。", "target_word": "果树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年冬天太冷，山下的果树冻坏了。", "target_word": "果树", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "棵", "label": "量词"}, {"form": "果树园", "label": "复合"}, {"form": "果樹", "label": "繁体"}], "register": "中性", "sense_fingerprint": "果实可食用的树木", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2009d73c-bf4e-4a49-ada1-b6ff159c7f51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13863, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "果树", "is_correct": true, "explanation": "guǒ shù：果实可供食用的树木，即本词。"}, {"text": "果蔬", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，“果蔬”指水果和蔬菜，不是树木。"}, {"text": "过熟", "is_correct": false, "explanation": "guò（第四声）与 guǒ（第三声）、shú（第二声）与 shù（第四声）声调不同，“过熟”指果实成熟过度，不是树木。"}, {"text": "国术", "is_correct": false, "explanation": "guó（第二声）与 guǒ（第三声）声调不同，“国术”指中国传统武术，不是树木。"}], "explanations": {"果树": "guǒ shù：果实可供食用的树木，即本词。", "果蔬": "shū（第一声）与 shù（第四声）声调不同，“果蔬”指水果和蔬菜，不是树木。", "过熟": "guò（第四声）与 guǒ（第三声）、shú（第二声）与 shù（第四声）声调不同，“过熟”指果实成熟过度，不是树木。", "国术": "guó（第二声）与 guǒ（第三声）声调不同，“国术”指中国传统武术，不是树木。"}, "sentence_index": null, "correct_answer": "果树"}, "level_3": {"options": [{"text": "果树", "is_correct": true, "explanation": "果树：能结果实的树，与“坐果率”和“果树”的句意相合。"}, {"text": "花卉", "is_correct": false, "explanation": "搭配：“坐果率”是果树结果的指标，花卉一般不说坐果。"}, {"text": "草原", "is_correct": false, "explanation": "语义：草原是草地，不结果实，也没有坐果率。"}, {"text": "蜂群", "is_correct": false, "explanation": "语义：蜂群是蜜蜂的群体，本身不结果，不能说坐果率。"}], "explanations": {"果树": "果树：能结果实的树，与“坐果率”和“果树”的句意相合。", "花卉": "搭配：“坐果率”是果树结果的指标，花卉一般不说坐果。", "草原": "语义：草原是草地，不结果实，也没有坐果率。", "蜂群": "语义：蜂群是蜜蜂的群体，本身不结果，不能说坐果率。"}, "sentence_index": 0, "correct_answer": "果树"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民在果园里摘果树。", "explanation": "这里应该用〈水果〉。果树是树，不能被摘；摘的应该是可以吃的〈水果〉。"}, {"text": "农民在果树里摘苹果。", "explanation": "这里应该用〈果园〉。果树是一棵棵树，不是可以走进去采摘的场所，“在……里”要用〈果园〉。"}, {"text": "农民在一只果树下面摘苹果。", "explanation": "这里应该用〈棵〉。〈只〉多用于动物，果树是植物，应该用量词〈棵〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13863, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "果树", "is_correct": true, "explanation": "果树：山上种的能结果实的树，与“桃树”“梨树”并列相合。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“种”用于植物，不能说种石头，与“种着很多”搭配不合。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器是人造的设备，不能种在山上，与句意不合。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具不能种在山上，与“有桃树也有梨树”的植物并列不合。"}], "explanations": {"果树": "果树：山上种的能结果实的树，与“桃树”“梨树”并列相合。", "石头": "搭配：“种”用于植物，不能说种石头，与“种着很多”搭配不合。", "机器": "语义：机器是人造的设备，不能种在山上，与句意不合。", "家具": "语义：家具不能种在山上，与“有桃树也有梨树”的植物并列不合。"}, "sentence_index": 6, "correct_answer": "果树"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们把果树当零食吃了。", "explanation": "这里应该用〈水果〉。果树是树木，不能当零食吃，孩子们吃的应该是〈水果〉。"}, {"text": "院子里那棵果树其实是松树，从来不结果子。", "explanation": "这里应该用〈树木〉。松树不结果，不能称为果树，只能泛称为〈树木〉。"}, {"text": "这棵果树每天早上都去学校上课。", "explanation": "这里应该用〈学生〉。果树是植物，不会去上学；去上学的应是〈学生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13863, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家门口有一只果树，每年秋天都结很多梨。", "corrected_sentence": "我家门口有一棵果树，每年秋天都结很多梨。", "error_description": "错误在量词：果树是植物，应用量词〈棵〉，〈只〉多用于动物，不能修饰果树。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13863, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秋天，果树里挂满了红苹果。", "corrected_sentence": "秋天，果树上挂满了红苹果。", "error_description": "错误在方位词：苹果挂在树上，应用〈上〉；果树不是可以容纳苹果的容器，不能用〈里〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13864, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13864, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13864, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "果树的花谢了以后，子房逐渐发育成果实的过程。", "primary_collocate": null, "pronunciation": "zuò guǒ", "ipa": "tswo˥˩ kwo˨˩˦", "syllable_count": 2, "sentences": [{"text": "例如，在某些高原农业区，野生蜂类数量锐减，本地果树的花即使开得再多也难以坐果，迫使农民转向成本高昂的人工授粉，这不仅增加了农业生产的经济负担，也暴露了食物供应链的脆弱性。", "target_word": "坐果", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "今年春天下雨太多，苹果树坐果很差。", "target_word": "坐果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷，梨花开了以后很难坐果。", "target_word": "坐果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵桃树花很多，可是坐果不多。", "target_word": "坐果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花期遇到大风，会影响果树坐果。", "target_word": "坐果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在花开时放蜜蜂，帮助果树坐果。", "target_word": "坐果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "樱桃树坐果以后，要少浇水。", "target_word": "坐果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究怎样让葡萄提前坐果。", "target_word": "坐果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种果树坐果早，夏天就能摘果子。", "target_word": "坐果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花粉不够，西瓜很难坐果。", "target_word": "坐果", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "坐果率", "label": "复合"}, {"form": "坐果了", "label": "体标"}], "register": "专业", "sense_fingerprint": "农业术语：果树花谢后子房发育成果实的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca6241f-7cd5-4227-99f1-641110d74754') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13864, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "坐果", "is_correct": true, "explanation": "正确答案：坐果，指花谢后子房发育成果实的过程。"}, {"text": "坐骨", "is_correct": false, "explanation": "gǔ（第三声）与 guǒ（第三声）韵母不同：u 与 o。坐骨意思是骨盆下部的骨头。"}, {"text": "做过", "is_correct": false, "explanation": "guò（第四声）与 guǒ（第三声）声调不同，做过意思是做过某件事。"}, {"text": "坐过", "is_correct": false, "explanation": "guò（第四声）与 guǒ（第三声）声调不同，坐过意思是曾经坐过某物。"}], "explanations": {"坐果": "正确答案：坐果，指花谢后子房发育成果实的过程。", "坐骨": "gǔ（第三声）与 guǒ（第三声）韵母不同：u 与 o。坐骨意思是骨盆下部的骨头。", "做过": "guò（第四声）与 guǒ（第三声）声调不同，做过意思是做过某件事。", "坐过": "guò（第四声）与 guǒ（第三声）声调不同，坐过意思是曾经坐过某物。"}, "sentence_index": null, "correct_answer": "坐果"}, "level_3": {"options": [{"text": "坐果", "is_correct": true, "explanation": "正确：坐果指花谢后子房发育成果实；花开得再多也难以坐果，才需要人工授粉。"}, {"text": "开花", "is_correct": false, "explanation": "语义：句中「花开得再多」说明花已经开了，再说「难以开花」自相矛盾。"}, {"text": "落果", "is_correct": false, "explanation": "语义：落果指果实掉落，与「花开得再多」后的授粉问题无关，句意不通。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：「发芽」用于种子或芽，不能说花「发芽」。"}], "explanations": {"坐果": "正确：坐果指花谢后子房发育成果实；花开得再多也难以坐果，才需要人工授粉。", "开花": "语义：句中「花开得再多」说明花已经开了，再说「难以开花」自相矛盾。", "落果": "语义：落果指果实掉落，与「花开得再多」后的授粉问题无关，句意不通。", "发芽": "搭配：「发芽」用于种子或芽，不能说花「发芽」。"}, "sentence_index": 0, "correct_answer": "坐果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "苹果已经坐果了，可以摘了。", "explanation": "这里应该用〈成熟〉。坐果是花谢后子房刚开始发育，果实还小，不能说已经可以摘；果实成熟了才能摘。"}, {"text": "我家的小狗每年春天都坐果。", "explanation": "这里应该用〈生〉。坐果只用于植物，指花谢后子房发育成果实；动物繁殖说“生”，不能说坐果。"}, {"text": "这些苹果摘下来以后又坐果了。", "explanation": "这里应该用〈长大〉。坐果指果实刚开始发育，摘下来的苹果已经长成，不会再坐果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坐果", "is_correct": true, "explanation": "正确：坐果指花谢后结出果实，樱桃树坐果以后才需要控制浇水。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：树不会睡觉，“睡觉以后要少浇水”没有道理。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：树不会唱歌，与浇水的安排无关。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：出生只用于人和动物，不说果树“出生”。"}], "explanations": {"坐果": "正确：坐果指花谢后结出果实，樱桃树坐果以后才需要控制浇水。", "睡觉": "语义：树不会睡觉，“睡觉以后要少浇水”没有道理。", "唱歌": "语义：树不会唱歌，与浇水的安排无关。", "出生": "搭配：出生只用于人和动物，不说果树“出生”。"}, "sentence_index": 6, "correct_answer": "坐果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次实验的坐果很好。", "explanation": "这里应该用〈结果〉。坐果只指植物花谢后子房发育成果实，不能用来说实验的结果。"}, {"text": "西瓜还没开花，就已经坐果了。", "explanation": "这里应该用〈长出〉。坐果必须在花谢之后，花还没开时只能说果实长出来，不能说坐果。"}, {"text": "我们家的电视机每年都坐果。", "explanation": "这里应该用〈生产〉。坐果只用于植物，指花谢后子房发育成果实；电视机是产品，不能说坐果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年果园的桃树被坐果很多。", "corrected_sentence": "今年果园的桃树坐果很多。", "error_description": "错误：“被坐果”；正确：“坐果”。坐果是不及物动词，不能用“被”构成被动句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "樱桃树今年坐果着很早。", "corrected_sentence": "樱桃树今年坐果很早。", "error_description": "错误：“坐果着”；正确：“坐果很早”。坐果是一次性完成的变化，不能加“着”表示持续。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13865, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13865, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13865, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人工授粉是指通过人工方式将花粉传到植物雌蕊柱头上的技术，用于帮助植物繁殖或提高产量。", "primary_collocate": null, "pronunciation": "rén gōng shòu fěn", "ipa": "ʐən˧˥ kʊŋ˥ ʂou˥˩ fən˨˩˦", "syllable_count": 4, "sentences": [{"text": "例如，在某些高原农业区，野生蜂类数量锐减已导致本地果树坐果率不足三成，迫使农民转向成本高昂的人工授粉，这不仅增加了农业生产的经济负担，也暴露了食物供应链的脆弱性。", "target_word": "人工授粉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "果园里花开了，农民用毛笔做人工授粉。", "target_word": "人工授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有蜜蜂的时候，只能靠人工授粉。", "target_word": "人工授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人工授粉可以让苹果结得更多。", "target_word": "人工授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每年春天都给梨树人工授粉。", "target_word": "人工授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人工授粉需要在花刚开的时候做。", "target_word": "人工授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天蜜蜂少，农民要多做人工授粉。", "target_word": "人工授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猕猴桃花粉少，常常需要人工授粉。", "target_word": "人工授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎样给黄瓜花人工授粉。", "target_word": "人工授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人工授粉比较花时间，但是效果很好。", "target_word": "人工授粉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人工授粉了", "label": "体标"}], "register": "专业", "sense_fingerprint": "农业技术：用人工方法把花粉传到雌蕊柱头上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca6241f-7cd5-4227-99f1-641110d74754') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13865, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人工授粉", "is_correct": true, "explanation": "正确：文中讲野生蜂类减少后农民改用的办法，即人工授粉。"}, {"text": "人工灌溉", "is_correct": false, "explanation": "语义：灌溉不能代替蜜蜂传粉，与前句“野生蜂类数量锐减”的因果不对应。"}, {"text": "人工授精", "is_correct": false, "explanation": "搭配：授精用于动物或人，不用于果树。"}, {"text": "机械收割", "is_correct": false, "explanation": "语义：收割发生在结果之后，不能替代前面的授粉步骤。"}], "explanations": {"人工授粉": "正确：文中讲野生蜂类减少后农民改用的办法，即人工授粉。", "人工灌溉": "语义：灌溉不能代替蜜蜂传粉，与前句“野生蜂类数量锐减”的因果不对应。", "人工授精": "搭配：授精用于动物或人，不用于果树。", "机械收割": "语义：收割发生在结果之后，不能替代前面的授粉步骤。"}, "sentence_index": 0, "correct_answer": "人工授粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母牛要做人工授粉，才能生小牛。", "explanation": "这里应该用〈人工授精〉。授粉只用于植物传粉，动物繁殖应说人工授精。"}, {"text": "妈妈在厨房里给饺子人工授粉。", "explanation": "这里应该用〈包〉。人工授粉是给植物花朵传粉的技术，饺子不是植物，应说包饺子，不能用此词。"}, {"text": "苹果已经长大了，才开始人工授粉。", "explanation": "这里应该用〈施肥〉。人工授粉必须在花期进行，果实长大后做的是施肥等管理，不能称为授粉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13865, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人工授粉", "is_correct": true, "explanation": "正确：下雨天蜜蜂少，农民要多做的就是人工授粉。"}, {"text": "人工放牧", "is_correct": false, "explanation": "语义：放牧与蜜蜂无关，不能替代授粉。"}, {"text": "人工织布", "is_correct": false, "explanation": "语义：织布与果树传粉毫无关系，前句的蜜蜂少无法由它解决。"}, {"text": "人工接生", "is_correct": false, "explanation": "搭配：接生用于人或动物分娩，不用于果树。"}], "explanations": {"人工授粉": "正确：下雨天蜜蜂少，农民要多做的就是人工授粉。", "人工放牧": "语义：放牧与蜜蜂无关，不能替代授粉。", "人工织布": "语义：织布与果树传粉毫无关系，前句的蜜蜂少无法由它解决。", "人工接生": "搭配：接生用于人或动物分娩，不用于果树。"}, "sentence_index": 6, "correct_answer": "人工授粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "养殖场常用人工授粉的方法养鱼苗。", "explanation": "这里应该用〈人工繁殖〉。授粉只用于植物传粉，鱼苗不能用人工授粉。"}, {"text": "西瓜还没开花，就已经人工授粉了。", "explanation": "这里应该用〈嫁接〉。人工授粉要在花开时进行；花还没开时可以做嫁接，但不能说授粉。"}, {"text": "我们把房子人工授粉了。", "explanation": "这里应该用〈装修〉。人工授粉是给植物花朵传粉，房子不是植物，应说装修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民今年给果树人工授粉的。", "corrected_sentence": "农民今年给果树人工授粉。", "error_description": "错误：“人工授粉的”；正确：“人工授粉”。句末的“的”需要名词中心语，单独作谓语时句子不完整，应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年果园里的苹果树都人工授粉着。", "corrected_sentence": "今年果园里的苹果树都人工授粉了。", "error_description": "错误：“人工授粉着”；正确：“人工授粉了”。“了”表示动作已完成，与“都”搭配说明结果，不能用“着”表示持续。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
