INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13866, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13866, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指家庭或个人在生活、教育、医疗等方面需要支付的金钱压力。", "primary_collocate": null, "pronunciation": "jīng jì fù dān", "ipa": "tɕiŋ˥ tɕi˥˩ fu˥˩ tan˥", "syllable_count": 4, "sentences": [{"text": "例如，在某些高原农业区，野生蜂类数量锐减已导致本地果树坐果率不足三成，迫使农民转向成本高昂的人工授粉，这不仅增加了农业生产的经济负担，也暴露了食物供应链的脆弱性。", "target_word": "经济负担", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "孩子上大学，给家里增加了经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看病太贵，成为很多家庭的经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想办法减轻农民的经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子给年轻人带来很大的经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人工作，家里经济负担很重。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "免费午餐减少了学生家庭的经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人生病住院，对孩子是不小的经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打两份工，想减轻父母的经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贷款太多会变成长期的经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "书面", "sense_fingerprint": "家庭或个人在生活、教育、医疗等方面的金钱压力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca6241f-7cd5-4227-99f1-641110d74754') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13866, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经济负担", "is_correct": true, "explanation": "与“增加”搭配，指农业生产中需要承担的金钱压力，符合句中“不仅……也暴露了……”的负面语境。"}, {"text": "地理位置", "is_correct": false, "explanation": "搭配：“增加”说数量或程度，不能用于地理位置。"}, {"text": "历史渊源", "is_correct": false, "explanation": "搭配：“渊源”指事物的来历，不能被“增加”。"}, {"text": "身体素质", "is_correct": false, "explanation": "语义：身体素质指人的体格，与农业生产的成本无关，句意不通。"}], "explanations": {"经济负担": "与“增加”搭配，指农业生产中需要承担的金钱压力，符合句中“不仅……也暴露了……”的负面语境。", "地理位置": "搭配：“增加”说数量或程度，不能用于地理位置。", "历史渊源": "搭配：“渊源”指事物的来历，不能被“增加”。", "身体素质": "语义：身体素质指人的体格，与农业生产的成本无关，句意不通。"}, "sentence_index": 0, "correct_answer": "经济负担"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府为贫困学生提供了很大的经济负担。", "explanation": "这里应该用〈经济援助〉。经济负担指需要自己承担的金钱压力，不能“提供”给别人；给予金钱帮助要说经济援助。"}, {"text": "这次投资让公司获得了很大的经济负担。", "explanation": "这里应该用〈经济收益〉。“获得”搭配收益、利益，经济负担是需要承受的压力，不能获得。"}, {"text": "政府给农户发放了很多经济负担。", "explanation": "这里应该用〈经济补贴〉。“发放”的是补贴、款项，经济负担是压力，不是可以发放的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经济负担", "is_correct": true, "explanation": "与“减少”搭配，指家庭承受的金钱压力，免费午餐能减轻它，符合句意。"}, {"text": "饮食习惯", "is_correct": false, "explanation": "搭配：“减少”用于数量，习惯不说减少，应说改变或培养。"}, {"text": "烹饪技术", "is_correct": false, "explanation": "搭配：“减少”不能用于技术，且与免费午餐减轻金钱压力的作用无关。"}, {"text": "营养价值", "is_correct": false, "explanation": "语义：免费午餐的作用是帮家庭减轻负担，“减少营养价值”与句意相反。"}], "explanations": {"经济负担": "与“减少”搭配，指家庭承受的金钱压力，免费午餐能减轻它，符合句意。", "饮食习惯": "搭配：“减少”用于数量，习惯不说减少，应说改变或培养。", "烹饪技术": "搭配：“减少”不能用于技术，且与免费午餐减轻金钱压力的作用无关。", "营养价值": "语义：免费午餐的作用是帮家庭减轻负担，“减少营养价值”与句意相反。"}, "sentence_index": 6, "correct_answer": "经济负担"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在银行工作，经济负担很好。", "explanation": "这里应该用〈经济状况〉。“很好”形容经济状况，经济负担指需要承受的压力，不能用“很好”来形容。"}, {"text": "这些年他把经济负担全部存进了银行。", "explanation": "这里应该用〈存款〉。经济负担是需要承受的压力，不能存进银行；存进银行的是存款。"}, {"text": "这笔奖金让我们家的经济负担收获了很多。", "explanation": "这里应该用〈收益〉。“收获”多用于庄稼、成果，经济负担是压力，不能收获；应说经济收益增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔学费对他的家庭是一笔不小经济负担。", "corrected_sentence": "这笔学费对他的家庭是一笔不小的经济负担。", "error_description": "“不小”与“经济负担”之间漏了结构助词“的”，应说“不小的经济负担”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔医药费对我们家来说是一只沉重的经济负担。", "corrected_sentence": "这笔医药费对我们家来说是一种沉重的经济负担。", "error_description": "“经济负担”的量词应用“种”；“只”用于动物等，不能修饰这个抽象名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
