INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13867, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "脆弱性指事物不坚固、容易受到破坏或伤害的特性。", "primary_collocate": null, "pronunciation": "cuì ruò xìng", "ipa": "tsʰuei̯˥˩ ʐuo̯˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "例如，在某些高原农业区，野生蜂类数量锐减已导致本地果树坐果率不足三成，迫使农民转向成本高昂的人工授粉，这不仅增加了农业生产的经济负担，也暴露了食物供应链的脆弱性。", "target_word": "脆弱性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这次停电暴露了城市电网的脆弱性。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家提醒，网络系统的脆弱性可能带来安全风险。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情让很多国家看到了经济的脆弱性。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在检查软件有没有安全方面的脆弱性。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过度依赖一个供应商，会加剧企业的脆弱性。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场洪水让人们认识到生态系统的脆弱性。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金融危机显示出银行体系的脆弱性。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在访谈中谈到了人类生命的脆弱性。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多备份几份数据，可以降低系统的脆弱性。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "脆弱", "label": "词根"}], "register": "书面", "sense_fingerprint": "系统、体系或社会等不够坚固，容易受到冲击和破坏的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca6241f-7cd5-4227-99f1-641110d74754') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13867, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脆弱性", "is_correct": true, "explanation": "指系统不坚固、容易受损的特性，与“暴露了……的”搭配，符合句意。"}, {"text": "口感", "is_correct": false, "explanation": "语义：供应链没有口感，“暴露口感”句意不通。"}, {"text": "节奏", "is_correct": false, "explanation": "搭配：“暴露”用于问题或缺陷，“节奏”不能被暴露。"}, {"text": "味道", "is_correct": false, "explanation": "语义：供应链不具备味道，句子不通。"}], "explanations": {"脆弱性": "指系统不坚固、容易受损的特性，与“暴露了……的”搭配，符合句意。", "口感": "语义：供应链没有口感，“暴露口感”句意不通。", "节奏": "搭配：“暴露”用于问题或缺陷，“节奏”不能被暴露。", "味道": "语义：供应链不具备味道，句子不通。"}, "sentence_index": 0, "correct_answer": "脆弱性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆新车的脆弱性很高，开起来很放心。", "explanation": "这里应该用〈安全性〉。脆弱性指容易受损的特性，说“脆弱性很高”意思相反；表示车子可靠要说安全性。"}, {"text": "这个供水系统的脆弱性很好，很少出问题。", "explanation": "这里应该用〈稳定性〉。“很好”指系统稳固，而脆弱性指容易受损；形容稳固要说稳定性。"}, {"text": "这种金属的脆弱性很好，不容易断。", "explanation": "这里应该用〈韧性〉。脆弱性指容易受损，“不容易断”描述的是韧性好，要说韧性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13867, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脆弱性", "is_correct": true, "explanation": "指系统在冲击下容易受损的特性，与“认识到……的”搭配，符合句意。"}, {"text": "口音", "is_correct": false, "explanation": "语义：生态系统没有口音，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”指人或动物身体的重量，生态系统不适用。"}, {"text": "嗓门", "is_correct": false, "explanation": "语域：“嗓门”是口语词，与书面的“认识到”不协调；且生态系统没有嗓门。"}], "explanations": {"脆弱性": "指系统在冲击下容易受损的特性，与“认识到……的”搭配，符合句意。", "口音": "语义：生态系统没有口音，句意不通。", "体重": "体貌：“体重”指人或动物身体的重量，生态系统不适用。", "嗓门": "语域：“嗓门”是口语词，与书面的“认识到”不协调；且生态系统没有嗓门。"}, "sentence_index": 6, "correct_answer": "脆弱性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次改进让系统的脆弱性更高，运行却更稳。", "explanation": "这里应该用〈稳定性〉。脆弱性越高越容易受损，与“运行却更稳”矛盾；说系统可靠要用稳定性。"}, {"text": "工程师发现这个系统有一项突出的优点，就是它的脆弱性。", "explanation": "这里应该用〈稳定性〉。脆弱性指容易受损，不是优点；说系统的优点要用稳定性。"}, {"text": "这份报告指出这个城市的交通系统脆弱性很好，几乎不会出事。", "explanation": "这里应该用〈可靠性〉。“很好”形容系统稳固，而脆弱性指容易受损；形容可靠要说可靠性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13867, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次事故暴露出这家工厂安全管理的很脆弱性。", "corrected_sentence": "这次事故暴露出这家工厂安全管理的脆弱性。", "error_description": "“脆弱性”是名词，前面不能加程度副词“很”；应去掉“很”，说“的脆弱性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13867, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次洪水暴露出防洪系统的一只脆弱性。", "corrected_sentence": "这次洪水暴露出防洪系统的一种脆弱性。", "error_description": "“脆弱性”的量词应用“种”；“只”用于动物，不能修饰抽象名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13868, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "思考", "is_correct": false, "explanation": "无关：“思考”与“相互依存”没有反义关系。"}, {"text": "独立", "is_correct": true, "explanation": "反义：“独立”与“相互依存”相对，一个是彼此依赖，一个是自主不依赖。"}, {"text": "游泳", "is_correct": false, "explanation": "无关：“游泳”与“相互依存”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "无关：“旅行”与“相互依存”没有反义关系。"}], "correct_answer": "独立", "explanations": {"思考": "无关：“思考”与“相互依存”没有反义关系。", "独立": "反义：“独立”与“相互依存”相对，一个是彼此依赖，一个是自主不依赖。", "游泳": "无关：“游泳”与“相互依存”没有反义关系。", "旅行": "无关：“旅行”与“相互依存”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13868, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阅读", "is_correct": false, "explanation": "无关：“阅读”与“相互依存”没有反义关系。"}, {"text": "独立", "is_correct": true, "explanation": "反义：“独立”与“相互依存”相对，指不依靠他人、自主存在。"}, {"text": "跳舞", "is_correct": false, "explanation": "无关：“跳舞”与“相互依存”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”与“相互依存”没有反义关系。"}], "correct_answer": "独立", "explanations": {"阅读": "无关：“阅读”与“相互依存”没有反义关系。", "独立": "反义：“独立”与“相互依存”相对，指不依靠他人、自主存在。", "跳舞": "无关：“跳舞”与“相互依存”没有反义关系。", "散步": "无关：“散步”与“相互依存”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13868, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "互相依赖，彼此依靠，缺一不可。", "primary_collocate": null, "pronunciation": "xiāng hù yī cún", "ipa": "ɕjɑŋ˥ xu˥˩ i˥ tsʰuən˧˥", "syllable_count": 4, "sentences": [{"text": "生物多样性的维系并非仅关乎物种数量的多寡，更在于物种间相互依存关系的稳健性。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "森林里的动物和植物相互依存。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂靠花粉生存，花朵靠蜜蜂传粉，两者相互依存。", "target_word": "相互依存", "complexity_tier": "T3", "furigana": "mì fēng kào huā fěn shēng cún, huā duǒ kào mì fēng chuán fěn, liǎng zhě xiāng hù yī cún.", "sentence_source": "generated"}, {"text": "在这个小岛上，人和自然相互依存。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界各国的经济相互依存，谁也离不开谁。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司和客户之间应该相互依存，共同发展。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种小鱼生活在一起，相互依存。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，家庭成员之间是相互依存的。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市和乡村相互依存，不能分开看。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩多年来相互依存，感情很深。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "事物、群体或系统之间互相依赖、缺一不可", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca6241f-7cd5-4227-99f1-641110d74754') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相互隔绝", "is_correct": false, "explanation": "语义：若物种间是相互隔绝的关系，就谈不上“维系”生物多样性，与句意相悖。"}, {"text": "相互依存", "is_correct": true, "explanation": "正确。“相互依存关系”指物种彼此依赖、缺一不可，与“维系”生物多样性的语境相符。"}, {"text": "相互爱慕", "is_correct": false, "explanation": "搭配：“爱慕”指人之间的情感，不能说物种之间相互爱慕。"}, {"text": "相互凑合", "is_correct": false, "explanation": "语域：“凑合”是口语，含“将就”之意，与书面的科学语境和“稳健性”的评价不合。"}], "explanations": {"相互隔绝": "语义：若物种间是相互隔绝的关系，就谈不上“维系”生物多样性，与句意相悖。", "相互依存": "正确。“相互依存关系”指物种彼此依赖、缺一不可，与“维系”生物多样性的语境相符。", "相互爱慕": "搭配：“爱慕”指人之间的情感，不能说物种之间相互爱慕。", "相互凑合": "语域：“凑合”是口语，含“将就”之意，与书面的科学语境和“稳健性”的评价不合。"}, "sentence_index": 0, "correct_answer": "相互依存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两派观点相互依存，争论不休。", "explanation": "这里应该用〈对立〉。相互依存强调彼此离不开、缺一不可，两派观点彼此排斥、争论不休，是对立关系，应说〈对立〉。"}, {"text": "两位同事在工作中相互依存，彼此从不联系。", "explanation": "这里应该用〈独立〉。相互依存强调彼此离不开，两位同事从不联系，说明各自独立，应说〈独立〉。"}, {"text": "两支球队相互依存，争夺冠军。", "explanation": "这里应该用〈竞争〉。相互依存表示彼此离不开，与“争夺冠军”的对抗关系正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相互签订", "is_correct": false, "explanation": "搭配：“签订”用于合同、协议，不能说小鱼之间相互签订。"}, {"text": "相互依存", "is_correct": true, "explanation": "正确。两种小鱼生活在一起，彼此依赖、缺一不可，与“相互依存”的意思相符。"}, {"text": "相互分离", "is_correct": false, "explanation": "语义：既然“生活在一起”，就不能说相互分离，与前句矛盾。"}, {"text": "相互考核", "is_correct": false, "explanation": "搭配：“考核”多用于人与工作之间，不能用于小鱼之间。"}], "explanations": {"相互签订": "搭配：“签订”用于合同、协议，不能说小鱼之间相互签订。", "相互依存": "正确。两种小鱼生活在一起，彼此依赖、缺一不可，与“相互依存”的意思相符。", "相互分离": "语义：既然“生活在一起”，就不能说相互分离，与前句矛盾。", "相互考核": "搭配：“考核”多用于人与工作之间，不能用于小鱼之间。"}, "sentence_index": 6, "correct_answer": "相互依存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "邻居们相互依存，多年来互不往来。", "explanation": "这里应该用〈疏远〉。相互依存强调彼此离不开、关系密切，邻居多年互不往来，是关系疏远，应说〈疏远〉。"}, {"text": "两位画家相互依存，经常交流画技。", "explanation": "这里应该用〈切磋〉。相互依存强调彼此离不开，两位画家经常交流画技，是互相切磋，不是依存关系，应说〈切磋〉。"}, {"text": "这两块磁铁相互依存。", "explanation": "这里应该用〈相互吸引〉。相互依存指彼此离不开、缺一不可；磁铁之间只有相互吸引或排斥的作用，没有依赖关系，应说〈相互吸引〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校和家长应该很相互依存，共同教育孩子。", "corrected_sentence": "学校和家长应该相互依存，共同教育孩子。", "error_description": "“相互”是副词，前面不能再加程度副词“很”；应去掉“很”，说“应该相互依存”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个村子被相互依存，谁也离不开谁。", "corrected_sentence": "这两个村子相互依存，谁也离不开谁。", "error_description": "错误：多加了“被”。“相互依存”是不及物的状态动词，不能用被字句，应去掉“被”，说“相互依存”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13869, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "数量", "is_correct": false, "explanation": "无关：“数量”与“稳健性”没有反义关系。"}, {"text": "脆弱性", "is_correct": true, "explanation": "反义：“脆弱性”与“稳健性”相对，指系统容易受干扰、不可靠。"}, {"text": "温度", "is_correct": false, "explanation": "无关：“温度”与“稳健性”没有反义关系。"}, {"text": "颜色", "is_correct": false, "explanation": "无关：“颜色”与“稳健性”没有反义关系。"}], "correct_answer": "脆弱性", "explanations": {"数量": "无关：“数量”与“稳健性”没有反义关系。", "脆弱性": "反义：“脆弱性”与“稳健性”相对，指系统容易受干扰、不可靠。", "温度": "无关：“温度”与“稳健性”没有反义关系。", "颜色": "无关：“颜色”与“稳健性”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13869, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "体积", "is_correct": false, "explanation": "无关：“体积”与“稳健性”没有反义关系。"}, {"text": "脾气", "is_correct": false, "explanation": "无关：“脾气”与“稳健性”没有反义关系。"}, {"text": "脆弱性", "is_correct": true, "explanation": "反义：“脆弱性”与“稳健性”相对，指系统容易受干扰、不可靠。"}, {"text": "香味", "is_correct": false, "explanation": "无关：“香味”与“稳健性”没有反义关系。"}], "correct_answer": "脆弱性", "explanations": {"体积": "无关：“体积”与“稳健性”没有反义关系。", "脾气": "无关：“脾气”与“稳健性”没有反义关系。", "脆弱性": "反义：“脆弱性”与“稳健性”相对，指系统容易受干扰、不可靠。", "香味": "无关：“香味”与“稳健性”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13869, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指系统或事物在遇到变化或干扰时，仍然能保持稳定、可靠的能力。", "primary_collocate": null, "pronunciation": "wěn jiàn xìng", "ipa": "wən˨˩ tɕjɛn˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "生物多样性的维系并非仅关乎物种数量的多寡，更在于物种间相互依存关系的稳健性。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这家银行的稳健性受到投资者的信任。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想提高财务的稳健性，减少风险。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家评价这座桥的结构稳健性很高。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要测试模型在新数据上的稳健性。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济的稳健性让这个国家顺利度过了危机。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的算法应该有很强的稳健性，不怕干扰。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投资专家更重视基金的稳健性，而不是高收益。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套系统遇到故障时仍能运行，稳健性很好。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了增强稳健性，团队设计了两套方案。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "稳健", "label": "词根"}], "register": "书面", "sense_fingerprint": "系统、模型或关系在变化和干扰下仍保持稳定可靠的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca6241f-7cd5-4227-99f1-641110d74754') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13869, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用来描述关系的性质，与“稳健”的评价不搭配。"}, {"text": "稳健性", "is_correct": true, "explanation": "正确。“关系的稳健性”指关系在干扰下仍能保持稳定，与“维系”生物多样性的语境相符。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”不能用来形容关系，说“关系的速度”不通。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“气味”不能用来形容关系，句意不通。"}], "explanations": {"颜色": "搭配：“颜色”不能用来描述关系的性质，与“稳健”的评价不搭配。", "稳健性": "正确。“关系的稳健性”指关系在干扰下仍能保持稳定，与“维系”生物多样性的语境相符。", "速度": "搭配：“速度”不能用来形容关系，说“关系的速度”不通。", "气味": "搭配：“气味”不能用来形容关系，句意不通。"}, "sentence_index": 0, "correct_answer": "稳健性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的情绪稳健性很差，一点小事就发脾气。", "explanation": "这里应该用〈稳定〉。稳健性指系统在干扰下保持可靠，描述人的情绪应说〈稳定〉。"}, {"text": "这位医生的稳健性很高，病人都信任他。", "explanation": "这里应该用〈可靠〉。稳健性指系统抵抗干扰的能力，评价人的可信度应说〈可靠〉。"}, {"text": "这次考试的稳健性很高，许多人都没及格。", "explanation": "这里应该用〈难度〉。稳健性指系统遇到干扰仍能保持可靠，形容考试难易应说〈难度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13869, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体积", "is_correct": false, "explanation": "搭配：“体积”指物体所占的空间，不能用来描述算法的“很强”性质。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：算法没有脾气，“很强的脾气”与句意不合。"}, {"text": "稳健性", "is_correct": true, "explanation": "正确。“很强的稳健性”指算法在干扰下仍然可靠，与“不怕干扰”相呼应。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：算法不能有香味，“很强的香味”说不通。"}], "explanations": {"体积": "搭配：“体积”指物体所占的空间，不能用来描述算法的“很强”性质。", "脾气": "语义：算法没有脾气，“很强的脾气”与句意不合。", "稳健性": "正确。“很强的稳健性”指算法在干扰下仍然可靠，与“不怕干扰”相呼应。", "香味": "搭配：算法不能有香味，“很强的香味”说不通。"}, "sentence_index": 6, "correct_answer": "稳健性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的稳健性很大，一顿能吃三碗饭。", "explanation": "这里应该用〈食量〉。稳健性指系统遇到干扰仍能保持可靠，形容一顿吃多少应说〈食量〉。"}, {"text": "这首歌的稳健性很强，听起来很悦耳。", "explanation": "这里应该用〈动听〉。稳健性指系统抵抗干扰的可靠能力，形容歌曲好听应说〈动听〉。"}, {"text": "我们用稳健性来测量温度。", "explanation": "这里应该用〈温度计〉。稳健性指系统抵抗干扰的可靠能力，不是测量仪器，测量温度应用〈温度计〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套系统在电压波动时仍具有一条很强的稳健性，能正常工作。", "corrected_sentence": "这套系统在电压波动时仍具有一种很强的稳健性，能正常工作。", "error_description": "错误：量词用错。“稳健性”是抽象名词，量词应用“种”；“条”多用于细长之物，不能修饰此处的抽象名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13869, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个模型在数据有噪声时仍保持很稳健性，能给出可靠结果。", "corrected_sentence": "这个模型在数据有噪声时仍保持了稳健性，能给出可靠结果。", "error_description": "错误：用了“很”代替“了”。“很”不能修饰名词“稳健性”，此处表示完成的“了”应紧跟动词“保持”，说“保持了稳健性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
