INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13871, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13871, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "指面对逆境时能够抵抗并适应，不轻易被困难打倒。", "primary_collocate": null, "pronunciation": "kàng nì", "ipa": "kʰɑŋ˥˩ ni˥˩", "syllable_count": 2, "sentences": [{"text": "蜜蜂在这一网络中扮演着“生态枢纽”的角色——它们穿梭于不同植物之间，促进基因流动，增强植物种群的适应潜力，从而提升整个生态系统的抗逆能力。", "target_word": "抗逆", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "孩子要学会抗逆，不能一遇到困难就哭。", "target_word": "抗逆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种草很抗逆，干旱时也能活。", "target_word": "抗逆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的植物特别抗逆。", "target_word": "抗逆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民选了更抗逆的水稻品种。", "target_word": "抗逆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些树苗抗逆，冬天也不会冻死。", "target_word": "抗逆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玉米需要抗逆，才能在干旱中长大。", "target_word": "抗逆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经历过失败的人，往往更加抗逆。", "target_word": "抗逆", "complexity_tier": "T3", "furigana": "jīng lì guò shī bài de rén, wǎng wǎng gèng jiā kàng nì.", "sentence_source": "generated"}, {"text": "这个品种的小麦抗逆，风雨再大也不倒。", "target_word": "抗逆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们在失败后抗逆。", "target_word": "抗逆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抗逆力", "label": "复合词"}, {"form": "抗逆性", "label": "复合词"}, {"form": "抗逆能力", "label": "复合词"}], "register": "书面", "sense_fingerprint": "面对逆境能抵抗并适应，不被困难打倒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51a2ec1-03d3-479d-a707-0e526ca5f366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13871, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抗逆", "is_correct": true, "explanation": "正确：抗逆指抵抗逆境的能力，与“提升生态系统的抗逆能力”相合。"}, {"text": "脆弱", "is_correct": false, "explanation": "语义：脆弱指容易受损，与“提升”的积极意思相反。"}, {"text": "衰退", "is_correct": false, "explanation": "语义：衰退指逐渐减弱，与“提升”的方向相反。"}, {"text": "饥饿", "is_correct": false, "explanation": "搭配：饥饿是身体状态，不是能力，不能用来修饰“能力”。"}], "explanations": {"抗逆": "正确：抗逆指抵抗逆境的能力，与“提升生态系统的抗逆能力”相合。", "脆弱": "语义：脆弱指容易受损，与“提升”的积极意思相反。", "衰退": "语义：衰退指逐渐减弱，与“提升”的方向相反。", "饥饿": "搭配：饥饿是身体状态，不是能力，不能用来修饰“能力”。"}, "sentence_index": 0, "correct_answer": "抗逆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子特别抗逆，用了十年也没坏。", "explanation": "这里应该用〈耐用〉。抗逆指生物或人面对逆境时的抵抗适应力，形容器物经久耐用要用耐用。"}, {"text": "这座桥特别抗逆，建了一百年。", "explanation": "这里应该用〈坚固〉。抗逆用于生物或人，形容桥梁结实要用坚固。"}, {"text": "这块玻璃特别抗逆，轻轻一碰就碎。", "explanation": "这里应该用〈易碎〉。句中说玻璃轻碰就碎，应描述为易碎，抗逆说的是抵抗逆境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13871, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抗逆", "is_correct": true, "explanation": "正确：抗逆指抵抗逆境的能力，玉米需要它才能在干旱中长大，语义相合。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：冷静指心态平和，植物不需要冷静，与干旱中长大的语境不合。"}, {"text": "幸福", "is_correct": false, "explanation": "搭配：幸福是人的心理感受，不用来说植物需要什么。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：温柔指性格或态度，与玉米在干旱中生长的需要不相干。"}], "explanations": {"抗逆": "正确：抗逆指抵抗逆境的能力，玉米需要它才能在干旱中长大，语义相合。", "冷静": "语义：冷静指心态平和，植物不需要冷静，与干旱中长大的语境不合。", "幸福": "搭配：幸福是人的心理感受，不用来说植物需要什么。", "温柔": "语义：温柔指性格或态度，与玉米在干旱中生长的需要不相干。"}, "sentence_index": 6, "correct_answer": "抗逆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一遇到挫折就抗逆，马上放弃了比赛。", "explanation": "这里应该用〈认输〉。抗逆是迎难而上的态度，遇挫折就放弃应说认输。"}, {"text": "面对压力，他选择抗逆，躲进了房间。", "explanation": "这里应该用〈逃避〉。抗逆指迎着困难应对，躲开困难应说逃避。"}, {"text": "在困难面前，他抗逆地低下了头。", "explanation": "这里应该用〈屈服〉。抗逆指不被困难压倒，低头屈服是相反的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13871, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种仙人掌被抗逆，沙漠里也能长。", "corrected_sentence": "这种仙人掌很抗逆，沙漠里也能长。", "error_description": "错误形式：“被抗逆”，用了被动标记“被”，而“抗逆”不能用于被动式。正确形式：“很抗逆”，用程度副词“很”修饰“抗逆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13871, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面对挫折，他没有放弃，而是坚定的抗逆，继续努力。", "corrected_sentence": "面对挫折，他没有放弃，而是坚定地抗逆，继续努力。", "error_description": "错误形式：“坚定的抗逆”，用了“的”字。正确形式：“坚定地抗逆”。修饰动词的状语要用“地”，不用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
