INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13875, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指某种生物或事物完全消失，不再存在。", "primary_collocate": null, "pronunciation": "miè jué", "ipa": "mjɛ˥˩ tɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "研究人员警告，若这片湿地继续被开发，许多依赖它生存的物种可能在数十年内彻底灭绝。", "target_word": "灭绝", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "恐龙在很久以前就灭绝了。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鸟已经灭绝了几十年。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类的活动让很多动物灭绝。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不保护，这种鱼就会灭绝。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家说，猛犸象一万年前灭绝。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么恐龙会灭绝？", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种老虎在中国已经灭绝。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灭绝的动物不会再回来。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本关于灭绝动物的书。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "灭绝了", "label": "体标"}, {"form": "灭绝过", "label": "体标"}, {"form": "灭绝率", "label": "复合"}], "register": "书面", "sense_fingerprint": "生物或事物完全消失不再存在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51a2ec1-03d3-479d-a707-0e526ca5f366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13875, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灭绝", "is_correct": true, "explanation": "正确：灭绝指物种彻底消失，与“彻底”搭配，符合濒危物种可能全部消失的警示语境。"}, {"text": "复活", "is_correct": false, "explanation": "语义：复活指死而重新活过来，与栖地被开发、物种面临消失的警示语境相反。"}, {"text": "栖息", "is_correct": false, "explanation": "语义：栖息指动物停留在某处生活，“彻底栖息”意义不通，也不符合威胁语境。"}, {"text": "繁衍", "is_correct": false, "explanation": "语义：繁衍指生物繁殖后代，与物种面临彻底消失的警示语境相反。"}], "explanations": {"灭绝": "正确：灭绝指物种彻底消失，与“彻底”搭配，符合濒危物种可能全部消失的警示语境。", "复活": "语义：复活指死而重新活过来，与栖地被开发、物种面临消失的警示语境相反。", "栖息": "语义：栖息指动物停留在某处生活，“彻底栖息”意义不通，也不符合威胁语境。", "繁衍": "语义：繁衍指生物繁殖后代，与物种面临彻底消失的警示语境相反。"}, "sentence_index": 0, "correct_answer": "灭绝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他灭绝了三天，大家都很着急。", "explanation": "这里应该用〈失踪〉。“灭绝”指物种或事物整体不再存在，人暂时不见不能用，应说“失踪”。"}, {"text": "这次实验灭绝了，我们只好重新做。", "explanation": "这里应该用〈失败〉。实验没有成功应说“失败”，“灭绝”只指生物或事物彻底消失。"}, {"text": "这种药吃了以后就灭绝了。", "explanation": "这里应该用〈失效〉。药物不再起作用应说“失效”，药并没有消失，不能说“灭绝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灭绝", "is_correct": true, "explanation": "正确：这里说恐龙整个种类不复存在，“为什么恐龙会灭绝”是合理的问法。"}, {"text": "说话", "is_correct": false, "explanation": "配价：说话要求说话者具备语言能力，恐龙不具备，“为什么恐龙会说话”与句子主语不匹配。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：恐龙不会唱歌，与句中“恐龙”这一对象不符，句子说不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：恐龙不会跳舞，“为什么恐龙会跳舞”与恐龙的生物特征相矛盾。"}], "explanations": {"灭绝": "正确：这里说恐龙整个种类不复存在，“为什么恐龙会灭绝”是合理的问法。", "说话": "配价：说话要求说话者具备语言能力，恐龙不具备，“为什么恐龙会说话”与句子主语不匹配。", "唱歌": "语义：恐龙不会唱歌，与句中“恐龙”这一对象不符，句子说不通。", "跳舞": "语义：恐龙不会跳舞，“为什么恐龙会跳舞”与恐龙的生物特征相矛盾。"}, "sentence_index": 6, "correct_answer": "灭绝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的猫昨天灭绝了。", "explanation": "这里应该用〈走失〉。一只猫走丢只是个体不见了，“灭绝”指整个种类不复存在，应说“走失”。"}, {"text": "他的成绩这次彻底灭绝了。", "explanation": "这里应该用〈下降〉。成绩变差应说“下降”，“灭绝”只指生物或事物彻底消失。"}, {"text": "夏天到了，气温一直在灭绝。", "explanation": "这里应该用〈升高〉。气温上升应说“升高”，“灭绝”不能用于气温这类数值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种蝴蝶已经很灭绝了。", "corrected_sentence": "这种蝴蝶已经灭绝了。", "error_description": "错误在“灭绝”前多加了程度副词“很”。“灭绝”是动词，不能受“很”修饰，应改为“这种蝴蝶已经灭绝了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种鸟灭绝了了。", "corrected_sentence": "这种鸟灭绝了。", "error_description": "错误在“灭绝”后的“了”重复了一次。动词后只需一个“了”，应改为“这种鸟灭绝了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13876, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13876, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13876, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指事物最初就有的、非人工加工或移植的本来状态。", "primary_collocate": null, "pronunciation": "yuán shēng", "ipa": "ɥɛn˧˥ ʂɤŋ˥˥", "syllable_count": 2, "sentences": [{"text": "部分前沿研究指出，建立生态廊道、恢复原生植被、实施精准农业管理以及制定跨区域的授粉保护政策，可能是缓解危机的有效路径。", "target_word": "原生", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这片山上有很多原生树木。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原生森林对小动物很重要。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想保护这里的原生环境。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花是原生植物，只分布在这一带。", "target_word": "原生", "complexity_tier": "T3", "furigana": "zhè zhǒng huā shì yuán shēng zhí wù, zhǐ fēn bù zài zhè yí dài.", "sentence_source": "generated"}, {"text": "公园里种着一些原生草。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原生植物比外来植物更适合这里。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的原生鸟越来越少了。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们找出原生的树。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河边还有原生的湿地。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原生植物", "label": "复合"}, {"form": "原生态", "label": "复合"}], "register": "书面", "sense_fingerprint": "最初就有、非人工移植的本来状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51a2ec1-03d3-479d-a707-0e526ca5f366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13876, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原生", "is_correct": true, "explanation": "正确：句子说恢复本来就有的植被，“原生植被”指原本生长在当地的植被，语境正合。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：陌生指不熟悉，与“恢复”所表示的回到原来状态相矛盾。"}, {"text": "稀少", "is_correct": false, "explanation": "语义：稀少指数量很少，与恢复植被的目标（重新茂盛）正好相反。"}, {"text": "整洁", "is_correct": false, "explanation": "搭配：整洁多用来形容环境或物品，不能说“恢复整洁植被”。"}], "explanations": {"原生": "正确：句子说恢复本来就有的植被，“原生植被”指原本生长在当地的植被，语境正合。", "陌生": "语义：陌生指不熟悉，与“恢复”所表示的回到原来状态相矛盾。", "稀少": "语义：稀少指数量很少，与恢复植被的目标（重新茂盛）正好相反。", "整洁": "搭配：整洁多用来形容环境或物品，不能说“恢复整洁植被”。"}, "sentence_index": 0, "correct_answer": "原生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些花是原生培育的。", "explanation": "这里应该用〈人工〉。“原生”指本来的状态、非人工加工，不能修饰“培育”，应说“人工培育”。"}, {"text": "他有原生的音乐天赋。", "explanation": "这里应该用〈先天〉。“原生”只说事物本来的状态，不用于说人的天赋，应说“先天的音乐天赋”。"}, {"text": "这种鸟是原生的，人们把它从国外带进来。", "explanation": "这里应该用〈外来〉。“原生”指本来就在当地，从国外带进来的鸟应说“外来”，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原生", "is_correct": true, "explanation": "正确：比较的是本地本来就有的植物与外来植物，“原生植物”正合句意。"}, {"text": "外来", "is_correct": false, "explanation": "语义：前后都用“外来”，比较的双方自相矛盾，“外来植物比外来植物”说不通。"}, {"text": "幼稚", "is_correct": false, "explanation": "搭配：幼稚通常用来形容人的想法或行为，不能用来修饰植物。"}, {"text": "荒凉", "is_correct": false, "explanation": "语义：荒凉指没有生机的环境，与“更适合这里”所表达的适应性相矛盾。"}], "explanations": {"原生": "正确：比较的是本地本来就有的植物与外来植物，“原生植物”正合句意。", "外来": "语义：前后都用“外来”，比较的双方自相矛盾，“外来植物比外来植物”说不通。", "幼稚": "搭配：幼稚通常用来形容人的想法或行为，不能用来修饰植物。", "荒凉": "语义：荒凉指没有生机的环境，与“更适合这里”所表达的适应性相矛盾。"}, "sentence_index": 6, "correct_answer": "原生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座楼是原生建成的。", "explanation": "这里应该用〈新建〉。楼房是人工建造的，“原生”只指非人工的本来状态，不能用于建造。"}, {"text": "这只羊是原生克隆出来的。", "explanation": "这里应该用〈人工〉。克隆出的羊是人工复制的，“原生”指本来的状态、非人工加工，不能修饰“克隆”。"}, {"text": "这只碗是原生手工做的。", "explanation": "这里不该用〈原生〉。碗是人工制作的，“原生”指本来的状态、非人工加工，与“人工制作”矛盾，应去掉“原生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座岛上的原生森林都是人工种植的。", "corrected_sentence": "这座岛上的原生森林都是自然生长的。", "error_description": "错误在“原生”与“人工种植”相矛盾：原生指本来就有、非人工加工或移植，森林不能既是原生的又是人工种植的。应改为“自然生长的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河边有一片原生的湿地，是从外地移植过来的。", "corrected_sentence": "这条河边有一片原生的湿地，是本来就长在这里的。", "error_description": "错误在“原生”与“移植”相矛盾：原生指非人工移植的本来状态，句中却说是从外地移植来的。应改为“本来就长在这里的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
