INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13877, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13877, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "保护区是为保护自然环境、野生动物或生态系统而划定的特殊区域。", "primary_collocate": null, "pronunciation": "bǎo hù qū", "ipa": "paʊ˨˩ xu˥˩ tɕʰy˥", "syllable_count": 3, "sentences": [{"text": "某些国家已启动“授粉者保护区”计划，通过立法限制特定神经毒性农药的使用，并鼓励农场主采用生态友好型耕作方式。", "target_word": "保护区", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这片森林是国家建立的自然保护区。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护区里有很多珍贵的野生动物。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府划定了新的保护区，禁止人们打猎。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客不能随便进入保护区的核心地带。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个保护区主要保护大熊猫的栖息地。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在保护区工作了十年，负责监测鸟类。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护湿地，当地建了一个保护区。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护区内严禁砍树和捕鱼。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在保护区里发现了一种新植物。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "自然保护区", "label": "复合"}, {"form": "国家级保护区", "label": "复合"}], "register": "中性", "sense_fingerprint": "为保护生态和野生动物而划定的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16167f6b-a703-4ef3-812d-318e93e86d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13877, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保护区", "is_correct": true, "explanation": "正确。“授粉者保护区”指为保护授粉昆虫而划定的区域，与后文“限制农药使用”的语境相符。"}, {"text": "农药", "is_correct": false, "explanation": "语义：“授粉者农药计划”与前句“限制农药的使用”自相矛盾，计划的对象不能是农药。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂与“生态友好型耕作”和保护授粉者的目标相反，句意不通。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“授粉者银行”不成词，“启动计划”的对象应是保护性的区域，不能是银行。"}], "explanations": {"保护区": "正确。“授粉者保护区”指为保护授粉昆虫而划定的区域，与后文“限制农药使用”的语境相符。", "农药": "语义：“授粉者农药计划”与前句“限制农药的使用”自相矛盾，计划的对象不能是农药。", "工厂": "语义：工厂与“生态友好型耕作”和保护授粉者的目标相反，句意不通。", "银行": "搭配：“授粉者银行”不成词，“启动计划”的对象应是保护性的区域，不能是银行。"}, "sentence_index": 0, "correct_answer": "保护区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只保护区很大，我们走了一天。", "explanation": "量词错误：〈只〉用于动物，保护区是地方，应用〈个〉或〈片〉。"}, {"text": "这个保护区每天处理几百吨垃圾。", "explanation": "这里应该用〈垃圾站〉。保护区是为保护生态而划定的区域，不负责处理垃圾。"}, {"text": "妈妈把钱放在保护区里。", "explanation": "这里应该用〈保险柜〉。保护区是为保护生态而划定的区域，不是存放钱财的器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13877, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保护区", "is_correct": true, "explanation": "正确。“他在保护区工作”指在生态保护地从事监测工作，与“监测鸟类”相符。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：餐厅与“监测鸟类”无关，鸟类监测需要野外或研究场所。"}, {"text": "超市", "is_correct": false, "explanation": "搭配：“监测鸟类”不与超市搭配，超市里没有需要监测的野生鸟类。"}, {"text": "商场", "is_correct": false, "explanation": "语义：商场不是开展生态监测的场所，句意不通。"}], "explanations": {"保护区": "正确。“他在保护区工作”指在生态保护地从事监测工作，与“监测鸟类”相符。", "餐厅": "语义：餐厅与“监测鸟类”无关，鸟类监测需要野外或研究场所。", "超市": "搭配：“监测鸟类”不与超市搭配，超市里没有需要监测的野生鸟类。", "商场": "语义：商场不是开展生态监测的场所，句意不通。"}, "sentence_index": 6, "correct_answer": "保护区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "保护区里住着很多病人。", "explanation": "这里应该用〈医院〉。保护区是生态保护地，不收治病人。"}, {"text": "我们参观了一位保护区。", "explanation": "量词错误：〈位〉用于人，保护区是地方，应用〈个〉或〈片〉。"}, {"text": "他是我们学校最好的保护区。", "explanation": "这里应该用〈人才〉。保护区是生态保护地，不能用来指优秀的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13877, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府在山区设立了一只保护区。", "corrected_sentence": "政府在山区设立了一个保护区。", "error_description": "量词错误：“只”用于动物，保护区是地方，应改为“个”，说“一个保护区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13877, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片草原已经被划为一本保护区了。", "corrected_sentence": "这片草原已经被划为一个保护区了。", "error_description": "量词错误：“本”用于书册，保护区是地方，应改为“个”，说“一个保护区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
