INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13878, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "毒性指物质对生物体造成损害的性质或程度。", "primary_collocate": null, "pronunciation": "dú xìng", "ipa": "tu˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "某些国家已启动“授粉者保护区”计划，通过立法限制特定神经毒性农药的使用，并鼓励农场主采用生态友好型耕作方式。", "target_word": "毒性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种农药的毒性很强，使用时要小心。", "target_word": "毒性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在测试新药的毒性。", "target_word": "毒性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验表明，这种塑料的毒性很低。", "target_word": "毒性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蘑菇的毒性和种类有关。", "target_word": "毒性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水里这种物质的毒性很强，会伤害鱼类。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "shuǐ lǐ zhè zhǒng wù zhì de dú xìng hěn qiáng, huì shāng hài yú lèi.", "sentence_source": "generated"}, {"text": "煮过以后，这种豆子的毒性会消失。", "target_word": "毒性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种蛇的毒性不高。", "target_word": "毒性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的废水有很强的毒性。", "target_word": "毒性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员比较了两种药的毒性大小。", "target_word": "毒性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "毒性反应", "label": "复合"}, {"form": "毒性物质", "label": "复合"}], "register": "中性", "sense_fingerprint": "物质对生物体造成损害的性质或程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16167f6b-a703-4ef3-812d-318e93e86d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13878, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毒性", "is_correct": true, "explanation": "正确。“神经毒性”指农药对神经系统的损害性质，与“限制使用”的语境相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“神经价格农药”不成立，价格与限制农药使用的语境无关。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与限制农药使用无关，句中强调的是农药的危害性。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“神经味道”不成词，“神经”之后应接表示危害性的词。"}], "explanations": {"毒性": "正确。“神经毒性”指农药对神经系统的损害性质，与“限制使用”的语境相符。", "价格": "语义：“神经价格农药”不成立，价格与限制农药使用的语境无关。", "颜色": "语义：颜色与限制农药使用无关，句中强调的是农药的危害性。", "味道": "搭配：“神经味道”不成词，“神经”之后应接表示危害性的词。"}, "sentence_index": 0, "correct_answer": "毒性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他喝下了毒性。", "explanation": "这里应该用〈毒药〉。毒性是性质，不能被喝下，说“喝下毒药”。"}, {"text": "他的毒性很大，说话总是伤人。", "explanation": "语义：毒性指物质对生物的损害性质，不用来形容人的性格，形容人应说“恶毒”或“毒舌”。"}, {"text": "我们称了一斤毒性。", "explanation": "量词错误：〈斤〉是重量单位，毒性是抽象性质，不能用重量单位称量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毒性", "is_correct": true, "explanation": "正确。“这种豆子的毒性”指豆子对生物的损害性质，煮过以后会消失，与句意相符。"}, {"text": "名字", "is_correct": false, "explanation": "语义：煮过以后豆子的名字不会消失，句意不通。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“消失”不与“重量”搭配，重量会减少而不会消失。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：豆子没有年龄会消失的说法，“年龄”与煮过的语境无关。"}], "explanations": {"毒性": "正确。“这种豆子的毒性”指豆子对生物的损害性质，煮过以后会消失，与句意相符。", "名字": "语义：煮过以后豆子的名字不会消失，句意不通。", "重量": "搭配：“消失”不与“重量”搭配，重量会减少而不会消失。", "年龄": "语义：豆子没有年龄会消失的说法，“年龄”与煮过的语境无关。"}, "sentence_index": 6, "correct_answer": "毒性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为吸食毒性而生病了。", "explanation": "这里应该用〈毒品〉。毒性是性质，不能被吸食，吸食的是毒品。"}, {"text": "他的毒性越来越深，已经戒不掉了。", "explanation": "这里说的是〈毒瘾〉。毒性指物质的损害性质，不能用来指成瘾。"}, {"text": "这一公里的毒性很低。", "explanation": "量词错误：〈公里〉是长度单位，毒性是抽象性质，不能用长度计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种化学品有一块毒性。", "corrected_sentence": "这种化学品有一定的毒性。", "error_description": "量词错误：“块”用于块状物，“毒性”是抽象名词，不能用“块”计量，应说“一定的毒性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员已经测出了这种物质的一粒毒性。", "corrected_sentence": "研究人员已经测出了这种物质的毒性。", "error_description": "量词错误：“粒”用于颗粒，“毒性”是抽象名词，不能加量词“一粒”，应直接说“这种物质的毒性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
