INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13879, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "拥有并经营农场的个人或企业，负责农场的种植、养殖等生产活动。", "primary_collocate": null, "pronunciation": "nóng chǎng zhǔ", "ipa": "nʊŋ˧˥ tʂʰɑŋ˨˩ tʂu˨˩", "syllable_count": 3, "sentences": [{"text": "某些国家已启动“授粉者保护区”计划，通过立法限制特定神经毒性农药的使用，并鼓励农场主采用生态友好型耕作方式。", "target_word": "农场主", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这位农场主有三百头牛和两百只羊。", "target_word": "农场主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场主每天早上五点就起床工作。", "target_word": "农场主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位农场主把新收的玉米卖给了商店。", "target_word": "农场主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场主雇了十几个工人帮忙收苹果。", "target_word": "农场主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他父亲是个农场主，家里种了很多麦子。", "target_word": "农场主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场主担心今年的雨水太少。", "target_word": "农场主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场主请兽医给生病的马看病。", "target_word": "农场主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多农场主开始用机器种地。", "target_word": "农场主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位农场主在山下经营着一片大果园。", "target_word": "农场主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "拥有并经营农场的人或企业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16167f6b-a703-4ef3-812d-318e93e86d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13879, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "农场主", "is_correct": true, "explanation": "农场主是拥有并经营农场的人，正是句中被鼓励采用生态耕作方式的对象。"}, {"text": "消费者", "is_correct": false, "explanation": "语义：消费者不从事耕作，不能采用生产性的耕作方式。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客不参与农田耕作，“采用耕作方式”与其身份不符。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“耕作方式”通常由种地的人采用，“工厂”不能与“采用耕作方式”搭配。"}], "explanations": {"农场主": "农场主是拥有并经营农场的人，正是句中被鼓励采用生态耕作方式的对象。", "消费者": "语义：消费者不从事耕作，不能采用生产性的耕作方式。", "游客": "语义：游客不参与农田耕作，“采用耕作方式”与其身份不符。", "工厂": "搭配：“耕作方式”通常由种地的人采用，“工厂”不能与“采用耕作方式”搭配。"}, "sentence_index": 0, "correct_answer": "农场主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去农场主玩，摘草莓。", "explanation": "这里应该用〈农场〉。“农场”是可以去玩的地方，“农场主”指经营农场的人，不能当作场所。"}, {"text": "他是我们工厂的农场主，管理着一千多名工人。", "explanation": "这里应该用〈厂长〉。“农场主”只指经营农场的人，不能用于工厂的管理者。"}, {"text": "这家餐厅的农场主很有经验，客人越来越多。", "explanation": "这里应该用〈老板〉。“农场主”指经营农场的人，餐厅的经营者应称“老板”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13879, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "农场主", "is_correct": true, "explanation": "农场主经营农田，最担心的就是今年雨水不足。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器没有心理活动，不能“担心”雨水。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不会“担心”。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“担心”的主语须是有意识的人或群体，“椅子”不能充当。"}], "explanations": {"农场主": "农场主经营农田，最担心的就是今年雨水不足。", "机器": "语义：机器没有心理活动，不能“担心”雨水。", "石头": "语义：石头没有生命，不会“担心”。", "椅子": "搭配：“担心”的主语须是有意识的人或群体，“椅子”不能充当。"}, "sentence_index": 6, "correct_answer": "农场主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是农场主，每天在教室里给学生上课。", "explanation": "这里应该用〈老师〉。“农场主”指拥有并经营农场的人，不能用来指在教室里授课的人。"}, {"text": "他是农场主，每天帮饭店送外卖，挣钱养家。", "explanation": "这里应该用〈外卖员〉。“农场主”指经营农场的人，给饭店送外卖的是“外卖员”。"}, {"text": "他是农场主，每个月从别人那里领工资，负责给牛挤奶。", "explanation": "这里应该用〈雇工〉。“农场主”是自己拥有并经营农场的人，靠工资给别人干活的是“雇工”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13879, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农场主牛吃了很多草。", "corrected_sentence": "农场主的牛吃了很多草。", "error_description": "漏掉定语标记“的”：“农场主的牛”表示“农场主拥有的牛”，应说“农场主的牛”，不能说“农场主牛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13879, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我认识两农场主，他们都很热情。", "corrected_sentence": "我认识两位农场主，他们都很热情。", "error_description": "数量词后缺少量词：“两”加指人的名词要有量词，应说“两位农场主”，不能说“两农场主”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13880, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "敌对", "is_correct": true, "explanation": "敌对指关系对立、互相敌视，与“友好”意思相反，是反义词。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软形容质地，与“友好”之间没有反义关系。"}, {"text": "遥远", "is_correct": false, "explanation": "遥远指距离或时间长，与“友好”不构成反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、不模糊，与“友好”不构成反义关系。"}], "correct_answer": "敌对", "explanations": {"敌对": "敌对指关系对立、互相敌视，与“友好”意思相反，是反义词。", "柔软": "柔软形容质地，与“友好”之间没有反义关系。", "遥远": "遥远指距离或时间长，与“友好”不构成反义关系。", "清楚": "清楚指明白、不模糊，与“友好”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13880, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "敌对", "is_correct": true, "explanation": "敌对指双方互相对立，态度相反，是“友好”的反义词。"}, {"text": "冷静", "is_correct": false, "explanation": "冷静指镇定、不慌乱，与“友好”没有反义关系。"}, {"text": "干燥", "is_correct": false, "explanation": "干燥指缺少水分，与“友好”不构成反义关系。"}, {"text": "辽阔", "is_correct": false, "explanation": "辽阔指广阔，与“友好”不构成反义关系。"}], "correct_answer": "敌对", "explanations": {"敌对": "敌对指双方互相对立，态度相反，是“友好”的反义词。", "冷静": "冷静指镇定、不慌乱，与“友好”没有反义关系。", "干燥": "干燥指缺少水分，与“友好”不构成反义关系。", "辽阔": "辽阔指广阔，与“友好”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13880, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容人与人之间的关系亲近、和睦，乐于相处。", "primary_collocate": null, "pronunciation": "yǒu hǎo", "ipa": "joʊ˨˩ xɑʊ˨˩", "syllable_count": 2, "sentences": [{"text": "这次会谈让两国的关系变得更加友好。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的邻居对人很友好。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国一直保持着友好的关系。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们对新来的同学很友好。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他友好地向我们打招呼。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国和日本是友好邻邦。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们和邻居的关系一直很友好。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们友好地握了握手。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家人对客人非常友好。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个城市的市长见面时态度很友好。", "target_word": "友好", "complexity_tier": "T3", "furigana": "yǒu hǎo", "sentence_source": "generated"}], "morphological_forms": [{"form": "友好地", "label": "状语形式"}, {"form": "不友好", "label": "否定形式"}], "register": "通用", "sense_fingerprint": "人与人或国与国之间关系亲近和睦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16167f6b-a703-4ef3-812d-318e93e86d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "友好", "is_correct": true, "explanation": "“友好”指两国关系亲近和睦，与“会谈”后关系改善的语境相符。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”指缺少水分，不能用来形容两国的关系。"}, {"text": "迟钝", "is_correct": false, "explanation": "语义：“迟钝”指反应慢，与两国关系的改善无关。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“关系”不能用“明亮”来形容，句意不通。"}], "explanations": {"友好": "“友好”指两国关系亲近和睦，与“会谈”后关系改善的语境相符。", "干燥": "语义：“干燥”指缺少水分，不能用来形容两国的关系。", "迟钝": "语义：“迟钝”指反应慢，与两国关系的改善无关。", "明亮": "搭配：“关系”不能用“明亮”来形容，句意不通。"}, "sentence_index": 0, "correct_answer": "友好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们是一对恋人，每天友好地手拉手散步。", "explanation": "这里应该用〈亲密〉。“友好”只表示关系和睦、乐于相处，不能描写恋人之间亲密的感情。"}, {"text": "他对我很友好，从不打招呼。", "explanation": "这里应该用〈冷淡〉。“友好”表示亲近、愿意相处，与“从不打招呼”的态度互相矛盾。"}, {"text": "两个邻居常常吵架，关系很友好。", "explanation": "这里应该用〈紧张〉。“友好”表示和睦、乐于相处，与经常吵架的关系互相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "友好", "is_correct": true, "explanation": "“友好”形容邻里之间关系亲近和睦，与“一直”相符。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“关系”不能用“很高”来形容。"}, {"text": "笔直", "is_correct": false, "explanation": "搭配：“笔直”形容线条或姿态，不能用来形容“关系”。"}, {"text": "迟钝", "is_correct": false, "explanation": "语义：“迟钝”指反应慢，与人际关系的亲近和睦无关，句意不通。"}], "explanations": {"友好": "“友好”形容邻里之间关系亲近和睦，与“一直”相符。", "高": "搭配：“关系”不能用“很高”来形容。", "笔直": "搭配：“笔直”形容线条或姿态，不能用来形容“关系”。", "迟钝": "语义：“迟钝”指反应慢，与人际关系的亲近和睦无关，句意不通。"}, "sentence_index": 6, "correct_answer": "友好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们俩一直很友好，谁也不愿意跟对方说话。", "explanation": "这里应该用〈冷漠〉。“友好”表示亲近和睦，与“谁也不愿意跟对方说话”的态度互相矛盾。"}, {"text": "那个孩子很友好，见了生人就躲在妈妈身后。", "explanation": "这里应该用〈害羞〉。“友好”表示对人亲近、乐于相处，与见生人就躲起来的样子互相矛盾。"}, {"text": "两家公司为了争夺客户，经常在市场上互相友好。", "explanation": "这里应该用〈竞争〉。“友好”表示关系和睦，与为争夺客户而互相较量的关系互相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们友好的和新同学打招呼。", "corrected_sentence": "孩子们友好地和新同学打招呼。", "error_description": "状语标记用错：修饰动词“打招呼”要用“地”，“友好的”是定语形式，应说“友好地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们之间的关系一直没友好。", "corrected_sentence": "他们之间的关系一直不友好。", "error_description": "否定词用错：形容词“友好”的否定要用“不”，应说“不友好”，不能说“没友好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
