INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13885, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从某处吸收或取得（有益的东西）。", "primary_collocate": null, "pronunciation": "jí qǔ", "ipa": "tɕi˧˥ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种从自然智慧中汲取灵感的跨学科探索，进一步凸显了保护昆虫多样性的深远意义。", "target_word": "汲取", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们要从失败中汲取教训。", "target_word": "汲取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从书里汲取了很多知识。", "target_word": "汲取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植物的根从土里汲取水分和养分。", "target_word": "汲取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人应该向前辈汲取经验。", "target_word": "汲取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从旅行中汲取灵感，写了一首歌。", "target_word": "汲取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司从过去的错误中汲取了经验。", "target_word": "汲取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艺术家常常从大自然汲取灵感。", "target_word": "汲取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要汲取历史的教训。", "target_word": "汲取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们正汲取着知识的营养。", "target_word": "汲取", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "汲取了", "label": "体标"}, {"form": "汲取过", "label": "体标"}, {"form": "汲取着", "label": "体标"}], "register": "书面语", "sense_fingerprint": "从某处吸收、获取有益的东西，如经验、教训、养分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa05ba3-543a-4f57-9e53-db31b3068c9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13885, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "汲取", "is_correct": true, "explanation": "jí qǔ，意思是从某处吸收有益的东西。"}, {"text": "截取", "is_correct": false, "explanation": "jié 与 jí 韵母不同（多一个 e），意思是截下一段，不是吸收有益的东西。"}, {"text": "计取", "is_correct": false, "explanation": "jì 与 jí 声调不同（第四声与第二声），意思是按标准计算后收取。"}, {"text": "极区", "is_correct": false, "explanation": "jí qū 与 jí qǔ 的第二音节声调不同（qū 为第一声），意思是南北极附近的地区。"}], "explanations": {"汲取": "jí qǔ，意思是从某处吸收有益的东西。", "截取": "jié 与 jí 韵母不同（多一个 e），意思是截下一段，不是吸收有益的东西。", "计取": "jì 与 jí 声调不同（第四声与第二声），意思是按标准计算后收取。", "极区": "jí qū 与 jí qǔ 的第二音节声调不同（qū 为第一声），意思是南北极附近的地区。"}, "sentence_index": null, "correct_answer": "汲取"}, "level_3": {"options": [{"text": "排放", "is_correct": false, "explanation": "语义：“排放”指向外排出废气、废水，与“灵感”的获得无关。"}, {"text": "汲取", "is_correct": true, "explanation": "汲取：从自然智慧中吸收有益的内容，与“灵感”搭配，句意通顺。"}, {"text": "倾倒", "is_correct": false, "explanation": "搭配：“倾倒”说的是把液体倒出，不能说从智慧中倾倒灵感。"}, {"text": "吞食", "is_correct": false, "explanation": "语义：“吞食”指把食物咽下，用在抽象的灵感上不合道理。"}], "explanations": {"排放": "语义：“排放”指向外排出废气、废水，与“灵感”的获得无关。", "汲取": "汲取：从自然智慧中吸收有益的内容，与“灵感”搭配，句意通顺。", "倾倒": "搭配：“倾倒”说的是把液体倒出，不能说从智慧中倾倒灵感。", "吞食": "语义：“吞食”指把食物咽下，用在抽象的灵感上不合道理。"}, "sentence_index": 0, "correct_answer": "汲取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生从病人的手臂上汲取了一管血液做化验。", "explanation": "这里应该用〈抽取〉。汲取 指吸收有益的东西，抽血样本要用“抽取”，不能说“汲取”。"}, {"text": "他通过考试汲取了入学资格。", "explanation": "这里应该用〈获取〉。汲取 的对象是知识、经验、养分这类可以吸收的内容，资格要用“获取”。"}, {"text": "敌军汲取了这座城市。", "explanation": "这里应该用〈夺取〉。汲取 是吸收有益之物，强行占有城市要用“夺取”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收割", "is_correct": false, "explanation": "语义：“收割”指割取庄稼，用在经验上不合。"}, {"text": "擦拭", "is_correct": false, "explanation": "搭配：“擦拭”针对桌面、玻璃等表面，不能用于经验，与“经验”不搭。"}, {"text": "汲取", "is_correct": true, "explanation": "汲取：从错误中吸收有益的经验，与“经验”搭配，句意通顺。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”多用于火、热情等，不能用于经验。"}], "explanations": {"收割": "语义：“收割”指割取庄稼，用在经验上不合。", "擦拭": "搭配：“擦拭”针对桌面、玻璃等表面，不能用于经验，与“经验”不搭。", "汲取": "汲取：从错误中吸收有益的经验，与“经验”搭配，句意通顺。", "点燃": "搭配：“点燃”多用于火、热情等，不能用于经验。"}, "sentence_index": 6, "correct_answer": "汲取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次考试汲取了一个好成绩，老师很高兴。", "explanation": "这里应该用〈取得〉。汲取 指吸收有益的内容，考试成绩要说“取得”，不能说“汲取”。"}, {"text": "学校向每位学生汲取了一笔学费。", "explanation": "这里应该用〈收取〉。汲取 指吸收有益的内容，向学生收费要用“收取”，不能说“汲取”。"}, {"text": "这家餐厅汲取了很多顾客的好评。", "explanation": "这里应该用〈赢得〉。汲取 指吸收有益的内容，好评是别人给予的，要用“赢得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正在汲取了经验。", "corrected_sentence": "我们正在汲取经验。", "error_description": "“汲取”后的“了”与“正在”矛盾：“正在”表示动作进行中，不能与表示完成的“了”同用。应去掉“了”，说“正在汲取经验”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他汲取了过经验。", "corrected_sentence": "他汲取过经验。", "error_description": "“汲取”的体标错位：“了”与“过”不能这样连用，应去掉“了”，说“汲取过经验”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13886, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13886, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13886, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指在创作或思考过程中突然产生的巧妙想法或创作冲动。", "primary_collocate": null, "pronunciation": "líng gǎn", "ipa": "liŋ˧˥ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种从自然智慧中汲取灵感的跨学科探索，进一步凸显了保护昆虫多样性的深远意义。", "target_word": "灵感", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "画家在海边散步时，突然有了新的灵感。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家常常从生活中找到写作的灵感。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完这首歌，他的创作灵感来了。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师的灵感来自一片落叶。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有灵感的时候，她就出去走走。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位诗人的灵感总是在夜里出现。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，读书能给我们带来灵感。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿起笔，把脑子里的灵感写了下来。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的画给了设计师很多灵感。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "创作灵感", "label": "复合"}], "register": "中性", "sense_fingerprint": "创作或思考时突然出现的巧妙想法或冲动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1e44a9-8db8-4cc7-8878-02df51e2b7e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13886, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "噪音", "is_correct": false, "explanation": "语义：“汲取”的对象应是有益的东西，“噪音”与智慧无关，句子不通。"}, {"text": "灵感", "is_correct": true, "explanation": "正确：“汲取灵感”指从事物中获得创作上的启发，与“自然智慧”“跨学科探索”的语境相符。"}, {"text": "烟雾", "is_correct": false, "explanation": "搭配：“汲取”常接养分、经验、知识等，不与“烟雾”搭配。"}, {"text": "废墟", "is_correct": false, "explanation": "语义：废墟是毁坏后的遗迹，与“从自然智慧中汲取”的积极含义相反。"}], "explanations": {"噪音": "语义：“汲取”的对象应是有益的东西，“噪音”与智慧无关，句子不通。", "灵感": "正确：“汲取灵感”指从事物中获得创作上的启发，与“自然智慧”“跨学科探索”的语境相符。", "烟雾": "搭配：“汲取”常接养分、经验、知识等，不与“烟雾”搭配。", "废墟": "语义：废墟是毁坏后的遗迹，与“从自然智慧中汲取”的积极含义相反。"}, "sentence_index": 0, "correct_answer": "灵感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他认真制定了一个灵感，准备明天开始执行。", "explanation": "这里应该用〈计划〉。“制定”和“执行”用于计划、方案，“灵感”指突然产生的想法，不能被制定或执行。"}, {"text": "这位老人的灵感很善良。", "explanation": "这里应该用〈灵魂〉。“善良”形容人的品性，“灵感”指创作时突然产生的想法，不能这样形容。"}, {"text": "这个灵感很重，我拿不动。", "explanation": "这里应该用〈东西〉。“重”和“拿不动”指有形实体的重量，“灵感”是抽象的想法，没有重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "语义：“工资”是报酬，不会“总是在夜里出现”，与诗人创作的语境不合。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“出现”不与“体重”搭配，句子所说的是诗人的创作，而非身体指标。"}, {"text": "灵感", "is_correct": true, "explanation": "正确：“诗人的灵感”指创作时突然冒出的想法，“总是在夜里出现”符合语境。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”与诗人的创作无关，“在夜里出现”也不通顺。"}], "explanations": {"工资": "语义：“工资”是报酬，不会“总是在夜里出现”，与诗人创作的语境不合。", "体重": "搭配：“出现”不与“体重”搭配，句子所说的是诗人的创作，而非身体指标。", "灵感": "正确：“诗人的灵感”指创作时突然冒出的想法，“总是在夜里出现”符合语境。", "账单": "语义：“账单”与诗人的创作无关，“在夜里出现”也不通顺。"}, "sentence_index": 6, "correct_answer": "灵感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他读完那本书，把灵感还给了图书馆。", "explanation": "这里应该用〈资料〉。“还”用于归还借来的东西，“灵感”是自己突然产生的想法，不能被归还。"}, {"text": "他的灵感很敏捷。", "explanation": "这里应该用〈思维〉。“敏捷”形容思考的速度，“灵感”不能用来这样形容。"}, {"text": "他和家人的灵感很疏远。", "explanation": "这里应该用〈感情〉。“疏远”指人与人之间的关系，“灵感”不能用来指人际关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在海边坐了很久，一条灵感也没有。", "corrected_sentence": "她在海边坐了很久，一点灵感也没有。", "error_description": "错误：“灵感”前的量词用了“条”。“条”用于细长的东西，灵感应用“点”（或“丝”“股”）计量。正确应为“一点灵感”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年就有了过这样的灵感。", "corrected_sentence": "他去年就有过这样的灵感。", "error_description": "错误：“有过”表示经历过，句中又加了“了”，形成“有了过”的重复。正确应为“有过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
