INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13887, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "指最终归结到最根本的、最核心的问题或原因上。", "primary_collocate": null, "pronunciation": "guī gēn jié dǐ", "ipa": "kweɪ˥ kən˥ tɕjɛ˧˥ ti˨˩˦", "syllable_count": 4, "sentences": [{"text": "归根结底，蜜蜂的命运与人类的粮食安全紧密交织。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "归根结底，学好汉语要靠每天练习。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他失败了，归根结底是因为不努力。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问题很多，归根结底只有一个原因。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "归根结底，健康比钱更重要。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事归根结底是我们的责任。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家吵了半天，归根结底是为了钱。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间，归根结底要互相相信。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "归根结底，好成绩来自努力。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车，归根结底是车太多了。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "归根到底", "label": "变体"}], "register": "书面", "sense_fingerprint": "最终归结到最根本的原因或问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1e44a9-8db8-4cc7-8878-02df51e2b7e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13887, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶然", "is_correct": false, "explanation": "语义：“偶然”指碰巧、不是必然，与“归结到最根本的原因”的含义相反。"}, {"text": "幸好", "is_correct": false, "explanation": "语义：“幸好”表示侥幸的庆幸，与后文对根本原因的说明不相符。"}, {"text": "归根结底", "is_correct": true, "explanation": "正确：“归根结底”引出最根本的原因或结论，与后文“蜜蜂的命运与粮食安全紧密交织”相符。"}, {"text": "猛然", "is_correct": false, "explanation": "搭配：“猛然”多用于突然的动作或发现，不与这种归纳性的论断搭配。"}], "explanations": {"偶然": "语义：“偶然”指碰巧、不是必然，与“归结到最根本的原因”的含义相反。", "幸好": "语义：“幸好”表示侥幸的庆幸，与后文对根本原因的说明不相符。", "归根结底": "正确：“归根结底”引出最根本的原因或结论，与后文“蜜蜂的命运与粮食安全紧密交织”相符。", "猛然": "搭配：“猛然”多用于突然的动作或发现，不与这种归纳性的论断搭配。"}, "sentence_index": 0, "correct_answer": "归根结底"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们先讨论，归根结底再投票。", "explanation": "这里应该用〈最后〉。“归根结底”表示归结到根本原因，不表示先后顺序。"}, {"text": "今天天气很好，归根结底我们去公园吧。", "explanation": "这里应该用〈那么〉。“归根结底”用于归纳根本原因，不用于提出建议。"}, {"text": "他认真复习，归根结底考了满分。", "explanation": "这里应该用〈结果〉。“归根结底”指向根本原因，不用来陈述一个结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13887, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与“归结到根本是为了钱”的论断不相符。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，句子说的是原因，不是突发的事件。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示催促尽快行动，不能用来引出根本原因，与“是为了钱”搭配不通。"}, {"text": "归根结底", "is_correct": true, "explanation": "正确：“归根结底”引出吵架的根本原因，与“吵了半天”“是为了钱”的语境相符。"}], "explanations": {"立刻": "语义：“立刻”表示马上，与“归结到根本是为了钱”的论断不相符。", "忽然": "语义：“忽然”表示突然发生，句子说的是原因，不是突发的事件。", "赶紧": "语义：“赶紧”表示催促尽快行动，不能用来引出根本原因，与“是为了钱”搭配不通。", "归根结底": "正确：“归根结底”引出吵架的根本原因，与“吵了半天”“是为了钱”的语境相符。"}, "sentence_index": 6, "correct_answer": "归根结底"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们归根结底去北京玩。", "explanation": "这里应该用〈暑假〉。“归根结底”表示归结到根本，不表示时间。"}, {"text": "他一方面很忙，归根结底又很有钱。", "explanation": "这里应该用〈另一方面〉。“归根结底”只用于归结根本，不用于并列的两个方面。"}, {"text": "我们班归根结底有三十个人。", "explanation": "这里应该用〈一共〉。“归根结底”表示归结根本，不用于统计数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13887, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次失败，归根结底我的责任。", "corrected_sentence": "这次失败，归根结底是我的责任。", "error_description": "错误：“归根结底”后漏掉判断词“是”，写成“归根结底我的责任”。正确应为“归根结底是我的责任”，“归根结底”引出的判断句需要“是”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13887, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们之间的矛盾很多，归根结底，归根结底是为了面子。", "corrected_sentence": "他们之间的矛盾很多，归根结底是为了面子。", "error_description": "错误：“归根结底”重复出现了两次。只需在句中出现一次，正确应为“归根结底是为了面子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
