INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13888, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人生中一切遭遇，包括生死、贫富、祸福等，常被看作由某种力量预先决定的发展趋势。", "primary_collocate": null, "pronunciation": "mìng yùn", "ipa": "miŋ˥˩ yn˥˩", "syllable_count": 2, "sentences": [{"text": "归根结底，蜜蜂的命运与人类的粮食安全紧密交织。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他相信努力可以改变自己的命运。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小女孩的命运让大家很难过。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "命运有时很奇怪，让我们遇到了彼此。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想把自己的命运交给别人。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写了一家人的命运。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人觉得命运是天生的。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争改变了这座城市的命运。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人不应该向命运低头。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次机会改变了她的命运。", "target_word": "命运", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "命运共同体", "label": "复合"}], "register": "中性", "sense_fingerprint": "人一生的遭遇与被预先决定的发展趋势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1e44a9-8db8-4cc7-8878-02df51e2b7e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13888, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "命运", "is_correct": true, "explanation": "正确：「命运」指人一生的遭遇，与「交织」搭配，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的外观特征，不能与粮食安全「紧密交织」，句子讲的是蜜蜂的遭遇。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格属于人的心理特征，不能用来说蜜蜂与粮食安全的关系。"}, {"text": "体型", "is_correct": false, "explanation": "体貌：体型指身体的外形，不能与「与人类的粮食安全紧密交织」搭配。"}], "explanations": {"命运": "正确：「命运」指人一生的遭遇，与「交织」搭配，符合句意。", "颜色": "语义：颜色是事物的外观特征，不能与粮食安全「紧密交织」，句子讲的是蜜蜂的遭遇。", "性格": "语义：性格属于人的心理特征，不能用来说蜜蜂与粮食安全的关系。", "体型": "体貌：体型指身体的外形，不能与「与人类的粮食安全紧密交织」搭配。"}, "sentence_index": 0, "correct_answer": "命运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试我的命运特别好，题目都会做。", "explanation": "这里应该用〈运气〉。命运指一个人一生的遭遇，不用来形容一次考试的顺利程度。"}, {"text": "这次旅行是我最难忘的命运。", "explanation": "这里应该用〈经历〉。命运指被预先决定的人生走向，不用来指一次旅行。"}, {"text": "他的命运很开朗，喜欢和朋友一起玩。", "explanation": "这里应该用〈性格〉。命运指人生的遭遇或走向，不能用来形容一个人的性格，应说「性格很开朗」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "命运", "is_correct": true, "explanation": "正确：「天生的」可以修饰命运，说明它被看作先天决定，符合句意。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是后天的制度，不是「天生的」。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：「天生的」修饰能力、性格，不修饰学费。"}, {"text": "课程", "is_correct": false, "explanation": "语义：课程是后天学习的内容，不能说「天生的」。"}], "explanations": {"命运": "正确：「天生的」可以修饰命运，说明它被看作先天决定，符合句意。", "考试": "语义：考试是后天的制度，不是「天生的」。", "学费": "搭配：「天生的」修饰能力、性格，不修饰学费。", "课程": "语义：课程是后天学习的内容，不能说「天生的」。"}, "sentence_index": 6, "correct_answer": "命运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天出门的命运特别差，下雨还忘带伞。", "explanation": "这里应该用〈运气〉。命运指一生的遭遇，不用来说一天的顺利或倒霉。"}, {"text": "这场比赛的命运出来了，我们赢了。", "explanation": "这里应该用〈结果〉。命运指人一生的遭遇，不用来指一场比赛的结果。"}, {"text": "这次实验的命运很有趣。", "explanation": "这里应该用〈过程〉。命运指人一生的遭遇，不用来说一次实验的经过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一条坎坷的命运。", "corrected_sentence": "他有一种坎坷的命运。", "error_description": "错误：「一条坎坷的命运」；正确：「一种坎坷的命运」。「条」用于细长的东西，命运是抽象名词，应该用「种」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她决心改变自己的一场命运。", "corrected_sentence": "她决心改变自己的命运。", "error_description": "错误：「一场命运」；正确：「自己的命运」。「场」用于比赛、活动等事件，不能用来计量命运，应去掉数量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13889, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "松散", "is_correct": true, "explanation": "正确：「松散」与「紧密」是反义词，指联系或结构不紧，符合这一义项。"}, {"text": "明亮", "is_correct": false, "explanation": "无反义关系：「明亮」形容光线充足，与「紧密」不构成反义。"}, {"text": "柔软", "is_correct": false, "explanation": "无反义关系：「柔软」形容质地，不与「紧密」相对。"}, {"text": "缓慢", "is_correct": false, "explanation": "无反义关系：「缓慢」形容速度，不是「紧密」的反义词。"}], "correct_answer": "松散", "explanations": {"松散": "正确：「松散」与「紧密」是反义词，指联系或结构不紧，符合这一义项。", "明亮": "无反义关系：「明亮」形容光线充足，与「紧密」不构成反义。", "柔软": "无反义关系：「柔软」形容质地，不与「紧密」相对。", "缓慢": "无反义关系：「缓慢」形容速度，不是「紧密」的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13889, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "松散", "is_correct": true, "explanation": "正确：「松散」与「紧密」是反义词，指联系或结构不紧，符合这一义项。"}, {"text": "安静", "is_correct": false, "explanation": "无反义关系：「安静」是与「吵闹」相对的，不是「紧密」的反义词。"}, {"text": "平坦", "is_correct": false, "explanation": "无反义关系：「平坦」形容表面，不与「紧密」相对。"}, {"text": "迅速", "is_correct": false, "explanation": "无反义关系：「迅速」形容速度，不是「紧密」的反义词。"}], "correct_answer": "松散", "explanations": {"松散": "正确：「松散」与「紧密」是反义词，指联系或结构不紧，符合这一义项。", "安静": "无反义关系：「安静」是与「吵闹」相对的，不是「紧密」的反义词。", "平坦": "无反义关系：「平坦」形容表面，不与「紧密」相对。", "迅速": "无反义关系：「迅速」形容速度，不是「紧密」的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13889, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容事物之间距离小、联系紧，或关系密切。", "primary_collocate": null, "pronunciation": "jǐn mì", "ipa": "tɕin˨˩ mi˥˩", "syllable_count": 2, "sentences": [{"text": "归根结底，蜜蜂的命运与人类的粮食安全紧密交织。", "target_word": "紧密", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这两个国家的经济联系很紧密。", "target_word": "紧密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司和他们合作得很紧密。", "target_word": "紧密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们两家公司的关系非常紧密。", "target_word": "紧密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队员们紧密配合，赢了比赛。", "target_word": "紧密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事和你的工作紧密相关。", "target_word": "紧密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请大家紧密团结在一起。", "target_word": "紧密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师和家长要保持紧密联系。", "target_word": "紧密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国的合作越来越紧密。", "target_word": "紧密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学和生活的联系十分紧密。", "target_word": "紧密", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "紧密地", "label": "状语形式"}, {"form": "緊密", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物之间联系紧、关系密切", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1e44a9-8db8-4cc7-8878-02df51e2b7e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13889, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "紧密", "is_correct": true, "explanation": "正确：「紧密交织」说两者联系紧，符合句意。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”指缺少水分，不能用来形容事物之间的交织，句意不通。"}, {"text": "辽阔", "is_correct": false, "explanation": "语义：辽阔指空间广大，不能用来形容“交织”。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：「明亮」多修饰光线、颜色，不修饰事物之间的联系。"}], "explanations": {"紧密": "正确：「紧密交织」说两者联系紧，符合句意。", "干燥": "语义：“干燥”指缺少水分，不能用来形容事物之间的交织，句意不通。", "辽阔": "语义：辽阔指空间广大，不能用来形容“交织”。", "明亮": "搭配：「明亮」多修饰光线、颜色，不修饰事物之间的联系。"}, "sentence_index": 0, "correct_answer": "紧密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种商品很紧密，很多人都抢着买。", "explanation": "这里应该用〈紧俏〉。“紧俏”指商品供不应求；“紧密”说事物之间的联系，不用来形容商品的供需。"}, {"text": "今天的时间安排很紧密，一点空闲都没有。", "explanation": "这里应该用〈紧凑〉。紧凑用于安排、结构；紧密用于联系或关系。"}, {"text": "我的心里很紧密，一直不敢睡觉。", "explanation": "这里应该用〈紧张〉。紧密说事物之间的联系，不用来形容人的心理状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13889, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "紧密", "is_correct": true, "explanation": "正确：「紧密团结」指关系紧，符合句意。"}, {"text": "悠闲", "is_correct": false, "explanation": "语义：「悠闲」是轻松的状态，与「团结在一起」的要求不符。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：「潮湿」指空气或物体含水多，不用来形容人的团结。"}, {"text": "暗淡", "is_correct": false, "explanation": "搭配：「暗淡」多修饰光线、前景，不修饰团结。"}], "explanations": {"紧密": "正确：「紧密团结」指关系紧，符合句意。", "悠闲": "语义：「悠闲」是轻松的状态，与「团结在一起」的要求不符。", "潮湿": "语义：「潮湿」指空气或物体含水多，不用来形容人的团结。", "暗淡": "搭配：「暗淡」多修饰光线、前景，不修饰团结。"}, "sentence_index": 6, "correct_answer": "紧密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的情况很紧密，需要马上去医院。", "explanation": "这里应该用〈紧急〉。紧密说事物之间的联系，形容情况危急要用紧急。"}, {"text": "这个地区的水很紧密，居民们都在想办法。", "explanation": "这里应该用〈紧缺〉。紧密说联系，水源不足要说紧缺。"}, {"text": "这座城市的交通很紧密，车子都动不了。", "explanation": "这里应该用〈拥挤〉。紧密说事物之间的联系，车流多要说拥挤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13889, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们两家公司的关系很紧密地。", "corrected_sentence": "他们两家公司的关系很紧密。", "error_description": "错误：形容词作谓语时句末加“地”，写成“很紧密地”。正确应为“很紧密”；“紧密地”只用作状语，不作谓语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13889, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个城市的交通联系十分紧密地。", "corrected_sentence": "这两个城市的交通联系十分紧密。", "error_description": "错误：句末加「地」，写成「十分紧密地」；正确：「十分紧密」。形容词作谓语时句末不加「地」，「紧密地」只用作状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
