INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13890, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物体或存在无法被看到或察觉。", "primary_collocate": null, "pronunciation": "yǐn xíng", "ipa": "in˨˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "它们不仅是农业生产的隐形支柱，更是生态系统健康与否的敏感指示器。", "target_word": "隐形", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "空气污染是城市里的隐形杀手。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的压力很大，可是别人看不出来，这是隐形的负担。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家务是妈妈的隐形工作，很少有人注意到。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些隐形的成本，买东西时看不到。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了房价，还有很多隐形的花费。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们之间有一堵隐形的墙，谁也不说话。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡眠不足是影响健康的隐形问题。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络上的隐形广告，我们常常没有发现。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有很多隐形的穷人，政府也不知道他们。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隱形", "label": "繁体"}, {"form": "隐形人", "label": "复合"}, {"form": "隐形眼镜", "label": "复合"}], "register": "中性", "sense_fingerprint": "抽象的、不易被察觉的存在，如隐形的成本、隐形的负担", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa05ba3-543a-4f57-9e53-db31b3068c9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彩色", "is_correct": false, "explanation": "体貌：“彩色”描写外观的颜色，与支柱的作用无关。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”形容声音嘈杂，不能修饰支柱。"}, {"text": "隐形", "is_correct": true, "explanation": "隐形：指作用不易被察觉，与“不仅……更是……”的句意相合。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”形容人的品性，不能用来修饰支柱。"}], "explanations": {"彩色": "体貌：“彩色”描写外观的颜色，与支柱的作用无关。", "吵闹": "语义：“吵闹”形容声音嘈杂，不能修饰支柱。", "隐形": "隐形：指作用不易被察觉，与“不仅……更是……”的句意相合。", "懒惰": "语义：“懒惰”形容人的品性，不能用来修饰支柱。"}, "sentence_index": 0, "correct_answer": "隐形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一种隐形遗传病，父母通常没有症状。", "explanation": "这里应该用〈隐性〉。隐形 指看不见，遗传学上不表现出来的特征要用“隐性”。"}, {"text": "他的错误很隐形，大家一眼就看出来了。", "explanation": "这里应该用〈明显〉。隐形 指看不见、不易察觉，与“一眼就看出来”矛盾；错误很容易看出要用“明显”。"}, {"text": "这台机器的声音很隐形，在车间里大家都听得清清楚楚。", "explanation": "这里应该用〈响亮〉。隐形 指不易察觉，与“听得清清楚楚”矛盾；声音大要用“响亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音杂乱，不能修饰墙。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容人的性情，用在墙上不合。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”多用于场面、场所，不能说“热闹的墙”。"}, {"text": "隐形", "is_correct": true, "explanation": "隐形：看不见，与“一堵……墙”搭配，句意通顺。"}], "explanations": {"嘈杂": "语义：“嘈杂”形容声音杂乱，不能修饰墙。", "温柔": "语义：“温柔”形容人的性情，用在墙上不合。", "热闹": "搭配：“热闹”多用于场面、场所，不能说“热闹的墙”。", "隐形": "隐形：看不见，与“一堵……墙”搭配，句意通顺。"}, "sentence_index": 6, "correct_answer": "隐形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把剪刀很隐形，一碰就划破了手。", "explanation": "这里应该用〈锋利〉。隐形 指看不见，与“一碰就划破了手”矛盾；刀刃锋利要用“锋利”。"}, {"text": "这份报告的数据很隐形，大家一看就能找到问题。", "explanation": "这里应该用〈直观〉。隐形 指看不见，与“一看就能找到问题”矛盾；数据清楚易懂要用“直观”。"}, {"text": "这辆车的喇叭很隐形，每次按都刺耳得让人头疼。", "explanation": "这里应该用〈刺耳〉。隐形 指看不见，与“刺耳得让人头疼”矛盾；声音尖锐难听要用“刺耳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔开支隐形的增加了家庭的负担。", "corrected_sentence": "这笔开支隐形地增加了家庭的负担。", "error_description": "“隐形”修饰动词“增加”时要用“地”，不能用“的”。应说“隐形地增加了家庭的负担”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们之间有一堵隐形了的墙，彼此都不肯让步。", "corrected_sentence": "他们之间有一堵隐形的墙，彼此都不肯让步。", "error_description": "“隐形”作定语时用“的”，不能用“了的”。应说“隐形的墙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
