INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13891, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻起支撑作用的人或事物。", "primary_collocate": null, "pronunciation": "zhī zhù", "ipa": "ʈʂɨ˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "它们不仅是农业生产的隐形支柱，更是生态系统健康与否的敏感指示器。", "target_word": "支柱", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "爸爸生病以后，哥哥成了这个家的支柱。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业是这个国家经济的支柱。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对很多老人来说，孩子是生活的支柱。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信仰是他在困难中的精神支柱。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂是小城的经济支柱，很多人在这里工作。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是球队的支柱，没有她，比赛就很难赢。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游是这个小岛收入的重要支柱。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在最难过的时候，朋友的鼓励成了他的支柱。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中小企业是国家就业的重要支柱。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "精神支柱", "label": "复合"}, {"form": "支柱产业", "label": "复合"}], "register": "中性", "sense_fingerprint": "比喻义：家庭、经济、精神等方面起关键支撑作用的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa05ba3-543a-4f57-9e53-db31b3068c9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13891, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "支柱", "is_correct": true, "explanation": "正确答案：支柱（zhī zhù），指起支撑作用的人或事物。"}, {"text": "蜘蛛", "is_correct": false, "explanation": "蜘蛛（zhī zhū）与支柱只有第二个音节不同：zhū 为第一声，zhù 为第四声，意思是蜘蛛。"}, {"text": "资助", "is_correct": false, "explanation": "zī 与 zhī 声母不同（z 与 zh），声调相同，意思是资助。"}, {"text": "制住", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是控制住、压制住。"}, {"text": "吃住", "is_correct": false, "explanation": "chī 与 zhī 声母不同（ch 与 zh），声调相同，意思是吃和住。"}], "explanations": {"支柱": "正确答案：支柱（zhī zhù），指起支撑作用的人或事物。", "蜘蛛": "蜘蛛（zhī zhū）与支柱只有第二个音节不同：zhū 为第一声，zhù 为第四声，意思是蜘蛛。", "资助": "zī 与 zhī 声母不同（z 与 zh），声调相同，意思是资助。", "制住": "zhì（第四声）与 zhī（第一声）声调不同，意思是控制住、压制住。", "吃住": "chī 与 zhī 声母不同（ch 与 zh），声调相同，意思是吃和住。"}, "sentence_index": null, "correct_answer": "支柱"}, "level_3": {"options": [{"text": "支柱", "is_correct": true, "explanation": "正确答案：「隐形支柱」指在农业生产中起支撑作用却不显眼的事物，与后句的递进关系相合。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具只用来娱乐，与「农业生产」的关键作用无关，句子读来不通。"}, {"text": "招牌", "is_correct": false, "explanation": "搭配：「隐形」与「招牌」不搭，招牌是醒目的标记，不能隐形。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：装饰只起点缀作用，与后句「更是……敏感指示器」所强调的实际作用不符。"}], "explanations": {"支柱": "正确答案：「隐形支柱」指在农业生产中起支撑作用却不显眼的事物，与后句的递进关系相合。", "玩具": "语义：玩具只用来娱乐，与「农业生产」的关键作用无关，句子读来不通。", "招牌": "搭配：「隐形」与「招牌」不搭，招牌是醒目的标记，不能隐形。", "装饰": "语义：装饰只起点缀作用，与后句「更是……敏感指示器」所强调的实际作用不符。"}, "sentence_index": 0, "correct_answer": "支柱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要夯实团队的支柱，才能赢得比赛。", "explanation": "这里应该用〈基础〉。夯实用于地基、基础，支柱是已经撑起来的结构，不能说夯实支柱。"}, {"text": "这份事业有深厚的支柱，经得起风浪。", "explanation": "这里应该用〈根基〉。深厚修饰根基、功底，支柱不这样修饰。"}, {"text": "我们要打好英语支柱，才能学好后面的课程。", "explanation": "这里应该用〈基础〉。「打好」常与「基础」搭配，表示打下底子；支柱是已经撑起来的结构，不这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13891, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "支柱", "is_correct": true, "explanation": "正确答案：支柱（zhī zhù），指起支撑作用的人或事物。"}, {"text": "止住", "is_correct": false, "explanation": "止（zhǐ，第三声）与支（zhī，第一声）声调不同，「止住」意思是停下来、制止。"}, {"text": "植株", "is_correct": false, "explanation": "植株（zhí zhū）与支柱两个音节声调都不同：zhí 为第二声，zhū 为第一声，意思是植物的整个株体。"}, {"text": "蜘蛛", "is_correct": false, "explanation": "蜘蛛（zhī zhū）与支柱只有第二个音节不同：zhū 为第一声，zhù 为第四声，意思是蜘蛛。"}, {"text": "制住", "is_correct": false, "explanation": "制（zhì，第四声）与支（zhī，第一声）声调不同，「制住」意思是控制住、压制住。"}], "explanations": {"支柱": "正确答案：支柱（zhī zhù），指起支撑作用的人或事物。", "止住": "止（zhǐ，第三声）与支（zhī，第一声）声调不同，「止住」意思是停下来、制止。", "植株": "植株（zhí zhū）与支柱两个音节声调都不同：zhí 为第二声，zhū 为第一声，意思是植物的整个株体。", "蜘蛛": "蜘蛛（zhī zhū）与支柱只有第二个音节不同：zhū 为第一声，zhù 为第四声，意思是蜘蛛。", "制住": "制（zhì，第四声）与支（zhī，第一声）声调不同，「制住」意思是控制住、压制住。"}, "sentence_index": null, "correct_answer": "支柱"}, "level_3": {"options": [{"text": "支柱", "is_correct": true, "explanation": "正确答案：「她是球队的支柱」指她是起关键作用的人，与后句「没有她，比赛就很难赢」一致。"}, {"text": "包袱", "is_correct": false, "explanation": "语义：包袱指负担，与后句对她的赞扬意思相反，「没有她比赛就很难赢」说的是她的重要性。"}, {"text": "拖油瓶", "is_correct": false, "explanation": "语域：「拖油瓶」是口语中的贬义说法，不适合用在球队的正式评价里，也与后句的赞扬语气矛盾。"}, {"text": "球迷", "is_correct": false, "explanation": "语义：球迷是观众，不上场比赛；「没有她，比赛就很难赢」说的是球员对比赛的作用。"}], "explanations": {"支柱": "正确答案：「她是球队的支柱」指她是起关键作用的人，与后句「没有她，比赛就很难赢」一致。", "包袱": "语义：包袱指负担，与后句对她的赞扬意思相反，「没有她比赛就很难赢」说的是她的重要性。", "拖油瓶": "语域：「拖油瓶」是口语中的贬义说法，不适合用在球队的正式评价里，也与后句的赞扬语气矛盾。", "球迷": "语义：球迷是观众，不上场比赛；「没有她，比赛就很难赢」说的是球员对比赛的作用。"}, "sentence_index": 6, "correct_answer": "支柱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要先抓住问题的支柱，再逐一解决。", "explanation": "这里应该用〈核心〉。「抓住」常与「核心」「关键」搭配，指找到最关键的部分，「支柱」不这样用。"}, {"text": "这次会议为两国合作奠定了良好的支柱。", "explanation": "这里应该用〈基石〉。「奠定」后面接的是可以打下底子的事物，「支柱」是已经撑起来的结构，不能说「奠定支柱」。"}, {"text": "他树立了良好的支柱，大家都很佩服他。", "explanation": "这里应该用〈威信〉。树立用于威信、形象、榜样，支柱是撑住结构的东西，不能说树立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13891, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是这个家的一只支柱，大家都靠他。", "corrected_sentence": "他是这个家的一个支柱，大家都靠他。", "error_description": "量词错误：「只」多用于动物和成对的东西，不能用来数人或比喻义的支柱。这里应该用「个」，说「一个支柱」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13891, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份爱成了他的一条精神支柱。", "corrected_sentence": "这份爱成了他的一个精神支柱。", "error_description": "量词错误：「条」用于河流、绳子等细长的东西，抽象的「精神支柱」应该用「个」计量，说「一个精神支柱」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13892, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13892, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13892, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "用于书面，连接两个相反的选择，表示‘是还是不是’或‘是否’。", "primary_collocate": null, "pronunciation": "yǔ fǒu", "ipa": "y˨˩ fou˨˩", "syllable_count": 2, "sentences": [{"text": "它们不仅是农业生产的隐形支柱，更是生态系统健康与否的敏感指示器。", "target_word": "与否", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "成功与否，都要努力试一试。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气好与否，我们都要出发。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去与否由你自己决定。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "价格贵与否，不是最重要的。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他来与否，对我们没有影响。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习好与否，不只看分数。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人快乐与否，和钱多少关系不大。", "target_word": "与否", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同意与否，请你今天告诉我。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "产品好用与否，客户最清楚。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "與否", "label": "繁体"}], "register": "书面", "sense_fingerprint": "书面用语，表示是还是不是", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1e44a9-8db8-4cc7-8878-02df51e2b7e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "与否", "is_correct": true, "explanation": "正确：“健康与否”表示“是否健康”，与“敏感指示器”搭配通顺。"}, {"text": "发挥", "is_correct": false, "explanation": "搭配：“健康”不能“发挥”，“发挥”通常接“作用”之类的宾语，这里说不通。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”指去某处看某物，与“生态系统健康”的状态无关，句子意思不通。"}, {"text": "投诉", "is_correct": false, "explanation": "配价：“投诉”需要投诉的对象，“健康投诉的”后面缺少对象，结构不完整。"}], "explanations": {"与否": "正确：“健康与否”表示“是否健康”，与“敏感指示器”搭配通顺。", "发挥": "搭配：“健康”不能“发挥”，“发挥”通常接“作用”之类的宾语，这里说不通。", "参观": "语义：“参观”指去某处看某物，与“生态系统健康”的状态无关，句子意思不通。", "投诉": "配价：“投诉”需要投诉的对象，“健康投诉的”后面缺少对象，结构不完整。"}, "sentence_index": 0, "correct_answer": "与否"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一定去与否，你不用管。", "explanation": "语义：“与否”表示去不去两种情况都有可能，说话人若已确定要去，就不能用它。这里应直接说“我一定去”。"}, {"text": "他昨天已经到了与否，我们还在等他。", "explanation": "语义：“已经到了”说明事实已定，又说“还在等他”，前后矛盾；说话人已知结果时不宜用“与否”。"}, {"text": "他必须参加与否，我们都要通知。", "explanation": "语义：“与否”表示参加与否还未确定，“必须”表示一定要参加，两者意思相反。这里应直接说“他必须参加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "与否", "is_correct": true, "explanation": "正确：“学习好与否”表示“学习好不好”，与后面“不只看分数”呼应。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“学习好感冒”意思不通，“感冒”不能与“学习好”组成这样的结构。"}, {"text": "下载", "is_correct": false, "explanation": "语义：“学习好下载”说不通，“下载”的对象是文件或软件，与“学习”无关。"}, {"text": "报名", "is_correct": false, "explanation": "配价：“报名”需要带上报名的项目，“学习好报名”缺少对象，结构不完整。"}], "explanations": {"与否": "正确：“学习好与否”表示“学习好不好”，与后面“不只看分数”呼应。", "感冒": "语义：“学习好感冒”意思不通，“感冒”不能与“学习好”组成这样的结构。", "下载": "语义：“学习好下载”说不通，“下载”的对象是文件或软件，与“学习”无关。", "报名": "配价：“报名”需要带上报名的项目，“学习好报名”缺少对象，结构不完整。"}, "sentence_index": 6, "correct_answer": "与否"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事他一定会做与否，大家都很放心。", "explanation": "语义：“与否”表示做不做尚未确定，“一定会做”表示已经确定，两者矛盾。这里应直接说“他一定会做”。"}, {"text": "他来还是不来与否，我们都要准备。", "explanation": "重复：“与否”本身已表示“是还是不是”，与“来还是不来”重复，应说“他来与否”。"}, {"text": "我们去公园与否爬山，都由你决定。", "explanation": "语义：“与否”只用于同一件事的正反两面，不能连接“去公园”和“爬山”两件不同的事，应说“去公园还是爬山”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他按时到达与否了，要看交通情况。", "corrected_sentence": "他按时到达与否，要看交通情况。", "error_description": "“与否”是书面的表达结构，后面不能再加“了”。应写作“他按时到达与否，要看交通情况”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新方案可行与否了，我们下周讨论。", "corrected_sentence": "新方案可行与否，我们下周讨论。", "error_description": "错误：“与否”是书面结构，后面不能再加“了”。应写作“新方案可行与否，我们下周讨论。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
