INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13894, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来显示或指示某种信息或状态的设备或装置。", "primary_collocate": null, "pronunciation": "zhǐ shì qì", "ipa": "ʈʂɨ˨˩ ʂɨ˥˩ tɕʰi˥˩", "syllable_count": 3, "sentences": [{"text": "这台设备的电源指示器亮起了绿灯，说明机器已经开机。", "target_word": "指示器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车上的油量指示器坏了。", "target_word": "指示器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "指示器亮了红灯，说明电量不足。", "target_word": "指示器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了一眼指示器，就知道水温。", "target_word": "指示器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器上有一个小指示器。", "target_word": "指示器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请检查一下电池指示器。", "target_word": "指示器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "指示器上的绿灯一直亮着。", "target_word": "指示器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑的指示器在哪儿？", "target_word": "指示器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人每天都看压力指示器。", "target_word": "指示器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我买了一个新的指示器。", "target_word": "指示器", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "显示信息或状态的装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1e44a9-8db8-4cc7-8878-02df51e2b7e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指示器", "is_correct": true, "explanation": "正确：“电源指示器”指显示设备开关状态的装置，与“亮起了绿灯”搭配通顺。"}, {"text": "农民", "is_correct": false, "explanation": "语义：“农民”是人，不能亮灯，“电源农民”说不通。"}, {"text": "会议", "is_correct": false, "explanation": "语义：“会议”不是装置，不能亮起绿灯，“电源会议”与句意不符。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“电源”后接“书包”不通，书包不是能亮灯的装置。"}], "explanations": {"指示器": "正确：“电源指示器”指显示设备开关状态的装置，与“亮起了绿灯”搭配通顺。", "农民": "语义：“农民”是人，不能亮灯，“电源农民”说不通。", "会议": "语义：“会议”不是装置，不能亮起绿灯，“电源会议”与句意不符。", "书包": "搭配：“电源”后接“书包”不通，书包不是能亮灯的装置。"}, "sentence_index": 0, "correct_answer": "指示器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生用指示器给病人打针。", "explanation": "语义：指示器是显示状态的装置，不能用来打针，这里应换成〈注射器〉。"}, {"text": "他把指示器穿在身上去上班。", "explanation": "语义：指示器是显示状态的装置，不是衣物，不能穿在身上，这里应换成〈外套〉。"}, {"text": "他用指示器削了一个苹果。", "explanation": "语义：指示器只用来显示状态，不能用来削东西，这里应换成〈刀〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指示器", "is_correct": true, "explanation": "正确：“指示器上的绿灯”指装置上亮着的灯，与句子意思一致。"}, {"text": "故事", "is_correct": false, "explanation": "语义：“故事”不是可以承载灯的实体，“故事上的绿灯”意思不通。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“上”要接可以承载东西的表面，“星期”不是物体，这里搭配不通。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：“清晨”是时间，不能作为绿灯所在的地方，句子意思不通。"}], "explanations": {"指示器": "正确：“指示器上的绿灯”指装置上亮着的灯，与句子意思一致。", "故事": "语义：“故事”不是可以承载灯的实体，“故事上的绿灯”意思不通。", "星期": "搭配：“上”要接可以承载东西的表面，“星期”不是物体，这里搭配不通。", "清晨": "语义：“清晨”是时间，不能作为绿灯所在的地方，句子意思不通。"}, "sentence_index": 6, "correct_answer": "指示器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门口的指示器唱起了歌。", "explanation": "语义：指示器是显示状态的装置，不会唱歌，这里应换成〈音箱〉。"}, {"text": "厨师用指示器量盐的多少。", "explanation": "这里应该用〈量勺〉。指示器是显示装置，不用来量取食材。"}, {"text": "我们一起吃了那个指示器。", "explanation": "语义：指示器是装置，不能吃，这里应换成食物，如〈饼干〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人在墙上装了一把指示器。", "corrected_sentence": "工人在墙上装了一个指示器。", "error_description": "量词：指示器用“个”，“把”用于有柄的器具，应写作“一个指示器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电量不足时，指示器会亮下来。", "corrected_sentence": "电量不足时，指示器会亮起来。", "error_description": "补语：表示灯光开始发亮用“亮起来”，“亮下来”不符合习惯，应写作“亮起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e85832-ebc2-48a2-962c-332ed21d6c0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19855, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "敷衍", "is_correct": true, "explanation": "反义：“认真对待”与“敷衍”表示对待事情的两种相反态度。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指探究事物，与“认真对待”没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”指加入某项活动，与“认真对待”没有反义关系。"}, {"text": "完成", "is_correct": false, "explanation": "“完成”指做完某件事，与“认真对待”没有反义关系。"}], "correct_answer": "敷衍", "explanations": {"敷衍": "反义：“认真对待”与“敷衍”表示对待事情的两种相反态度。", "研究": "“研究”指探究事物，与“认真对待”没有反义关系。", "参加": "“参加”指加入某项活动，与“认真对待”没有反义关系。", "完成": "“完成”指做完某件事，与“认真对待”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
