INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19855, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "以严肃认真的态度处理某件事情。", "primary_collocate": null, "pronunciation": "rèn zhēn duì dài", "ipa": "ɻən˥˩ ʈʂən˥ tweɪ˥˩ taɪ˥˩", "syllable_count": 4, "sentences": [{"text": "SaaS公司需要认真对待数据和算法的合规问题。", "target_word": "认真对待", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "老师要求我们认真对待每次考试。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你应该认真对待这份工作。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他认真对待朋友说的每一句话。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试快到了，大家要认真对待复习。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生认真对待每一位病人。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不能不认真对待安全问题。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她认真对待了这次面试，准备了很久。", "target_word": "认真对待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司认真对待客人的意见。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来没有认真对待过这件事。", "target_word": "认真对待", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "认真对待了", "label": "体标"}, {"form": "认真对待过", "label": "体标"}], "register": "中性", "sense_fingerprint": "以严肃认真的态度处理事情、问题或任务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79963f23-daa7-47ea-a422-83820dc3fd66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19855, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认真对待", "is_correct": true, "explanation": "“认真对待”表示严肃处理，与“需要……合规问题”的语境相符。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“需要忽视”与合规问题应受重视的语境相反。"}, {"text": "出售", "is_correct": false, "explanation": "搭配：“出售”针对商品，不能用于“合规问题”。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”用于场所或展览，不能用于数据和算法的问题。"}], "explanations": {"认真对待": "“认真对待”表示严肃处理，与“需要……合规问题”的语境相符。", "忽视": "语义：“需要忽视”与合规问题应受重视的语境相反。", "出售": "搭配：“出售”针对商品，不能用于“合规问题”。", "参观": "搭配：“参观”用于场所或展览，不能用于数据和算法的问题。"}, "sentence_index": 0, "correct_answer": "认真对待"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都认真对待这张桌子。", "explanation": "这里应该用〈擦〉。〈认真对待〉用于事情、问题或人，不用于擦拭家具这类具体动作。"}, {"text": "他认真对待了那袋大米。", "explanation": "这里应该用〈淘〉。〈认真对待〉不用于淘洗食材这类具体动作。"}, {"text": "他认真对待了窗外的天气。", "explanation": "这里应该用〈观察〉。〈认真对待〉表示对事情的态度，不用于观察自然现象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19855, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认真对待", "is_correct": true, "explanation": "“认真对待”表示严肃处理，“不能不……安全问题”需要这种态度。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”用于植物，不能用于安全问题。"}, {"text": "组装", "is_correct": false, "explanation": "搭配：“组装”用于零件或机器，不能用于安全问题。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：安全问题不能被欣赏，与句意冲突。"}], "explanations": {"认真对待": "“认真对待”表示严肃处理，“不能不……安全问题”需要这种态度。", "种植": "搭配：“种植”用于植物，不能用于安全问题。", "组装": "搭配：“组装”用于零件或机器，不能用于安全问题。", "欣赏": "语义：安全问题不能被欣赏，与句意冲突。"}, "sentence_index": 6, "correct_answer": "认真对待"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从来没有认真对待过这把椅子。", "explanation": "这里应该用〈坐〉。〈认真对待〉表示对事情的态度，不用于坐这类具体动作。"}, {"text": "他从来没有认真对待过这盆花。", "explanation": "这里应该用〈浇〉。〈认真对待〉不用于浇花这类具体动作。"}, {"text": "他从来没有认真对待过这条马路。", "explanation": "这里应该用〈跑〉。〈认真对待〉不用于在马路上跑步这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19855, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们从来没有认真对待了这份工作。", "corrected_sentence": "我们从来没有认真对待过这份工作。", "error_description": "错误：表示经历的“认真对待”后用了“了”。正确：“从来没有”表示经历，应说“认真对待过”，用“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19855, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对这件事认真对待很好。", "corrected_sentence": "他对这件事认真对待得很好。", "error_description": "错误：“认真对待”作谓语时缺少补语标记“得”。正确：表示程度的补语要用“得”连接，应说“认真对待得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
