INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19858, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人，指人类，能够制造工具并使用语言进行社会性活动的高等动物。", "primary_collocate": null, "pronunciation": "rén", "ipa": "ɻən˧˥", "syllable_count": 1, "sentences": [{"text": "人是会使用语言的高等动物。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人能制造工具，这是人和动物不同的地方。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人在社会里生活，需要和别人合作。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几千年前的人就会用火了。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人通过语言交流想法。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究人怎样学会说话。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人比其他动物更会用工具。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人需要空气和水才能生活。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从很早以前开始，人就会制造简单的工具。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人是社会性动物，不能一个人生活。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人类", "label": "复合"}, {"form": "古人", "label": "复合"}], "register": "书面", "sense_fingerprint": "人：能制造工具、使用语言的人类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cff4beb-2454-4408-ae79-6e87aa30b10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19858, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人", "is_correct": true, "explanation": "正确答案：人（rén），指能制造工具、使用语言的人类。"}, {"text": "忍", "is_correct": false, "explanation": "rěn（第三声）与 rén（第二声）声调不同，意思是忍耐。"}, {"text": "然", "is_correct": false, "explanation": "rán 与 rén 韵母不同（-an / -en），声调相同，意思是这样、如此。"}, {"text": "任", "is_correct": false, "explanation": "rèn（第四声）与 rén（第二声）声调不同，韵母相同，意思是任务、任何。"}], "explanations": {"人": "正确答案：人（rén），指能制造工具、使用语言的人类。", "忍": "rěn（第三声）与 rén（第二声）声调不同，意思是忍耐。", "然": "rán 与 rén 韵母不同（-an / -en），声调相同，意思是这样、如此。", "任": "rèn（第四声）与 rén（第二声）声调不同，韵母相同，意思是任务、任何。"}, "sentence_index": null, "correct_answer": "人"}, "level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会使用语言，也不是动物。"}, {"text": "人", "is_correct": true, "explanation": "人：能使用语言的高等动物，正好填入句中的空格。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不是动物，也不会使用语言。"}, {"text": "机器人", "is_correct": false, "explanation": "搭配：「高等动物」是生物类别，机器人不属于动物，不能这样说。"}], "explanations": {"桌子": "语义：桌子是家具，不会使用语言，也不是动物。", "人": "人：能使用语言的高等动物，正好填入句中的空格。", "植物": "语义：植物不是动物，也不会使用语言。", "机器人": "搭配：「高等动物」是生物类别，机器人不属于动物，不能这样说。"}, "sentence_index": 0, "correct_answer": "人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "细菌是一种微小的人。", "explanation": "这里应该用〈生物〉。「人」只指人类，不指细菌等一般生物。"}, {"text": "大象是最大的陆地人。", "explanation": "这里应该用〈动物〉。「人」不作为一般动物的类别词，不能说「陆地人」。"}, {"text": "我们班来了一只人。", "explanation": "这里应该用〈个〉或〈位〉。量词「只」用于动物，指人要用「个」或「位」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19858, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "人", "is_correct": true, "explanation": "正确答案：人（rén），指能制造工具、使用语言的人类。"}, {"text": "仍", "is_correct": false, "explanation": "réng 与 rén 韵母不同（-eng / -en），声调相同，意思是仍然。"}, {"text": "忍", "is_correct": false, "explanation": "rěn（第三声）与 rén（第二声）声调不同，意思是忍耐。"}, {"text": "认", "is_correct": false, "explanation": "rèn（第四声）与 rén（第二声）声调不同，意思是承认或辨认。"}], "explanations": {"人": "正确答案：人（rén），指能制造工具、使用语言的人类。", "仍": "réng 与 rén 韵母不同（-eng / -en），声调相同，意思是仍然。", "忍": "rěn（第三声）与 rén（第二声）声调不同，意思是忍耐。", "认": "rèn（第四声）与 rén（第二声）声调不同，意思是承认或辨认。"}, "sentence_index": null, "correct_answer": "人"}, "level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不会用工具，也不会比其他动物更聪明。"}, {"text": "人", "is_correct": true, "explanation": "人：比其他动物更会用工具，正好填入句中的空格。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不是用工具的主体。"}, {"text": "机器", "is_correct": false, "explanation": "搭配：「比其他动物」要求比较的对象是生物，机器不属于动物范畴。"}], "explanations": {"石头": "语义：石头不会用工具，也不会比其他动物更聪明。", "人": "人：比其他动物更会用工具，正好填入句中的空格。", "汽车": "语义：汽车是交通工具，不是用工具的主体。", "机器": "搭配：「比其他动物」要求比较的对象是生物，机器不属于动物范畴。"}, "sentence_index": 6, "correct_answer": "人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵树是一个很高的人。", "explanation": "这里应该用〈植物〉。「人」指人类，不能用来指树木这样的植物。"}, {"text": "我们家养的猫是一个很可爱的人。", "explanation": "这里应该用〈动物〉。「人」指人类，不能用来指猫，猫属于动物。"}, {"text": "公司新来了十条人。", "explanation": "这里应该用〈个〉或〈位〉。量词「条」不用于指人，「人」要用「个」或「位」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人大脑比其他动物复杂。", "corrected_sentence": "人的大脑比其他动物复杂。", "error_description": "错误形式是「人大脑」，正确形式是「人的大脑」。「人」修饰名词「大脑」时要用「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "都人需要空气和水。", "corrected_sentence": "人都需要空气和水。", "error_description": "错误形式是「都人」，正确形式是「人都」。副词「都」要放在主语「人」之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19859, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "给", "is_correct": true, "explanation": "反义：“要”是向别人索取，“给”是把东西交给别人，二者方向相反。"}, {"text": "写", "is_correct": false, "explanation": "写：动词，指用笔记录文字，与“要”没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "吃：动词，指把食物咽下，与“要”没有反义关系。"}, {"text": "站", "is_correct": false, "explanation": "站：动词，指身体直立，与“要”没有反义关系。"}], "correct_answer": "给", "explanations": {"给": "反义：“要”是向别人索取，“给”是把东西交给别人，二者方向相反。", "写": "写：动词，指用笔记录文字，与“要”没有反义关系。", "吃": "吃：动词，指把食物咽下，与“要”没有反义关系。", "站": "站：动词，指身体直立，与“要”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19859, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "给", "is_correct": true, "explanation": "反义：“要”是向别人索取，“给”是把东西交给别人，二者方向相反。"}, {"text": "跑", "is_correct": false, "explanation": "跑：动词，指快速移动，与“要”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱：动词，指发出有节奏的声音表达音乐，与“要”没有反义关系。"}, {"text": "看", "is_correct": false, "explanation": "看：动词，指用眼睛注视，与“要”没有反义关系。"}], "correct_answer": "给", "explanations": {"给": "反义：“要”是向别人索取，“给”是把东西交给别人，二者方向相反。", "跑": "跑：动词，指快速移动，与“要”没有反义关系。", "唱": "唱：动词，指发出有节奏的声音表达音乐，与“要”没有反义关系。", "看": "看：动词，指用眼睛注视，与“要”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19859, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示希望、需要或请求得到某物，或做某事。", "primary_collocate": null, "pronunciation": "yào", "ipa": "jau˥˩", "syllable_count": 1, "sentences": [{"text": "服务员，我要一碗牛肉面。", "target_word": "要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请问，你要几个包子？", "target_word": "要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我要两张去上海的票。", "target_word": "要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师，我要一支新笔。", "target_word": "要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人要了一杯咖啡。", "target_word": "要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他要我的电话号码。", "target_word": "要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买书时，我要了一个袋子。", "target_word": "要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要大杯还是小杯？", "target_word": "要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子向妈妈要零花钱。", "target_word": "要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我要一张纸，写个地址。", "target_word": "要", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不要", "label": "否定"}, {"form": "要了", "label": "体标"}], "register": "口语", "sense_fingerprint": "要：点餐、买东西或向别人索取时，请求得到某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a7f8796-b995-49d4-a98e-f68767af4dc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19859, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "要", "is_correct": true, "explanation": "要（yào）：请求得到某物，如点餐时说“我要一碗面”。这是本词。"}, {"text": "咬", "is_correct": false, "explanation": "咬（yǎo）与 yào 声调不同（第三声），意思是用牙齿夹住，与点餐无关。"}, {"text": "摇", "is_correct": false, "explanation": "摇（yáo）与 yào 声调不同（第二声），意思是晃动。"}, {"text": "腰", "is_correct": false, "explanation": "腰（yāo）与 yào 声调不同（第一声），意思是身体的腰部。"}, {"text": "掉", "is_correct": false, "explanation": "掉（diào）与 yào 只差声母（d 与零声母），意思是落下或失去。"}], "explanations": {"要": "要（yào）：请求得到某物，如点餐时说“我要一碗面”。这是本词。", "咬": "咬（yǎo）与 yào 声调不同（第三声），意思是用牙齿夹住，与点餐无关。", "摇": "摇（yáo）与 yào 声调不同（第二声），意思是晃动。", "腰": "腰（yāo）与 yào 声调不同（第一声），意思是身体的腰部。", "掉": "掉（diào）与 yào 只差声母（d 与零声母），意思是落下或失去。"}, "sentence_index": null, "correct_answer": "要"}, "level_3": {"options": [{"text": "要", "is_correct": true, "explanation": "正确：点餐时说“我要一碗牛肉面”，表示请求得到，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说唱一碗牛肉面。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”与点餐的语境不符，不能说哭一碗牛肉面。"}, {"text": "冻", "is_correct": false, "explanation": "语义：“冻”表示使变冷变硬，与“牛肉面”的点餐语境不符。"}], "explanations": {"要": "正确：点餐时说“我要一碗牛肉面”，表示请求得到，符合句意。", "唱": "搭配：“唱”的对象是歌曲，不能说唱一碗牛肉面。", "哭": "语义：“哭”与点餐的语境不符，不能说哭一碗牛肉面。", "冻": "语义：“冻”表示使变冷变硬，与“牛肉面”的点餐语境不符。"}, "sentence_index": 0, "correct_answer": "要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周五要放假了，大家都很高兴。", "explanation": "这里的“要”表示将要发生，不表示请求得到某物或做某事。"}, {"text": "下个月我们要搬进新房子了。", "explanation": "这里的“要”表示将要发生，不表示希望、需要或请求得到某物或做某事。"}, {"text": "马上要下课了，大家收拾东西吧。", "explanation": "这里的“要”表示即将发生，不表示希望、需要或请求得到某物或做某事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19859, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "要", "is_correct": true, "explanation": "要（yào）：请求得到某物，如买东西时说“我要一张纸”。这是本词。"}, {"text": "邀", "is_correct": false, "explanation": "邀（yāo）与 yào 声调不同（第一声），意思是请人来或参加。"}, {"text": "遥", "is_correct": false, "explanation": "遥（yáo）与 yào 声调不同（第二声），意思是距离远。"}, {"text": "跳", "is_correct": false, "explanation": "跳（tiào）与 yào 只差声母（t 与零声母），意思是身体离开地面向上或向前运动。"}], "explanations": {"要": "要（yào）：请求得到某物，如买东西时说“我要一张纸”。这是本词。", "邀": "邀（yāo）与 yào 声调不同（第一声），意思是请人来或参加。", "遥": "遥（yáo）与 yào 声调不同（第二声），意思是距离远。", "跳": "跳（tiào）与 yào 只差声母（t 与零声母），意思是身体离开地面向上或向前运动。"}, "sentence_index": null, "correct_answer": "要"}, "level_3": {"options": [{"text": "要", "is_correct": true, "explanation": "正确：“买书时，我要了一个袋子”表示请求得到，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃的对象是食物，不能说吃了一个袋子，与买书的语境不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”后不能接“袋子”，不能说唱了一个袋子。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬袋子不合常理，与买书时的情境不符。"}], "explanations": {"要": "正确：“买书时，我要了一个袋子”表示请求得到，符合句意。", "吃": "语义：吃的对象是食物，不能说吃了一个袋子，与买书的语境不符。", "唱": "搭配：“唱”后不能接“袋子”，不能说唱了一个袋子。", "咬": "语义：咬袋子不合常理，与买书时的情境不符。"}, "sentence_index": 6, "correct_answer": "要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "列车要到站了，大家收拾行李吧。", "explanation": "这里的“要”表示将要发生，不表示希望、需要或请求得到某物或做某事。"}, {"text": "天要黑了，快回家吧。", "explanation": "这里的“要”表示将要发生，不表示希望、需要或请求得到某物或做某事。"}, {"text": "天气快要冷了，多穿衣服。", "explanation": "这里的“要”与“快”连用，表示即将发生，不表示请求得到某物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一张去北京的火车票。", "corrected_sentence": "我要一张去北京的火车票。", "error_description": "错误：句中缺少动词“要”，“我”后直接接数量短语，句子不成立。补上“要”即为“我要一张去北京的火车票。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我了要一个纸袋。", "corrected_sentence": "我要了一个纸袋。", "error_description": "错误形式：“了要”；正确形式：“要了”。动态助词“了”应紧跟在动词“要”之后，不能放在“要”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19860, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "整齐", "is_correct": true, "explanation": "“整齐”与“乱”构成反义，指物品摆放有序。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”说厚度，与“乱”没有反义关系。"}, {"text": "远", "is_correct": false, "explanation": "“远”说距离，与“乱”没有反义关系。"}, {"text": "窄", "is_correct": false, "explanation": "“窄”说宽度，与“乱”没有反义关系。"}], "correct_answer": "整齐", "explanations": {"整齐": "“整齐”与“乱”构成反义，指物品摆放有序。", "厚": "“厚”说厚度，与“乱”没有反义关系。", "远": "“远”说距离，与“乱”没有反义关系。", "窄": "“窄”说宽度，与“乱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19860, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有条不紊", "is_correct": true, "explanation": "“有条不紊”与“乱”构成反义，指做事或摆放有条理。"}, {"text": "薄", "is_correct": false, "explanation": "“薄”说厚度，与“乱”没有反义关系。"}, {"text": "近", "is_correct": false, "explanation": "“近”说距离，与“乱”没有反义关系。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”说速度，与“乱”没有反义关系。"}], "correct_answer": "有条不紊", "explanations": {"有条不紊": "“有条不紊”与“乱”构成反义，指做事或摆放有条理。", "薄": "“薄”说厚度，与“乱”没有反义关系。", "近": "“近”说距离，与“乱”没有反义关系。", "慢": "“慢”说速度，与“乱”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19860, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指事物没有条理、秩序或混乱的状态。", "primary_collocate": null, "pronunciation": "luàn", "ipa": "lwan˥˩", "syllable_count": 1, "sentences": [{"text": "数据要干净，不能乱。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "你的房间太乱了。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上很乱，找不到笔。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的书包里太乱了，什么都找不到。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们走后，客厅很乱。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，头发就乱了。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文件放得太乱，要重新整理。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个仓库里的东西很乱，找东西很费时间。", "target_word": "乱", "complexity_tier": "T3", "furigana": "luàn", "sentence_source": "generated"}, {"text": "她把厨房收拾好，不再乱了。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的作业写得很乱。", "target_word": "乱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "乱了", "label": "体标"}, {"form": "混乱", "label": "复合"}, {"form": "亂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "没有条理秩序、混乱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd4e57f7-af7c-4ea1-9953-f36f2503a567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19860, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "乱", "is_correct": true, "explanation": "正确答案。“乱”读 luàn，指事物没有条理、秩序，即本词。"}, {"text": "算", "is_correct": false, "explanation": "suàn（算）与 luàn 声母不同（s 与 l），意思是计算。"}, {"text": "烂", "is_correct": false, "explanation": "làn（烂）比 luàn 少了介音 u，声音不同，意思是腐烂。"}, {"text": "论", "is_correct": false, "explanation": "lùn（论）比 luàn 少了韵母中的 a，声音不同，意思是讨论。"}, {"text": "换", "is_correct": false, "explanation": "huàn（换）与 luàn 声母不同（h 与 l），意思是交换。"}, {"text": "惯", "is_correct": false, "explanation": "guàn（惯）与 luàn 声母不同（g 与 l），意思是习惯。"}], "explanations": {"乱": "正确答案。“乱”读 luàn，指事物没有条理、秩序，即本词。", "算": "suàn（算）与 luàn 声母不同（s 与 l），意思是计算。", "烂": "làn（烂）比 luàn 少了介音 u，声音不同，意思是腐烂。", "论": "lùn（论）比 luàn 少了韵母中的 a，声音不同，意思是讨论。", "换": "huàn（换）与 luàn 声母不同（h 与 l），意思是交换。", "惯": "guàn（惯）与 luàn 声母不同（g 与 l），意思是习惯。"}, "sentence_index": null, "correct_answer": "乱"}, "level_3": {"options": [{"text": "乱", "is_correct": true, "explanation": "“乱”指没有条理，与“干净”相对，填入后句意通顺。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，数据是否整洁不能用甜来形容。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容高度或身材，不能用来说数据。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线，与数据是否干净无关，句子不通。"}], "explanations": {"乱": "“乱”指没有条理，与“干净”相对，填入后句意通顺。", "甜": "语义：“甜”说味道，数据是否整洁不能用甜来形容。", "矮": "体貌：“矮”形容高度或身材，不能用来说数据。", "亮": "语义：“亮”说光线，与数据是否干净无关，句子不通。"}, "sentence_index": 0, "correct_answer": "乱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的手很乱，洗了好几遍还是不干净。", "explanation": "这里应该用〈脏〉。“乱”指没有条理，说手上的污垢要用“脏”。"}, {"text": "他的腿很乱，走不动了。", "explanation": "这里应该用〈疼〉。“乱”指没有条理，不能用来描述腿部的疼痛。"}, {"text": "这件衣服很乱，只要十块钱。", "explanation": "这里应该用〈便宜〉。“乱”指没有条理，不能用来说价格低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19860, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "乱", "is_correct": true, "explanation": "正确答案。“乱”读 luàn，指事物没有条理、秩序，即本词。"}, {"text": "卵", "is_correct": false, "explanation": "luǎn（卵）与 luàn 声调不同（第三声与第四声），意思是卵子。"}, {"text": "段", "is_correct": false, "explanation": "duàn（段）与 luàn 声母不同（d 与 l），意思是一段。"}, {"text": "卷", "is_correct": false, "explanation": "juàn（卷）与 luàn 声母不同（j 与 l），意思是卷起。"}, {"text": "劝", "is_correct": false, "explanation": "quàn（劝）与 luàn 声母不同（q 与 l），意思是劝说。"}, {"text": "钻", "is_correct": false, "explanation": "zuàn（钻）与 luàn 声母不同（z 与 l），意思是钻研。"}], "explanations": {"乱": "正确答案。“乱”读 luàn，指事物没有条理、秩序，即本词。", "卵": "luǎn（卵）与 luàn 声调不同（第三声与第四声），意思是卵子。", "段": "duàn（段）与 luàn 声母不同（d 与 l），意思是一段。", "卷": "juàn（卷）与 luàn 声母不同（j 与 l），意思是卷起。", "劝": "quàn（劝）与 luàn 声母不同（q 与 l），意思是劝说。", "钻": "zuàn（钻）与 luàn 声母不同（z 与 l），意思是钻研。"}, "sentence_index": null, "correct_answer": "乱"}, "level_3": {"options": [{"text": "乱", "is_correct": true, "explanation": "“乱”指没有条理，“放得太乱”说摆放杂乱，需要重新整理，句意通顺。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的身材，不能用来形容文件的摆放。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”说价格，文件的摆放状态与价格无关，句子不通。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容身材，不能用来说文件放置的样子。"}], "explanations": {"乱": "“乱”指没有条理，“放得太乱”说摆放杂乱，需要重新整理，句意通顺。", "瘦": "体貌：“瘦”形容人或动物的身材，不能用来形容文件的摆放。", "贵": "语义：“贵”说价格，文件的摆放状态与价格无关，句子不通。", "胖": "体貌：“胖”形容身材，不能用来说文件放置的样子。"}, "sentence_index": 6, "correct_answer": "乱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个西瓜乱了，已经不能吃了。", "explanation": "这里应该用〈烂〉。“乱”指没有条理，不能用来说食物腐坏。"}, {"text": "他这次的成绩很乱。", "explanation": "这里应该用〈差〉。“乱”指没有条理，不能用来评价成绩的高低。"}, {"text": "这个菜的味道很乱。", "explanation": "这里应该用〈糟糕〉。“乱”指没有条理，不能用来评价味道的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的抽屉里乱很，找不到钥匙。", "corrected_sentence": "我的抽屉里很乱，找不到钥匙。", "error_description": "语序错误：“很”应放在形容词“乱”之前，说“很乱”；“乱很”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把抽屉乱了，找东西很费劲。", "corrected_sentence": "他把抽屉弄乱了，找东西很费劲。", "error_description": "漏掉动词：“乱”不能直接放在“把”字句中作谓语，应补“弄”，说“把抽屉弄乱了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
