INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19864, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "检查数据：对信息进行核对、验证，以确保其正确、完整。", "primary_collocate": null, "pronunciation": "jiǎn chá shù jù", "ipa": "tɕjɛn˨˩ ʈʂʰa˧˥ ʂu˥˩ tɕy˥˩", "syllable_count": 4, "sentences": [{"text": "提交报告以前，请先检查数据。", "target_word": "检查数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每天早上都要检查数据。", "target_word": "检查数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他正在电脑前检查数据。", "target_word": "检查数据", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板让我下午检查数据。", "target_word": "检查数据", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "发现错误以后，她重新检查数据。", "target_word": "检查数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王检查数据的时候，发现了两个错误。", "target_word": "检查数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报告交给经理以前，你检查数据了吗？", "target_word": "检查数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们必须认真检查数据，才能保证结果正确。", "target_word": "检查数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每次交表格前都会检查数据，所以很少出错。", "target_word": "检查数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验结束后，同学们一起检查数据。", "target_word": "检查数据", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "检查了数据", "label": "体标"}, {"form": "檢查數據", "label": "繁体"}], "register": "通用", "sense_fingerprint": "核对验证信息是否正确完整", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd4e57f7-af7c-4ea1-9953-f36f2503a567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19864, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "检查数据", "is_correct": true, "explanation": "正确：检查数据指核对信息是否正确，符合“提交报告以前，请先”的语境。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与提交报告前的工作准备无关，句子不通。"}, {"text": "玩耍", "is_correct": false, "explanation": "语域：玩耍口语化、轻松，与正式的报告提交场合不符。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：发呆不是提交报告前应做的准备动作，与“请先”的要求冲突。"}], "explanations": {"检查数据": "正确：检查数据指核对信息是否正确，符合“提交报告以前，请先”的语境。", "唱歌": "语义：唱歌与提交报告前的工作准备无关，句子不通。", "玩耍": "语域：玩耍口语化、轻松，与正式的报告提交场合不符。", "发呆": "语义：发呆不是提交报告前应做的准备动作，与“请先”的要求冲突。"}, "sentence_index": 0, "correct_answer": "检查数据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每年都去医院检查数据。", "explanation": "这里应该用〈体检〉。检查数据针对信息是否正确，人的身体健康检查要说体检。"}, {"text": "海关在机场检查数据的重量，看行李有没有超重。", "explanation": "这里应该用〈称〉。检查数据是核对信息是否正确，不指称量重量。"}, {"text": "他在银行检查数据，准备取款。", "explanation": "这里应该用〈查询〉。检查数据强调核对数据是否正确，查看余额要说查询。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "检查数据", "is_correct": true, "explanation": "正确：检查数据指核对信息，符合“报告交给经理以前，你”之后的语境。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞与交报告的工作流程无关，句子不通。"}, {"text": "逛街", "is_correct": false, "explanation": "语域：逛街是轻松的日常活动，与工作汇报的场景不协调。"}, {"text": "打游戏", "is_correct": false, "explanation": "语义：打游戏与交报告给经理的工作顺序相悖，句意不合理。"}], "explanations": {"检查数据": "正确：检查数据指核对信息，符合“报告交给经理以前，你”之后的语境。", "跳舞": "语义：跳舞与交报告的工作流程无关，句子不通。", "逛街": "语域：逛街是轻松的日常活动，与工作汇报的场景不协调。", "打游戏": "语义：打游戏与交报告给经理的工作顺序相悖，句意不合理。"}, "sentence_index": 6, "correct_answer": "检查数据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们一起检查数据的颜色。", "explanation": "这里应该用〈看〉。检查数据是核对信息是否正确，不指查看物品的外观颜色。"}, {"text": "同学们一起检查数据的心情。", "explanation": "这里应该用〈关心〉。检查数据是核对信息是否正确，不指关注别人的心情。"}, {"text": "同学们一起检查数据的味道。", "explanation": "这里应该用〈尝〉。检查数据是核对信息是否正确，不指品尝食物的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天检查过数据。", "corrected_sentence": "我明天检查数据。", "error_description": "体标误用：“过”表示已经发生或曾经历的动作，不能与表示将来的“明天”同用。正确：删去“过”，应说“我明天检查数据”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天不检查数据。", "corrected_sentence": "他昨天没检查数据。", "error_description": "错误：否定已发生的动作要用“没”，不用“不”。正确：“他昨天没检查数据”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
