INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19868, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "修理，使损坏的东西恢复原样或正常工作。", "primary_collocate": null, "pronunciation": "xiū", "ipa": "ɕjoʊ˥", "syllable_count": 1, "sentences": [{"text": "软件出问题，要马上修。", "target_word": "修", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "我的自行车坏了，明天要去修。", "target_word": "修", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸会修电脑，也会修手机。", "target_word": "修", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水管坏了，请师傅来修一下。", "target_word": "修", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋坏了，我想拿去修。", "target_word": "修", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把窗户修好了，屋里不再冷。", "target_word": "修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视机坏了，你能不能修？", "target_word": "修", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆旧车修了三次，还是不能开。", "target_word": "修", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机屏幕碎了，我下午去店里修。", "target_word": "修", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在门口修着自行车，没看见我。", "target_word": "修", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "修了", "label": "体标"}, {"form": "修着", "label": "体标"}, {"form": "修修", "label": "重叠"}, {"form": "修理", "label": "复合"}], "register": "口语", "sense_fingerprint": "修理坏掉的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd4e57f7-af7c-4ea1-9953-f36f2503a567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19868, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "修", "is_correct": true, "explanation": "修 xiū（第一声）是本词，意思是修理。"}, {"text": "秀", "is_correct": false, "explanation": "xiù（第四声）与 xiū（第一声）声调不同，意思是秀丽、展示。"}, {"text": "袖", "is_correct": false, "explanation": "xiù（第四声）与 xiū（第一声）声调不同，意思是衣袖。"}, {"text": "锈", "is_correct": false, "explanation": "xiù（第四声）与 xiū（第一声）声调不同，意思是金属生锈。"}], "explanations": {"修": "修 xiū（第一声）是本词，意思是修理。", "秀": "xiù（第四声）与 xiū（第一声）声调不同，意思是秀丽、展示。", "袖": "xiù（第四声）与 xiū（第一声）声调不同，意思是衣袖。", "锈": "xiù（第四声）与 xiū（第一声）声调不同，意思是金属生锈。"}, "sentence_index": null, "correct_answer": "修"}, "level_3": {"options": [{"text": "修", "is_correct": true, "explanation": "正确：修指修理，使出问题的软件恢复正常，符合“要马上”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃与软件出问题无关，句子不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉无法解决软件故障，与“要马上”的语境冲突。"}, {"text": "送", "is_correct": false, "explanation": "语义：送是递交、赠予，不能让出问题的软件恢复正常，与“要马上”的修理需求不符。"}], "explanations": {"修": "正确：修指修理，使出问题的软件恢复正常，符合“要马上”的语境。", "吃": "语义：吃与软件出问题无关，句子不通。", "睡觉": "语义：睡觉无法解决软件故障，与“要马上”的语境冲突。", "送": "语义：送是递交、赠予，不能让出问题的软件恢复正常，与“要马上”的修理需求不符。"}, "sentence_index": 0, "correct_answer": "修"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天在厨房修饭。", "explanation": "这里应该用〈做〉。修指修理已坏的东西，不能用于做饭。"}, {"text": "农民春天修庄稼。", "explanation": "这里应该用〈种〉。修指修理，不指播种庄稼。"}, {"text": "学生在课堂上修数学题。", "explanation": "这里应该用〈做〉。修指修理已坏的东西，不能用于做数学题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19868, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "修", "is_correct": true, "explanation": "修 xiū（第一声）是本词，意思是修理。"}, {"text": "绣", "is_correct": false, "explanation": "xiù（第四声）与 xiū（第一声）声调不同，意思是刺绣。"}, {"text": "嗅", "is_correct": false, "explanation": "xiù（第四声）与 xiū（第一声）声调不同，意思是用鼻子闻。"}, {"text": "朽", "is_correct": false, "explanation": "xiǔ（第三声）与 xiū（第一声）声调不同，意思是腐烂、腐朽。"}], "explanations": {"修": "修 xiū（第一声）是本词，意思是修理。", "绣": "xiù（第四声）与 xiū（第一声）声调不同，意思是刺绣。", "嗅": "xiù（第四声）与 xiū（第一声）声调不同，意思是用鼻子闻。", "朽": "xiǔ（第三声）与 xiū（第一声）声调不同，意思是腐烂、腐朽。"}, "sentence_index": null, "correct_answer": "修"}, "level_3": {"options": [{"text": "修", "is_correct": true, "explanation": "正确：修指修理，符合“电视机坏了”之后的求助语境。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱与电视机坏了的求助语境无关，句子不通。"}, {"text": "跑", "is_correct": false, "explanation": "语义：跑与电视机故障无关，句意不合理。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗与电视机坏了的求助语境无关，“能不能洗”说的不是修理，句意不通。"}], "explanations": {"修": "正确：修指修理，符合“电视机坏了”之后的求助语境。", "唱": "语义：唱与电视机坏了的求助语境无关，句子不通。", "跑": "语义：跑与电视机故障无关，句意不合理。", "洗": "语义：洗与电视机坏了的求助语境无关，“能不能洗”说的不是修理，句意不通。"}, "sentence_index": 6, "correct_answer": "修"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天晚上修日记，很认真。", "explanation": "这里应该用〈写〉。修指修理，不能用于写日记。"}, {"text": "她在舞台上修歌，大家都听。", "explanation": "这里应该用〈唱〉。修指修理，不能用于唱歌。"}, {"text": "老师在课堂上修故事。", "explanation": "这里应该用〈讲〉。修指修理，不能用于讲故事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在厨房里着修收音机。", "corrected_sentence": "妈妈在厨房里修着收音机。", "error_description": "错误：“着”放在动词“修”之前。正确：“着”应紧跟动词，说“修着收音机”，表示动作正在进行。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈昨天不修电脑。", "corrected_sentence": "妈妈昨天没修电脑。", "error_description": "错误：否定已发生的动作要用“没”，不用“不”。正确：“妈妈昨天没修电脑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
