INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19869, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "修理使恢复完好状态。", "primary_collocate": null, "pronunciation": "xiū hǎo", "ipa": "ɕi̯ou˥ xau̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "他把我的自行车修好了。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅明天就能把电视修好。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑修好以后，我马上给你打电话。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双旧鞋请人修好了，又能穿了。", "target_word": "修好", "complexity_tier": "T3", "furigana": "xiū hǎo", "sentence_source": "generated"}, {"text": "爸爸花了一个下午才把水管修好。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部手机修好要三百块钱。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的车修好了，明天可以来取。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这把旧椅子修好，继续用它。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调修好后，房间里很快凉快起来了。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他修好了门锁，大家都很高兴。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "修好了", "label": "体标"}, {"form": "修好过", "label": "体标"}, {"form": "修不好", "label": "否定可能补语"}, {"form": "修得好", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "修理某物，使其恢复完好状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e5e0e04-19d0-4826-8ae8-48040290f7a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19869, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修好", "is_correct": true, "explanation": "修好表示修理使其恢复完好，与“我的自行车”搭配，句意通顺。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：自行车不能吃，“吃掉”与句中的“自行车”相冲突。"}, {"text": "喝掉", "is_correct": false, "explanation": "搭配：“喝掉”的对象通常是液体或饮料，不能和自行车搭配。"}, {"text": "煮掉", "is_correct": false, "explanation": "语义：自行车不能放进锅里煮，“煮掉”与句中的对象无法对应。"}], "explanations": {"修好": "修好表示修理使其恢复完好，与“我的自行车”搭配，句意通顺。", "吃掉": "语义：自行车不能吃，“吃掉”与句中的“自行车”相冲突。", "喝掉": "搭配：“喝掉”的对象通常是液体或饮料，不能和自行车搭配。", "煮掉": "语义：自行车不能放进锅里煮，“煮掉”与句中的对象无法对应。"}, "sentence_index": 0, "correct_answer": "修好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的感冒吃了药，三天就修好了。", "explanation": "这里应该用〈治好〉。修好用于器物的修理，人的病痛要用治好。"}, {"text": "妈妈先把晚饭修好，大家就可以吃了。", "explanation": "这里应该用〈做好〉。饭菜是做出来的，修好只用于把坏了的东西修理好。"}, {"text": "茶已经修好了，大家快来喝吧。", "explanation": "这里应该用〈泡好〉。茶是泡出来的，不能说修好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19869, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修好", "is_correct": true, "explanation": "修好表示修理完毕，与“来取”的语境相符，句意通顺。"}, {"text": "写好", "is_correct": false, "explanation": "语义：车不能被写，“写好”的对象是文字，与句中的“车”相冲突。"}, {"text": "读完", "is_correct": false, "explanation": "语义：车不能被阅读，“读完”与句中的“车”无法对应。"}, {"text": "炒好", "is_correct": false, "explanation": "搭配：“炒”的对象是食物，不能说炒车。"}], "explanations": {"修好": "修好表示修理完毕，与“来取”的语境相符，句意通顺。", "写好": "语义：车不能被写，“写好”的对象是文字，与句中的“车”相冲突。", "读完": "语义：车不能被阅读，“读完”与句中的“车”无法对应。", "炒好": "搭配：“炒”的对象是食物，不能说炒车。"}, "sentence_index": 6, "correct_answer": "修好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把这盘鸡蛋修好了，大家快来吃。", "explanation": "这里应该用〈炒好〉。鸡蛋是炒出来的，修好只用于修理坏了的东西。"}, {"text": "他很快就把婚礼修好了，大家都来祝贺。", "explanation": "这里应该用〈办好〉。婚礼要筹办、操办，修好只用于修理坏了的东西。"}, {"text": "他的理想修好了，将来要当医生。", "explanation": "这里应该用〈确定〉。理想是树立、确定的，修好只用于修理坏了的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于把我的车修好了了。", "corrected_sentence": "他终于把我的车修好了。", "error_description": "错误形式：修好了了；正确形式：修好了。句末的“了”只需要一个，多加一个“了”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19869, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没把这台机器修好了。", "corrected_sentence": "我没把这台机器修好。", "error_description": "错误形式：我没把这台机器修好了；正确形式：我没把这台机器修好。用“没”表示未完成时，动词后不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
