INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19870, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词。表示同样、并列或加强语气。", "primary_collocate": null, "pronunciation": "yě", "ipa": "jɛ˨˩", "syllable_count": 1, "sentences": [{"text": "我喜欢茶，我朋友也喜欢茶。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是学生，我也是学生。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去，我也去。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会说英语，也会说汉语。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天很冷，明天也很冷。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥爱看书，姐姐也爱看书。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没吃早饭，他也没吃。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店东西好，价格也不贵。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我累了，你也累了吧？", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在北京，他爸爸也住在北京。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "也许", "label": "复合"}], "register": "中性", "sense_fingerprint": "也：表示同样、并列，另一人或另一件事与前面相同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4177ca5c-ed1d-4b04-aa07-385752d02c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19870, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "也", "is_correct": true, "explanation": "正确：yě（第三声）是“也”，表示同样、并列，另一人或另一件事与前面相同。"}, {"text": "夜", "is_correct": false, "explanation": "yè（第四声）与 yě 声调不同，意思是“夜晚”。"}, {"text": "叶", "is_correct": false, "explanation": "yè（第四声）与 yě 声调不同，意思是“树叶”。"}, {"text": "爷", "is_correct": false, "explanation": "yé（第二声）与 yě 声调不同，意思是“爷爷”。"}, {"text": "椰", "is_correct": false, "explanation": "yē（第一声）与 yě 声调不同，意思是“椰子”。"}], "explanations": {"也": "正确：yě（第三声）是“也”，表示同样、并列，另一人或另一件事与前面相同。", "夜": "yè（第四声）与 yě 声调不同，意思是“夜晚”。", "叶": "yè（第四声）与 yě 声调不同，意思是“树叶”。", "爷": "yé（第二声）与 yě 声调不同，意思是“爷爷”。", "椰": "yē（第一声）与 yě 声调不同，意思是“椰子”。"}, "sentence_index": null, "correct_answer": "也"}, "level_3": {"options": [{"text": "也", "is_correct": true, "explanation": "正确：“也”表示同样，我朋友和“我”一样喜欢茶，与句意相符。"}, {"text": "又", "is_correct": false, "explanation": "语义：“又”表示重复，前文并未说明朋友之前喜欢过茶，句意不合。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，前后句并无对立，不能用“却”。"}, {"text": "并", "is_correct": false, "explanation": "搭配：“并”一般与否定词连用，不直接修饰肯定动词“喜欢”。"}], "explanations": {"也": "正确：“也”表示同样，我朋友和“我”一样喜欢茶，与句意相符。", "又": "语义：“又”表示重复，前文并未说明朋友之前喜欢过茶，句意不合。", "却": "语义：“却”表示转折，前后句并无对立，不能用“却”。", "并": "搭配：“并”一般与否定词连用，不直接修饰肯定动词“喜欢”。"}, "sentence_index": 0, "correct_answer": "也"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他会说英语，也不会说英语。", "explanation": "同一主语的肯定与否定直接矛盾，句意不通；“也”只能连接同向或并列的内容。应改写谓语，例如“他会说英语，却不太会写作”。"}, {"text": "今天很冷，我也很热。", "explanation": "这里的“也”表示同样，“冷”与“热”相反，应改用〈却〉表示转折。"}, {"text": "他第一次来，也第二次来了。", "explanation": "这里的“也”表示同样，不能表示次数上的重复，应改用〈又〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0b14b86-4dcf-4ad2-830b-fc3605394ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19870, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "也", "is_correct": true, "explanation": "正确：yě（第三声）是“也”，表示同样、并列，另一人或另一件事与前面相同。"}, {"text": "业", "is_correct": false, "explanation": "yè（第四声）与 yě 声调不同，意思是“事业”。"}, {"text": "耶", "is_correct": false, "explanation": "yē（第一声）与 yě 声调不同，意思是“耶稣”。"}, {"text": "以", "is_correct": false, "explanation": "yǐ（第三声）与 yě 韵母不同（i 与 e），意思是“以为”。"}], "explanations": {"也": "正确：yě（第三声）是“也”，表示同样、并列，另一人或另一件事与前面相同。", "业": "yè（第四声）与 yě 声调不同，意思是“事业”。", "耶": "yē（第一声）与 yě 声调不同，意思是“耶稣”。", "以": "yǐ（第三声）与 yě 韵母不同（i 与 e），意思是“以为”。"}, "sentence_index": null, "correct_answer": "也"}, "level_3": {"options": [{"text": "也", "is_correct": true, "explanation": "正确：“也”表示同样，他和“我”一样没吃，与前句的平行关系相符。"}, {"text": "偏", "is_correct": false, "explanation": "语义：“偏”表示故意与常理相反，与前句的平行关系不符。"}, {"text": "才", "is_correct": false, "explanation": "搭配：“才”一般不与“没”直接连用，此处无法组成通顺的搭配。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示限定，句意变为“仅他没吃”，与前句的并列关系不符。"}], "explanations": {"也": "正确：“也”表示同样，他和“我”一样没吃，与前句的平行关系相符。", "偏": "语义：“偏”表示故意与常理相反，与前句的平行关系不符。", "才": "搭配：“才”一般不与“没”直接连用，此处无法组成通顺的搭配。", "只": "语义：“只”表示限定，句意变为“仅他没吃”，与前句的并列关系不符。"}, "sentence_index": 6, "correct_answer": "也"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天去了公园，也去了公园。", "explanation": "这里的“也”表示同样，但表示重复的动作应改用〈又〉。"}, {"text": "这本书很好看，我也很便宜。", "explanation": "这里的“也”连接的两项不平行，“书好看”与“我便宜”之间没有可以“同样”对应的关系，句意不通。"}, {"text": "他很聪明，也很笨。", "explanation": "这里的“也”表示同样，“聪明”与“笨”相反，应改用〈却〉表示转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0b14b86-4dcf-4ad2-830b-fc3605394ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没也吃晚饭。", "corrected_sentence": "我也没吃晚饭。", "error_description": "错误：“也”应放在“没”之前，写作“也没吃”；“没也吃”的语序是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0b14b86-4dcf-4ad2-830b-fc3605394ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹会唱歌，弟弟会也唱歌。", "corrected_sentence": "妹妹会唱歌，弟弟也会唱歌。", "error_description": "错误：“会也唱歌”，“也”被放在助动词“会”与动词“唱”之间；正确：“也会唱歌”，“也”应放在助动词“会”之前，表示并列。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0b14b86-4dcf-4ad2-830b-fc3605394ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
