INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19872, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过手机、电脑等设备发送信息给别人。", "primary_collocate": null, "pronunciation": "fā xiāo xi", "ipa": "fa⁵⁵ ɕiau̯⁵⁵ ɕi", "syllable_count": 3, "sentences": [{"text": "电脑为什么给这个人发消息？", "target_word": "发消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每天晚上给妈妈发消息。", "target_word": "发消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你到了以后给我发消息。", "target_word": "发消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在手机上给朋友发消息。", "target_word": "发消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上课的时候不要发消息。", "target_word": "发消息", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她正在用电脑发消息。", "target_word": "发消息", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想给老师发消息，问明天的事。", "target_word": "发消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以先发消息，再打电话。", "target_word": "发消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他发消息给我，说今天不来了。", "target_word": "发消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们喜欢给同学发消息。", "target_word": "发消息", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "发了消息", "label": "体标"}, {"form": "发过消息", "label": "体标"}, {"form": "發消息", "label": "繁体"}], "register": "口语", "sense_fingerprint": "用手机、电脑把文字信息发给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b2747cf-51da-4bed-8a3e-6845ab573b37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发消息", "is_correct": true, "explanation": "正确：“发消息”指通过设备给人发送信息，与“电脑”作主语、“给这个人”搭配自然。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：电脑不能给人洗澡，主语与动作不相容。"}, {"text": "剪头发", "is_correct": false, "explanation": "语义：剪头发需要人的双手，电脑无法完成这个动作。"}, {"text": "通话", "is_correct": false, "explanation": "配价：“通话”是不及物动词，不能用“给这个人”引出对象，应说“和这个人通话”。"}], "explanations": {"发消息": "正确：“发消息”指通过设备给人发送信息，与“电脑”作主语、“给这个人”搭配自然。", "洗澡": "语义：电脑不能给人洗澡，主语与动作不相容。", "剪头发": "语义：剪头发需要人的双手，电脑无法完成这个动作。", "通话": "配价：“通话”是不及物动词，不能用“给这个人”引出对象，应说“和这个人通话”。"}, "sentence_index": 0, "correct_answer": "发消息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这本书发消息给朋友了。", "explanation": "这里应该用〈寄〉。〈发消息〉只用于文字信息，寄送实物要用〈寄〉。"}, {"text": "他用钥匙给朋友发消息。", "explanation": "这里应该用〈开〉。用钥匙是开门、开锁，不是发消息；〈发消息〉要借助手机、电脑等能传送文字的设备。"}, {"text": "这棵树给朋友发消息。", "explanation": "这里应该用〈告诉〉。〈发消息〉的主语须是能使用手机、电脑的人，树不能发消息，只能由人去告诉朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发消息", "is_correct": true, "explanation": "正确：“发消息”表示给人发送信息，与“想给老师”和“问明天的事”相符。"}, {"text": "洗衣服", "is_correct": false, "explanation": "语义：“洗衣服”是家务，与“问明天的事”的目的不相容，句子不通。"}, {"text": "见面", "is_correct": false, "explanation": "配价：“见面”要用“跟”或“和”引出对象，不能说“给老师见面”。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与“问明天的事”无关，“给老师吃饭”的意思也不合理。"}], "explanations": {"发消息": "正确：“发消息”表示给人发送信息，与“想给老师”和“问明天的事”相符。", "洗衣服": "语义：“洗衣服”是家务，与“问明天的事”的目的不相容，句子不通。", "见面": "配价：“见面”要用“跟”或“和”引出对象，不能说“给老师见面”。", "吃饭": "语义：“吃饭”与“问明天的事”无关，“给老师吃饭”的意思也不合理。"}, "sentence_index": 6, "correct_answer": "发消息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们喜欢给桌子发消息。", "explanation": "这里应该用〈擦〉。〈给〉后接桌子适合〈擦〉这类动作；〈发消息〉的接收者须是能收到文字信息的人。"}, {"text": "孩子们喜欢当面给同学发消息。", "explanation": "这里应该用〈口头告诉〉。〈发消息〉要通过手机、电脑等设备传送，当面说话不能用〈发消息〉。"}, {"text": "孩子们喜欢给窗户发消息。", "explanation": "这里应该用〈关〉。窗户是用来关的，不能接收消息；〈发消息〉的接收者须是能收到文字信息的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天给他了发消息。", "corrected_sentence": "我昨天给他发了消息。", "error_description": "错误：“了”的位置不对。正确应为“发了消息”，“了”紧跟动词表示完成；“了发消息”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师每天学生发消息。", "corrected_sentence": "老师每天给学生发消息。", "error_description": "错误：缺少“给”。“发消息”后要用“给”引出接收者，“学生发消息”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
