INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19873, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指用户输入账号和密码以进入计算机系统、网站或应用程序的过程。", "primary_collocate": null, "pronunciation": "dēng lù", "ipa": "təŋ⁵⁵ lu⁵¹", "syllable_count": 2, "sentences": [{"text": "为什么不让那个人登录？", "target_word": "登录", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "我忘了密码，不能登录。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先输入账号，再登录。", "target_word": "登录", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天早上都登录邮箱。", "target_word": "登录", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个网站要先登录才能买东西。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你用手机号码就可以登录。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的电脑登录不了学校的网站。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "登录以后，你能看到自己的信息。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她正在登录银行的手机软件。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "密码错了三次，他就不能再登录了。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "登录了", "label": "体标"}, {"form": "登录过", "label": "体标"}, {"form": "登录名", "label": "复合"}, {"form": "登录密码", "label": "复合"}, {"form": "登錄", "label": "繁体"}], "register": "中性", "sense_fingerprint": "输入账号和密码，进入电脑系统、网站或应用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b2747cf-51da-4bed-8a3e-6845ab573b37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19873, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "登录", "is_correct": true, "explanation": "正确：“登录”指输入账号和密码进入系统，句中“不让那个人登录”即不让他进入系统。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”是金属氧化的结果，人不会生锈，“不让那个人生锈”句意荒谬。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：“凝固”指液体变稠变硬，不用于人，“不让那个人凝固”句意荒谬。"}, {"text": "发电", "is_correct": false, "explanation": "语义：“发电”是设备或电站的功能，人不能发电，“不让那个人发电”句意荒谬。"}], "explanations": {"登录": "正确：“登录”指输入账号和密码进入系统，句中“不让那个人登录”即不让他进入系统。", "生锈": "语义：“生锈”是金属氧化的结果，人不会生锈，“不让那个人生锈”句意荒谬。", "凝固": "语义：“凝固”指液体变稠变硬，不用于人，“不让那个人凝固”句意荒谬。", "发电": "语义：“发电”是设备或电站的功能，人不能发电，“不让那个人发电”句意荒谬。"}, "sentence_index": 0, "correct_answer": "登录"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都登录公司。", "explanation": "这里应该用〈进入〉。“登录”指输入账号和密码进入网站或系统，不能用来说走进公司这样的实体场所。"}, {"text": "飞机终于登录了机场。", "explanation": "这里应该用〈登陆〉。“登陆”指飞机、船只到达陆地，与“登录”同音但意思不同，“登录”不能用于飞机。"}, {"text": "宇航员终于登录了月球。", "explanation": "这里应该用〈登上〉。“登上”指到达某处，宇航员登上月球；“登录”指输入账号和密码进入网站或系统，不能用于月球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19873, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "登录", "is_correct": true, "explanation": "正确：“登录”能与“不了”搭配，表示无法进入学校的网站，句意通顺。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”指在户外行走，电脑不能散步，“散步不了学校的网站”句意荒谬。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”的主体是人，电脑不能结婚，句子与常识冲突。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：“驾临”是敬辞，只用于尊贵的客人到访，用在“我的电脑”这类语境中语域不合。"}], "explanations": {"登录": "正确：“登录”能与“不了”搭配，表示无法进入学校的网站，句意通顺。", "散步": "语义：“散步”指在户外行走，电脑不能散步，“散步不了学校的网站”句意荒谬。", "结婚": "语义：“结婚”的主体是人，电脑不能结婚，句子与常识冲突。", "驾临": "语域：“驾临”是敬辞，只用于尊贵的客人到访，用在“我的电脑”这类语境中语域不合。"}, "sentence_index": 6, "correct_answer": "登录"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她们明天去登录，看日出。", "explanation": "这里应该用〈登山〉。“登山”指攀登山峰，“登录”指输入账号进入系统，不能用于爬山。"}, {"text": "他登录了那个文件。", "explanation": "这里应该用〈打开〉。“登录”用于进入网站或系统，文件要用“打开”，不能说“登录文件”。"}, {"text": "他终于登录了珠峰，大家都为他鼓掌。", "explanation": "这里应该用〈登顶〉。“登顶”指攀登到山顶，“登录”指输入账号进入系统，不能用于山峰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他顺利登录了了系统。", "corrected_sentence": "他顺利登录了系统。", "error_description": "错误：“了”重复。“登录”后只需一个“了”，应为“登录了系统”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天都把登录学习平台。", "corrected_sentence": "我每天都登录学习平台。", "error_description": "错误：多出“把”。“把”字句需要“把+名词+动词”结构，“把登录学习平台”不成立，应删去“把”，为“我每天都登录学习平台。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19875, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "义务", "is_correct": true, "explanation": "正确：“权利”指可以做的事，“义务”指必须做的事，二者构成反义关系。"}, {"text": "房间", "is_correct": false, "explanation": "与“权利”没有反义关系，二者不是对立的概念。"}, {"text": "天气", "is_correct": false, "explanation": "与“权利”没有反义关系，二者语义无对立。"}, {"text": "学校", "is_correct": false, "explanation": "与“权利”没有反义关系，二者不构成对立。"}], "correct_answer": "义务", "explanations": {"义务": "正确：“权利”指可以做的事，“义务”指必须做的事，二者构成反义关系。", "房间": "与“权利”没有反义关系，二者不是对立的概念。", "天气": "与“权利”没有反义关系，二者语义无对立。", "学校": "与“权利”没有反义关系，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19875, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "义务", "is_correct": true, "explanation": "正确：“权利”与“义务”是一对反义词，分别指可以做的事和必须做的事。"}, {"text": "桌子", "is_correct": false, "explanation": "与“权利”没有反义关系，二者不构成对立。"}, {"text": "汽车", "is_correct": false, "explanation": "与“权利”没有反义关系，二者语义无对立。"}, {"text": "公园", "is_correct": false, "explanation": "与“权利”没有反义关系，二者不构成对立。"}], "correct_answer": "义务", "explanations": {"义务": "正确：“权利”与“义务”是一对反义词，分别指可以做的事和必须做的事。", "桌子": "与“权利”没有反义关系，二者不构成对立。", "汽车": "与“权利”没有反义关系，二者语义无对立。", "公园": "与“权利”没有反义关系，二者不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19875, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指法律或道德上允许人们做某事或拥有某物的资格。", "primary_collocate": null, "pronunciation": "quán lì", "ipa": "tɕʰɥɛn˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "用户有权利知道这些。", "target_word": "权利", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "每个公民都有选举的权利。", "target_word": "权利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子有受教育的权利。", "target_word": "权利", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你没有权利看别人的信。", "target_word": "权利", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "法律保护我们的权利。", "target_word": "权利", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人有休息的权利。", "target_word": "权利", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买了票的人有权利进去。", "target_word": "权利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他放弃了投票的权利。", "target_word": "权利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板不能不给工人休假，这是工人的权利。", "target_word": "权利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人都有说话的权利，请让他说完。", "target_word": "权利", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项权利", "label": "量词"}, {"form": "權利", "label": "繁体"}, {"form": "权利人", "label": "复合"}], "register": "中性", "sense_fingerprint": "法律或道德上允许人做某事、拥有某物的资格（有权利、享有权利、保护权利）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b2747cf-51da-4bed-8a3e-6845ab573b37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19875, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "权利", "is_correct": true, "explanation": "正确：“用户有权利知道这些”表示法律或道德允许用户知道这些信息，语义通顺。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是物件，“用户有手机知道这些”句意不通，无法表达“知道这些”的资格。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人可以拥有的东西，与“用户有……知道这些”的语义不合。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”是物件，“用户有房子知道这些”句意不通，无法表达“知道这些”的资格。"}], "explanations": {"权利": "正确：“用户有权利知道这些”表示法律或道德允许用户知道这些信息，语义通顺。", "手机": "语义：“手机”是物件，“用户有手机知道这些”句意不通，无法表达“知道这些”的资格。", "天气": "语义：“天气”不是人可以拥有的东西，与“用户有……知道这些”的语义不合。", "房子": "语义：“房子”是物件，“用户有房子知道这些”句意不通，无法表达“知道这些”的资格。"}, "sentence_index": 0, "correct_answer": "权利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你有权利遵守学校的规定。", "explanation": "这里应该用〈义务〉。“权利”指法律或道德允许做的事，遵守规定是必须履行的责任，应说“义务”。"}, {"text": "市长有权利任命官员。", "explanation": "这里应该用〈权力〉。“权力”指支配、命令别人的力量，任命官员属于权力；“权利”指法律或道德允许的资格。"}, {"text": "公司今年的权利很高。", "explanation": "这里应该用〈利润〉。“利润”指收入减去成本后的盈余，“权利”指法律或道德允许的资格，不能用来说公司的盈利。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "权利", "is_correct": true, "explanation": "正确：“买了票的人有权利进去”表示买票者有资格进入，语义通顺。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“饭”不能作为进入场所的资格，“买了票的人有饭进去”句意荒谬。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是可以凭借进入的东西，句意不通。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”不是可以拥有并凭借进入的资格，“有脚步进去”不通。"}], "explanations": {"权利": "正确：“买了票的人有权利进去”表示买票者有资格进入，语义通顺。", "饭": "语义：“饭”不能作为进入场所的资格，“买了票的人有饭进去”句意荒谬。", "颜色": "语义：“颜色”不是可以凭借进入的东西，句意不通。", "脚步": "语义：“脚步”不是可以拥有并凭借进入的资格，“有脚步进去”不通。"}, "sentence_index": 6, "correct_answer": "权利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的权利很重，压得他喘不过气。", "explanation": "这里应该用〈责任〉。“责任”可以“重”，压得人喘不过气；“权利”不能说“重”。"}, {"text": "他对这件事负有权利。", "explanation": "这里应该用〈责任〉。“负有”后面接“责任”，不能接“权利”。"}, {"text": "他担任了公司的权利。", "explanation": "这里应该用〈职务〉。“担任”的对象是职务、职位，“权利”不能被担任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他享有一把重要的权利。", "corrected_sentence": "他享有一项重要的权利。", "error_description": "量词错误：“权利”的量词应为“项”，不能用“把”，“把”用于有柄的器具。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生有提问的权利人，老师应该耐心回答。", "corrected_sentence": "学生有提问的权利，老师应该耐心回答。", "error_description": "复合词误用：“权利人”指权利的持有者，这里表示“权利”本身，应说“提问的权利”，不能用“权利人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
