INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19877, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "情态动词。表示对将来或某种情况的可能性的推测。", "primary_collocate": null, "pronunciation": "huì", "ipa": "xweɪ˥˩", "syllable_count": 1, "sentences": [{"text": "明天可能会下雨，你带伞吧。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天这么黑，他不会来了。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样做，妈妈会不高兴的。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别担心，他一定会同意的。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在出发，我们八点会到家。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很认真，一定会考得很好。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不吃早饭，上午会很饿的。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她这么聪明，会找到办法的。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太晚了，他今天不会来看你。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放心，这件事我会告诉他的。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "会：表示对将来或某种情况的可能性的推测", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4177ca5c-ed1d-4b04-aa07-385752d02c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19877, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "会", "is_correct": true, "explanation": "正确：huì（第四声）是“会”，此处表示对将来或某种情况的可能性的推测。"}, {"text": "回", "is_correct": false, "explanation": "huí（第二声）与 huì 声调不同，意思是“回来、回答”。"}, {"text": "毁", "is_correct": false, "explanation": "huǐ（第三声）与 huì 声调不同，意思是“毁坏”。"}, {"text": "挥", "is_correct": false, "explanation": "huī（第一声）与 huì 声调不同，意思是“挥动”。"}, {"text": "灰", "is_correct": false, "explanation": "huī（第一声）与 huì 声调不同，意思是“灰色”。"}, {"text": "愧", "is_correct": false, "explanation": "kuì（第四声）与 huì 声母不同（k 与 h），意思是“惭愧”。"}], "explanations": {"会": "正确：huì（第四声）是“会”，此处表示对将来或某种情况的可能性的推测。", "回": "huí（第二声）与 huì 声调不同，意思是“回来、回答”。", "毁": "huǐ（第三声）与 huì 声调不同，意思是“毁坏”。", "挥": "huī（第一声）与 huì 声调不同，意思是“挥动”。", "灰": "huī（第一声）与 huì 声调不同，意思是“灰色”。", "愧": "kuì（第四声）与 huì 声母不同（k 与 h），意思是“惭愧”。"}, "sentence_index": null, "correct_answer": "会"}, "level_3": {"options": [{"text": "会", "is_correct": true, "explanation": "正确：“会”表示对将来的可能性的推测，与“可能”搭配，语意通顺。"}, {"text": "曾", "is_correct": false, "explanation": "语义：“曾”表示过去的经历，与“明天”的将来时间冲突，句意不通。"}, {"text": "得", "is_correct": false, "explanation": "语义：“得”表示必须，与“可能”表示的推测相矛盾，句意不通。"}, {"text": "该", "is_correct": false, "explanation": "语义：“该”表示应当，与“可能”表示的推测相悖，句意不通。"}], "explanations": {"会": "正确：“会”表示对将来的可能性的推测，与“可能”搭配，语意通顺。", "曾": "语义：“曾”表示过去的经历，与“明天”的将来时间冲突，句意不通。", "得": "语义：“得”表示必须，与“可能”表示的推测相矛盾，句意不通。", "该": "语义：“该”表示应当，与“可能”表示的推测相悖，句意不通。"}, "sentence_index": 0, "correct_answer": "会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盏灯一定会读书的。", "explanation": "这里的“会”误用为能力义，灯不能读书，此句应表示推测，不能指无生命物体的能力。"}, {"text": "明天的会很高兴。", "explanation": "这里的“会”是名词“会议”，会议不能用“高兴”形容，与表示推测的动词义无关。"}, {"text": "他在机场会了一台电脑。", "explanation": "这里的“会”是“见面”之义，只用于人，电脑不能用“会”，与表示推测的动词义无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0b14b86-4dcf-4ad2-830b-fc3605394ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19877, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "会", "is_correct": true, "explanation": "正确：huì（第四声）是“会”，此处表示对将来或某种情况的可能性的推测。"}, {"text": "悔", "is_correct": false, "explanation": "huǐ（第三声）与 huì 声调不同，意思是“后悔”。"}, {"text": "辉", "is_correct": false, "explanation": "huī（第一声）与 huì 声调不同，意思是“光辉”。"}, {"text": "贵", "is_correct": false, "explanation": "guì（第四声）与 huì 声母不同（g 与 h），意思是“价格高”。"}, {"text": "退", "is_correct": false, "explanation": "tuì（第四声）与 huì 声母不同（t 与 h），意思是“后退”。"}], "explanations": {"会": "正确：huì（第四声）是“会”，此处表示对将来或某种情况的可能性的推测。", "悔": "huǐ（第三声）与 huì 声调不同，意思是“后悔”。", "辉": "huī（第一声）与 huì 声调不同，意思是“光辉”。", "贵": "guì（第四声）与 huì 声母不同（g 与 h），意思是“价格高”。", "退": "tuì（第四声）与 huì 声母不同（t 与 h），意思是“后退”。"}, "sentence_index": null, "correct_answer": "会"}, "level_3": {"options": [{"text": "会", "is_correct": true, "explanation": "正确：“会”表示对结果的推测，“不吃早饭”之后“很饿”是可能的推断。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢”表示有胆量，饿不能靠胆量决定，句意不通。"}, {"text": "肯", "is_correct": false, "explanation": "语义：“肯”表示愿意，饿与否不取决于意愿，句意不通。"}, {"text": "须", "is_correct": false, "explanation": "语法：“须”后需接动词，不能直接接“很饿”；且“须”属书面语，与口语句不协调。"}], "explanations": {"会": "正确：“会”表示对结果的推测，“不吃早饭”之后“很饿”是可能的推断。", "敢": "语义：“敢”表示有胆量，饿不能靠胆量决定，句意不通。", "肯": "语义：“肯”表示愿意，饿与否不取决于意愿，句意不通。", "须": "语法：“须”后需接动词，不能直接接“很饿”；且“须”属书面语，与口语句不协调。"}, "sentence_index": 6, "correct_answer": "会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他毕业后做了会计。", "explanation": "这里的“会”属于复合词“会计”的一部分，并非独立使用的推测义“会”，与本义项不同。"}, {"text": "这个会唱了三首歌。", "explanation": "这里的“会”是名词“会议”，会议不能“唱歌”，与表示推测的动词义不同。"}, {"text": "我在车站会过一只狗。", "explanation": "这里的“会”是“见面”之义，只用于人，不能用于动物，与表示推测的动词义不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0b14b86-4dcf-4ad2-830b-fc3605394ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19877, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天我会不去公司。", "corrected_sentence": "明天我不会去公司。", "error_description": "错误：否定词“不”应放在“会”之前，写作“不会去”；“会不去”的语序是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0b14b86-4dcf-4ad2-830b-fc3605394ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19877, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天他没会来参加会议。", "corrected_sentence": "今天他不会来参加会议。", "error_description": "错误：表示对将来的推测否定应用“不会”，不能用“没会”，“没”只用于已发生的事。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0b14b86-4dcf-4ad2-830b-fc3605394ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
