INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19878, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，用在动词、形容词前表示否定。", "primary_collocate": null, "pronunciation": "bù", "ipa": "pu˥˩", "syllable_count": 1, "sentences": [{"text": "我不喝咖啡，只喝茶。", "target_word": "不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天很冷，他不出门。", "target_word": "不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个菜不咸，也不酸。", "target_word": "不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不知道他的名字。", "target_word": "不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟不吃肉，只吃菜。", "target_word": "不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她不高，但是跑得很快。", "target_word": "不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不想回家，想再玩一会儿。", "target_word": "不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不来，我们先开始吧。", "target_word": "不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书不便宜，也不新。", "target_word": "不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她不懂中文，我们只好写字。", "target_word": "不", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不是", "label": "复合"}, {"form": "不会", "label": "复合"}], "register": "通用", "sense_fingerprint": "不：副词，放在动词或形容词前表示否定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff2dc4db-9995-4fb8-b9e3-e98d425bf1f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19878, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不", "is_correct": true, "explanation": "正确。“不”（bù，第四声）是否定副词，表示否定。"}, {"text": "度", "is_correct": false, "explanation": "度（dù，第四声）与 bù 声母不同（d 与 b），意思是程度。"}, {"text": "路", "is_correct": false, "explanation": "路（lù，第四声）与 bù 声母不同（l 与 b），意思是道路。"}, {"text": "护", "is_correct": false, "explanation": "护（hù，第四声）与 bù 声母不同（h 与 b），意思是保护。"}, {"text": "故", "is_correct": false, "explanation": "故（gù，第四声）与 bù 声母不同（g 与 b），意思是缘故、旧的。"}], "explanations": {"不": "正确。“不”（bù，第四声）是否定副词，表示否定。", "度": "度（dù，第四声）与 bù 声母不同（d 与 b），意思是程度。", "路": "路（lù，第四声）与 bù 声母不同（l 与 b），意思是道路。", "护": "护（hù，第四声）与 bù 声母不同（h 与 b），意思是保护。", "故": "故（gù，第四声）与 bù 声母不同（g 与 b），意思是缘故、旧的。"}, "sentence_index": null, "correct_answer": "不"}, "level_3": {"options": [{"text": "不", "is_correct": true, "explanation": "正确。“我不喝咖啡”表示否定，与后句“只喝茶”形成对比。"}, {"text": "也", "is_correct": false, "explanation": "语义：“也”表示同样，与“只喝茶”的排他语义矛盾。"}, {"text": "都", "is_correct": false, "explanation": "语义：“都”表示全部，与“只喝茶”的排他语义矛盾。"}, {"text": "又", "is_correct": false, "explanation": "搭配：“又”表示重复，前文没有喝咖啡的情况，此处不合适。"}], "explanations": {"不": "正确。“我不喝咖啡”表示否定，与后句“只喝茶”形成对比。", "也": "语义：“也”表示同样，与“只喝茶”的排他语义矛盾。", "都": "语义：“都”表示全部，与“只喝茶”的排他语义矛盾。", "又": "搭配：“又”表示重复，前文没有喝咖啡的情况，此处不合适。"}, "sentence_index": 0, "correct_answer": "不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天不去，因为我生病了。", "explanation": "这里应该用〈没〉。〈不〉多表示意愿或习惯，过去没有去的具体事情要用〈没〉，应说“我昨天没去，因为我生病了”。"}, {"text": "我不考好，所以很难过。", "explanation": "这里应该用〈没〉。已经发生的结果是没考好，要用〈没〉；〈不〉多表示不愿意，不能说“不考好”。"}, {"text": "我不做完作业，所以不能出去玩。", "explanation": "这里应该用〈没〉。作业是否完成是已经发生的事实，要用〈没〉，应说“没做完作业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19878, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不", "is_correct": true, "explanation": "正确。“不”（bù）是否定副词，表示否定。"}, {"text": "木", "is_correct": false, "explanation": "木（mù，第四声）与 bù 声母不同（m 与 b），意思是树木。"}, {"text": "怒", "is_correct": false, "explanation": "怒（nù，第四声）与 bù 声母不同（n 与 b），意思是愤怒。"}, {"text": "补", "is_correct": false, "explanation": "补（bǔ，第三声）与 bù 声调不同，意思是补充。"}, {"text": "幕", "is_correct": false, "explanation": "幕（mù，第四声）与 bù 声母不同（m 与 b），意思是幕布。"}], "explanations": {"不": "正确。“不”（bù）是否定副词，表示否定。", "木": "木（mù，第四声）与 bù 声母不同（m 与 b），意思是树木。", "怒": "怒（nù，第四声）与 bù 声母不同（n 与 b），意思是愤怒。", "补": "补（bǔ，第三声）与 bù 声调不同，意思是补充。", "幕": "幕（mù，第四声）与 bù 声母不同（m 与 b），意思是幕布。"}, "sentence_index": null, "correct_answer": "不"}, "level_3": {"options": [{"text": "不", "is_correct": true, "explanation": "正确。“我不想回家”表示否定，与后句“想再玩一会儿”相符。"}, {"text": "就", "is_correct": false, "explanation": "语义：“就”表示只想，与后句“想再玩一会儿”矛盾。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示仅仅，与后句“想再玩一会儿”矛盾。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”多与已发生的动作或变化搭配，与心理动词“想”不合。"}], "explanations": {"不": "正确。“我不想回家”表示否定，与后句“想再玩一会儿”相符。", "就": "语义：“就”表示只想，与后句“想再玩一会儿”矛盾。", "只": "语义：“只”表示仅仅，与后句“想再玩一会儿”矛盾。", "已经": "搭配：“已经”多与已发生的动作或变化搭配，与心理动词“想”不合。"}, "sentence_index": 6, "correct_answer": "不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请不在教室里大声说话。", "explanation": "这里应该用〈别〉或〈不要〉。劝阻、禁止要用〈别〉，〈不〉只陈述否定，“请不在教室里”不通。"}, {"text": "我昨天不看见他，所以没有打招呼。", "explanation": "这里应该用〈没〉。“看见”是不受意志控制的感知，过去没有发生的事实要用〈没〉，应说“我昨天没看见他”。"}, {"text": "他不朋友很多，所以很少出去玩。", "explanation": "这里的〈不〉放错了位置。〈不〉应放在谓词前，应说“他朋友不多，所以很少出去玩”，不能插在主语“他”与“朋友”之间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不去过北京，这是第一次去。", "corrected_sentence": "我没去过北京，这是第一次去。", "error_description": "否定词错误：说明没有过某种经历，要用“没”，应为“没去过北京”，不能说“不去过北京”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家不有电视，我们常去朋友家看。", "corrected_sentence": "我家没有电视，我们常去朋友家看。", "error_description": "否定词错误：表示领有的否定要用“没有”，应为“没有电视”，不能说“不有电视”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19879, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保持", "is_correct": true, "explanation": "反义：“保持”指维持原样，与“改”（换成另一种）相反。"}, {"text": "睡", "is_correct": false, "explanation": "无反义关系：“睡”指睡觉，与“改”的意思无关。"}, {"text": "喝", "is_correct": false, "explanation": "无反义关系：“喝”指饮用，与“改”的意思无关。"}, {"text": "写", "is_correct": false, "explanation": "无反义关系：“写”指书写，与“改”的意思无关。"}], "correct_answer": "保持", "explanations": {"保持": "反义：“保持”指维持原样，与“改”（换成另一种）相反。", "睡": "无反义关系：“睡”指睡觉，与“改”的意思无关。", "喝": "无反义关系：“喝”指饮用，与“改”的意思无关。", "写": "无反义关系：“写”指书写，与“改”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19879, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保持", "is_correct": true, "explanation": "反义：“保持”指维持原样，与“改”（换成另一种）相反。"}, {"text": "读", "is_correct": false, "explanation": "无反义关系：“读”指看着文字发声或理解，与“改”的意思无关。"}, {"text": "走", "is_correct": false, "explanation": "无反义关系：“走”指移动，与“改”的意思无关。"}, {"text": "看", "is_correct": false, "explanation": "无反义关系：“看”指用眼睛观察，与“改”的意思无关。"}], "correct_answer": "保持", "explanations": {"保持": "反义：“保持”指维持原样，与“改”（换成另一种）相反。", "读": "无反义关系：“读”指看着文字发声或理解，与“改”的意思无关。", "走": "无反义关系：“走”指移动，与“改”的意思无关。", "看": "无反义关系：“看”指用眼睛观察，与“改”的意思无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19879, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改变，使事物发生变化。", "primary_collocate": null, "pronunciation": "gǎi", "ipa": "kai˨˩˦", "syllable_count": 1, "sentences": [{"text": "也要听用户的建议，改得更好。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "他把头发改成了短发。", "target_word": "改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想改一下旅行的时间。", "target_word": "改", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天下雨，我们改去看电影吧。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今年改做生意了。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生让他改吃清淡的饭菜。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把会议改到下午三点了。", "target_word": "改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她家的房子改成了一家小书店。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司改了上班的时间，早上九点开始。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路太堵，我们改走小路吧。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "改了", "label": "体标"}, {"form": "改过", "label": "体标"}, {"form": "改改", "label": "重叠"}, {"form": "改变", "label": "复合"}, {"form": "改进", "label": "复合"}], "register": "中性", "sense_fingerprint": "把原来的样子、时间、做法换成另一种（改成、改到、改做）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b2747cf-51da-4bed-8a3e-6845ab573b37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19879, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "改", "is_correct": true, "explanation": "正确：改（gǎi），意思是改变、更改，即把原来的样子换成别的。"}, {"text": "海", "is_correct": false, "explanation": "hǎi（第三声）与 gǎi 声母不同（h 与 g），意思是大海。"}, {"text": "买", "is_correct": false, "explanation": "mǎi（第三声）与 gǎi 声母不同（m 与 g），意思是购买。"}, {"text": "感", "is_correct": false, "explanation": "gǎn（第三声）与 gǎi 韵母不同（an 与 ai），意思是感觉。"}, {"text": "搞", "is_correct": false, "explanation": "gǎo（第三声）与 gǎi 韵母不同（ao 与 ai），意思是做、干。"}, {"text": "该", "is_correct": false, "explanation": "gāi（第一声）与 gǎi 声调不同，意思是应当、该当。"}], "explanations": {"改": "正确：改（gǎi），意思是改变、更改，即把原来的样子换成别的。", "海": "hǎi（第三声）与 gǎi 声母不同（h 与 g），意思是大海。", "买": "mǎi（第三声）与 gǎi 声母不同（m 与 g），意思是购买。", "感": "gǎn（第三声）与 gǎi 韵母不同（an 与 ai），意思是感觉。", "搞": "gǎo（第三声）与 gǎi 韵母不同（ao 与 ai），意思是做、干。", "该": "gāi（第一声）与 gǎi 声调不同，意思是应当、该当。"}, "sentence_index": null, "correct_answer": "改"}, "level_3": {"options": [{"text": "改", "is_correct": true, "explanation": "正确：“改得更好”指改进得更好，符合“听用户的建议”的语境。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”指流泪出声，与改进做法无关，“哭得更好”在此语境中说不通。"}, {"text": "吵", "is_correct": false, "explanation": "语义：“吵”指争吵、声音嘈杂，与改进做法无关，“吵得更好”说不通。"}, {"text": "咳", "is_correct": false, "explanation": "语义：“咳”指咳嗽，与改进做法无关，“咳得更好”说不通。"}], "explanations": {"改": "正确：“改得更好”指改进得更好，符合“听用户的建议”的语境。", "哭": "语义：“哭”指流泪出声，与改进做法无关，“哭得更好”在此语境中说不通。", "吵": "语义：“吵”指争吵、声音嘈杂，与改进做法无关，“吵得更好”说不通。", "咳": "语义：“咳”指咳嗽，与改进做法无关，“咳得更好”说不通。"}, "sentence_index": 0, "correct_answer": "改"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵树改得很高了。", "explanation": "这里应该用〈长〉。树自己生长变高是自然变化，不是有人有意把它换成另一种样子；“改”要求有人主动改变事物。"}, {"text": "他的儿子改成了大人。", "explanation": "这里应该用〈长成〉。孩子自然长大要说“长成”，“改”指人有意地把事物换成另一种样子，不能用来说人长大。"}, {"text": "他的体重改了三公斤。", "explanation": "这里应该用〈增加〉。体重增减是数量变化，不说“改了三公斤”；“改”指有意地把事物换成另一种样子或做法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19879, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "改", "is_correct": true, "explanation": "正确：改（gǎi），意思是改变、更改，即把原来的样子换成别的。"}, {"text": "百", "is_correct": false, "explanation": "bǎi（第三声）与 gǎi 声母不同（b 与 g），意思是一百。"}, {"text": "奶", "is_correct": false, "explanation": "nǎi（第三声）与 gǎi 声母不同（n 与 g），意思是牛奶。"}, {"text": "盖", "is_correct": false, "explanation": "gài（第四声）与 gǎi 声调不同，意思是覆盖、盖住。"}, {"text": "凯", "is_correct": false, "explanation": "kǎi（第三声）与 gǎi 声母不同（k 与 g），意思是凯旋、胜利。"}], "explanations": {"改": "正确：改（gǎi），意思是改变、更改，即把原来的样子换成别的。", "百": "bǎi（第三声）与 gǎi 声母不同（b 与 g），意思是一百。", "奶": "nǎi（第三声）与 gǎi 声母不同（n 与 g），意思是牛奶。", "盖": "gài（第四声）与 gǎi 声调不同，意思是覆盖、盖住。", "凯": "kǎi（第三声）与 gǎi 声母不同（k 与 g），意思是凯旋、胜利。"}, "sentence_index": null, "correct_answer": "改"}, "level_3": {"options": [{"text": "改", "is_correct": true, "explanation": "正确：“改到下午三点”指把会议的时间改成下午三点，符合语境。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”指递送物品，“送到下午三点”不能用于会议时间。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，“把会议吃到下午三点”说不通。"}, {"text": "坐", "is_correct": false, "explanation": "配价：“坐”是不及物动词，不能带“会议”作受事，不能说“把会议坐到”。"}], "explanations": {"改": "正确：“改到下午三点”指把会议的时间改成下午三点，符合语境。", "送": "语义：“送”指递送物品，“送到下午三点”不能用于会议时间。", "吃": "语义：“吃”指进食，“把会议吃到下午三点”说不通。", "坐": "配价：“坐”是不及物动词，不能带“会议”作受事，不能说“把会议坐到”。"}, "sentence_index": 6, "correct_answer": "改"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气改得很冷了。", "explanation": "这里应该用〈变〉。天气自然转冷不需要人去改，要用“变”；“改”指人有意地改变事物。"}, {"text": "他改了一台新电脑。", "explanation": "这里应该用〈换〉。买了新的换掉旧的是替换，“改”指对原有事物做局部变动，不能说“改了一台新电脑”。"}, {"text": "工人改了一个大坑。", "explanation": "这里应该用〈挖〉。挖坑是造出空洞的动作，“改”指对原有事物做变动，不能用来说挖出一个坑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19879, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把窗帘改了蓝色。", "corrected_sentence": "他把窗帘改成了蓝色。", "error_description": "错误形式：“改了蓝色”；正确形式：“改成了蓝色”。“改”后要用“成”引出变成的结果，不能直接接结果词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19879, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天我们把会议改到了下午三点。", "corrected_sentence": "明天我们把会议改到下午三点。", "error_description": "“了”用错：“明天”表示将来，动作尚未发生，“改到”后不能加“了”，应说“明天我们把会议改到下午三点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
