INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师让不我们在教室里吃东西。", "corrected_sentence": "老师不让我们在教室里吃东西。", "error_description": "语序错误：否定词“不”应放在“让”前面，应为“不让我们”，不能说“让不我们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
