INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19881, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，用在形容词或某些动词前，表示程度相当高。", "primary_collocate": null, "pronunciation": "hěn", "ipa": "xən²¹⁴", "syllable_count": 1, "sentences": [{"text": "我很喜欢这个城市。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很想家，每天给妈妈打电话。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明很爱看书。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹很怕黑。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师很关心我们的学习。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很需要你的帮助。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很会唱歌。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都很尊敬这位老医生。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子很有礼貌。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很同意你的看法。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "程度副词，也可用在心理、能愿类动词前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cff4beb-2454-4408-ae79-6e87aa30b10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19881, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "很", "is_correct": true, "explanation": "正确答案：hěn（第三声），意思是“很”。"}, {"text": "恨", "is_correct": false, "explanation": "hěn（第三声）与 hèn（第四声）声调不同，意思是“恨”。"}, {"text": "痕", "is_correct": false, "explanation": "hěn（第三声）与 hén（第二声）声调不同，意思是“痕迹”。"}, {"text": "肯", "is_correct": false, "explanation": "h 与 k 声母不同，声调相同（第三声），意思是“肯”。"}, {"text": "怎", "is_correct": false, "explanation": "zěn（第三声）与 hěn 声母不同（z / h），声调相同，意思是怎样、为什么。"}], "explanations": {"很": "正确答案：hěn（第三声），意思是“很”。", "恨": "hěn（第三声）与 hèn（第四声）声调不同，意思是“恨”。", "痕": "hěn（第三声）与 hén（第二声）声调不同，意思是“痕迹”。", "肯": "h 与 k 声母不同，声调相同（第三声），意思是“肯”。", "怎": "zěn（第三声）与 hěn 声母不同（z / h），声调相同，意思是怎样、为什么。"}, "sentence_index": null, "correct_answer": "很"}, "level_3": {"options": [{"text": "很", "is_correct": true, "explanation": "“很”修饰心理动词“喜欢”，表示感情程度高，符合句意。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行，“喜欢”是持续的心理状态，不能用进行体。"}, {"text": "差点", "is_correct": false, "explanation": "语义：“差点”表示几乎发生，“差点喜欢”意为快要喜欢上，与句中已表达的喜爱不符。"}, {"text": "将", "is_correct": false, "explanation": "语义：“将”表示将来，“将喜欢”把句意改成以后才有的喜爱，与句中表达的当前喜爱不符。"}], "explanations": {"很": "“很”修饰心理动词“喜欢”，表示感情程度高，符合句意。", "正在": "体貌：“正在”表示动作进行，“喜欢”是持续的心理状态，不能用进行体。", "差点": "语义：“差点”表示几乎发生，“差点喜欢”意为快要喜欢上，与句中已表达的喜爱不符。", "将": "语义：“将”表示将来，“将喜欢”把句意改成以后才有的喜爱，与句中表达的当前喜爱不符。"}, "sentence_index": 0, "correct_answer": "很"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的办法很唯一，就是等他回来。", "explanation": "这里误用了〈很〉。“很”只修饰有程度差别的形容词或心理动词，“唯一”没有程度之分，不能用“很”修饰，应去掉“很”。"}, {"text": "我很一起去了图书馆。", "explanation": "这里误用了〈很〉。“很”不能修饰“一起”这类表示共同的副词，应去掉“很”，直接说“一起去了图书馆”。"}, {"text": "我很永远记得你的帮助。", "explanation": "这里误用了〈很〉。“永远”表示时间上没有终点，不分程度，不能用“很”修饰，应去掉“很”，直接说“永远记得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19881, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "很", "is_correct": true, "explanation": "正确答案：hěn（第三声），意思是“很”。"}, {"text": "本", "is_correct": false, "explanation": "běn（第三声）与 hěn 声母不同（b / h），声调相同，意思是书本。"}, {"text": "粉", "is_correct": false, "explanation": "fěn（第三声）与 hěn 声母不同（f / h），声调相同，意思是粉末。"}, {"text": "审", "is_correct": false, "explanation": "shěn（第三声）与 hěn 声母不同（sh / h），声调相同，意思是审查。"}, {"text": "稳", "is_correct": false, "explanation": "wěn（第三声）与 hěn 声母不同（w / h），声调相同，意思是稳定。"}], "explanations": {"很": "正确答案：hěn（第三声），意思是“很”。", "本": "běn（第三声）与 hěn 声母不同（b / h），声调相同，意思是书本。", "粉": "fěn（第三声）与 hěn 声母不同（f / h），声调相同，意思是粉末。", "审": "shěn（第三声）与 hěn 声母不同（sh / h），声调相同，意思是审查。", "稳": "wěn（第三声）与 hěn 声母不同（w / h），声调相同，意思是稳定。"}, "sentence_index": null, "correct_answer": "很"}, "level_3": {"options": [{"text": "很", "is_correct": true, "explanation": "“很”修饰能愿动词“会”，表示程度高，符合句意。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”多与否定词连用，直接修饰肯定的“会”不自然。"}, {"text": "甚是", "is_correct": false, "explanation": "语域：“甚是”是书面语，用在日常口语的能力描述里显得生硬。"}, {"text": "难道", "is_correct": false, "explanation": "语义：“难道”表示反问，句中没有疑问语气，“她难道会唱歌”不成立。"}], "explanations": {"很": "“很”修饰能愿动词“会”，表示程度高，符合句意。", "根本": "搭配：“根本”多与否定词连用，直接修饰肯定的“会”不自然。", "甚是": "语域：“甚是”是书面语，用在日常口语的能力描述里显得生硬。", "难道": "语义：“难道”表示反问，句中没有疑问语气，“她难道会唱歌”不成立。"}, "sentence_index": 6, "correct_answer": "很"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她很结婚了，孩子已经三岁。", "explanation": "这里误用了〈很〉。“很”不能修饰“结婚”这类动作性动词，应去掉“很”，直接说“结婚了”。"}, {"text": "我们很同时出发了。", "explanation": "这里误用了〈很〉。“同时”表示时间一致，没有程度差别，不能用“很”修饰，应去掉“很”，直接说“同时出发”。"}, {"text": "我很第一个到了教室。", "explanation": "这里误用了〈很〉。“很”表示程度高，不能修饰“第一个”这类表示次序的词，应去掉“很”，直接说“第一个到了教室”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19881, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他会很踢足球。", "corrected_sentence": "他很会踢足球。", "error_description": "应为“很会”：“很”要放在能愿动词“会”前面，“会很踢足球”语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
