INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19882, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "虚伪", "is_correct": true, "explanation": "反义：“虚伪”指表里不一、不真实，与“诚实”（言行与内心一致）相反。"}, {"text": "勇敢", "is_correct": false, "explanation": "无反义关系：“勇敢”形容胆量大，与“诚实”的意思无关。"}, {"text": "聪明", "is_correct": false, "explanation": "无反义关系：“聪明”形容智力高，与“诚实”的意思无关。"}, {"text": "热情", "is_correct": false, "explanation": "无反义关系：“热情”形容待人友好、积极，与“诚实”的意思无关。"}], "correct_answer": "虚伪", "explanations": {"虚伪": "反义：“虚伪”指表里不一、不真实，与“诚实”（言行与内心一致）相反。", "勇敢": "无反义关系：“勇敢”形容胆量大，与“诚实”的意思无关。", "聪明": "无反义关系：“聪明”形容智力高，与“诚实”的意思无关。", "热情": "无反义关系：“热情”形容待人友好、积极，与“诚实”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
