INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19882, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指言行与内心一致，不虚假。", "primary_collocate": null, "pronunciation": "chéng shí", "ipa": "tʂʰɤŋ˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "说清楚，才能让别人觉得你很诚实。", "target_word": "诚实", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "他是个很诚实的孩子。", "target_word": "诚实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "做人要诚实，不能骗别人。", "target_word": "诚实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她很诚实，错了就说错了。", "target_word": "诚实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "诚实的人，说话和做事一样。", "target_word": "诚实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板喜欢诚实的员工。", "target_word": "诚实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他对朋友一向很诚实，从不装样子。", "target_word": "诚实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要诚实地告诉医生哪里不舒服。", "target_word": "诚实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虽然说出来很难，但他还是诚实地回答了。", "target_word": "诚实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来很诚实，没有人怀疑他。", "target_word": "诚实", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "誠實", "label": "繁体"}], "register": "中性", "sense_fingerprint": "说的、做的和心里想的一致，不虚假、不装样子（很诚实、诚实地回答）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b2747cf-51da-4bed-8a3e-6845ab573b37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19882, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诚实", "is_correct": true, "explanation": "正确：“你很诚实”与“说清楚”的语境一致，表示言行一致、不虚假。"}, {"text": "粗心", "is_correct": false, "explanation": "语义：“粗心”指做事马虎，与“说清楚”的意思相悖，别人不会因此觉得你可靠。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”多形容场面，不说人“很热闹”。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”说外表，与“说清楚”无关，不能让别人觉得你诚实。"}], "explanations": {"诚实": "正确：“你很诚实”与“说清楚”的语境一致，表示言行一致、不虚假。", "粗心": "语义：“粗心”指做事马虎，与“说清楚”的意思相悖，别人不会因此觉得你可靠。", "热闹": "搭配：“热闹”多形容场面，不说人“很热闹”。", "漂亮": "体貌：“漂亮”说外表，与“说清楚”无关，不能让别人觉得你诚实。"}, "sentence_index": 0, "correct_answer": "诚实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她诚实地喝了一杯茶。", "explanation": "这里应该用〈慢慢〉。“诚实”描述言行是否与内心一致，不修饰喝茶这类动作。"}, {"text": "这张桌子很诚实。", "explanation": "这里应该用〈结实〉。桌子牢固要说“结实”，“诚实”只用于描述人的言行真实、不说假话。"}, {"text": "这条路很诚实。", "explanation": "这里应该用〈平坦〉。“平坦”形容路面平整，“诚实”只用于描述人的言行真实、不说假话，不能用来形容路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19882, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诚实", "is_correct": true, "explanation": "正确：“一向很诚实，从不装样子”，与语境一致。"}, {"text": "做作", "is_correct": false, "explanation": "语义：“做作”指故意装样子，与“从不装样子”相悖。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”多形容身高或位置，不能修饰对待朋友的态度。"}, {"text": "健康", "is_correct": false, "explanation": "搭配：“健康”形容身体或状况，不说“对朋友很健康”。"}], "explanations": {"诚实": "正确：“一向很诚实，从不装样子”，与语境一致。", "做作": "语义：“做作”指故意装样子，与“从不装样子”相悖。", "高": "搭配：“高”多形容身高或位置，不能修饰对待朋友的态度。", "健康": "搭配：“健康”形容身体或状况，不说“对朋友很健康”。"}, "sentence_index": 6, "correct_answer": "诚实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他诚实地站起身来。", "explanation": "这里应该用〈缓缓〉。“诚实”说明言行是否与内心一致，不用来形容站起身这种动作。"}, {"text": "他的声音很诚实。", "explanation": "这里应该用〈洪亮〉。“洪亮”形容声音大而清晰，“诚实”只用于描述人的言行真实、不说假话，不能用来形容声音。"}, {"text": "我们诚实地在公园散步。", "explanation": "这里应该用〈悠闲〉。“诚实”修饰的是言行态度，不适合用来形容散步这种动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说话很的诚实，从不夸大事实。", "corrected_sentence": "他说话很诚实，从不夸大事实。", "error_description": "“的”用错：“很”后面直接接形容词作谓语，不能加“的”，应说“很诚实”，不能说“很的诚实”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他诚实的承认了错误。", "corrected_sentence": "他诚实地承认了错误。", "error_description": "错误形式：“诚实的承认”；正确形式：“诚实地承认”。修饰动词“承认”的状语要用“地”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
