INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19884, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "共同参与某项事务或活动的个人或组织。", "primary_collocate": null, "pronunciation": "hé zuò huǒ bàn", "ipa": "xɤ˧˥ tswo˥˩ xwo˧˩ pan˥˩", "syllable_count": 4, "sentences": [{"text": "比如，系统需要说明哪些数据用来改进产品，哪些可能分享给合作伙伴。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这家公司是我们多年的合作伙伴。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们正在寻找新的合作伙伴。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和合作伙伴一起开了一家小店。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的合作伙伴会互相帮助，共同发展。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校和银行成了合作伙伴。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "签合同以前，要先了解合作伙伴的情况。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目的合作伙伴来自三个国家。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很信任自己的合作伙伴。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司选择合作伙伴时，最看重诚信。", "target_word": "合作伙伴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "共同参与事务或活动的个人或组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edbb42d2-d5e9-4e3a-bea1-4e5446f06e3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19884, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：「分享给」的对象应是人或组织，「冰箱」不能接收数据。"}, {"text": "合作伙伴", "is_correct": true, "explanation": "正确。「分享给合作伙伴」指把数据提供给共同参与业务的个人或组织。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不是可以分享数据的对象，与「分享给」的语境不符。"}, {"text": "垃圾", "is_correct": false, "explanation": "语域：「垃圾」是贬义口语词，不适合出现在正式的数据说明中。"}], "explanations": {"冰箱": "语义：「分享给」的对象应是人或组织，「冰箱」不能接收数据。", "合作伙伴": "正确。「分享给合作伙伴」指把数据提供给共同参与业务的个人或组织。", "天气": "语义：「天气」不是可以分享数据的对象，与「分享给」的语境不符。", "垃圾": "语域：「垃圾」是贬义口语词，不适合出现在正式的数据说明中。"}, "sentence_index": 0, "correct_answer": "合作伙伴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都给合作伙伴浇水。", "explanation": "这里应该用〈植物〉。合作伙伴指一起做事的人或组织，不能像植物一样用“浇水”。"}, {"text": "这家店的合作伙伴很好吃。", "explanation": "这里应该用〈饭菜〉。合作伙伴指一起做事的人或组织，不能用“好吃”来形容。"}, {"text": "他把合作伙伴擦亮了。", "explanation": "这里应该用〈皮鞋〉。合作伙伴指人或组织，不能用“擦亮”来表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "猫", "is_correct": false, "explanation": "语义：「猫」不是签约的对象，与「签合同以前」要了解对方情况的语境不符。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：「身材」是外形特征，不属于签约前需要了解的对方情况。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：「厨房」不是可以签约的一方，与签合同的语境不符。"}, {"text": "合作伙伴", "is_correct": true, "explanation": "正确。「了解合作伙伴的情况」指签约前核实对方的经营、信誉等情况。"}], "explanations": {"猫": "语义：「猫」不是签约的对象，与「签合同以前」要了解对方情况的语境不符。", "身材": "体貌：「身材」是外形特征，不属于签约前需要了解的对方情况。", "厨房": "语义：「厨房」不是可以签约的一方，与签合同的语境不符。", "合作伙伴": "正确。「了解合作伙伴的情况」指签约前核实对方的经营、信誉等情况。"}, "sentence_index": 6, "correct_answer": "合作伙伴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直很孝顺合作伙伴。", "explanation": "这里应该用〈父母〉。合作伙伴指共同做事的人或组织，不能用来指长辈。"}, {"text": "他一口气喝完了合作伙伴。", "explanation": "这里应该用〈饮料〉。合作伙伴指共同做事的人或组织，不能用“喝完”来表示。"}, {"text": "这个合作伙伴的颜色很鲜艳。", "explanation": "这里应该用〈颜料〉。合作伙伴指一起做事的人或组织，不能用“颜色鲜艳”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们找到了一条新的合作伙伴。", "corrected_sentence": "我们找到了一位新的合作伙伴。", "error_description": "量词错误：「合作伙伴」指人或组织，应搭配「位」或「个」；「条」用于消息、河流等，不能用于「合作伙伴」，正确说法是「一位新的合作伙伴」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们找到了两合作伙伴。", "corrected_sentence": "他们找到了两个合作伙伴。", "error_description": "量词错误：数词「两」与「合作伙伴」之间须加量词「个」（或「位」），写作「两个合作伙伴」；「两合作伙伴」不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
