INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19885, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "对事物有清楚的认识或理解。", "primary_collocate": null, "pronunciation": "míng bai", "ipa": "miŋ˧˥ pai", "syllable_count": 2, "sentences": [{"text": "如果用户不明白说明内容，他们就无法做出正确选择。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "听完老师的解释，我才明白这个道理。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不明白为什么大家都笑了。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题很难，我还没有完全明白。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你明白我的意思吗？", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我明白了，原来是这样。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大以后，才会明白父母的辛苦。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说得很清楚，病人也都明白了。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她明白只有努力才能成功。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他明白自己错了，马上说了对不起。", "target_word": "明白", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "明白了", "label": "体标"}], "register": "中性", "sense_fingerprint": "对事物、道理有清楚的认识或理解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edbb42d2-d5e9-4e3a-bea1-4e5446f06e3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19885, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "明摆", "is_correct": false, "explanation": "明摆 míngbǎi 与 míngbai 声母、韵母相同，仅声调不同，意思是明显、一目了然，不是“理解”。"}, {"text": "明白", "is_correct": true, "explanation": "正确答案：明白 míngbai，表示对事物有清楚的认识或理解。"}, {"text": "清白", "is_correct": false, "explanation": "清白 qīngbai 与 míngbai 第一个音节的声母不同（q 与 m），声调也不同，意思是清白、无可指责。"}, {"text": "名牌", "is_correct": false, "explanation": "名牌 míngpái 与 míngbai 第二个音节的声母不同（p 与 b），声调也不同，意思是名牌商品。"}], "explanations": {"明摆": "明摆 míngbǎi 与 míngbai 声母、韵母相同，仅声调不同，意思是明显、一目了然，不是“理解”。", "明白": "正确答案：明白 míngbai，表示对事物有清楚的认识或理解。", "清白": "清白 qīngbai 与 míngbai 第一个音节的声母不同（q 与 m），声调也不同，意思是清白、无可指责。", "名牌": "名牌 míngpái 与 míngbai 第二个音节的声母不同（p 与 b），声调也不同，意思是名牌商品。"}, "sentence_index": null, "correct_answer": "明白"}, "level_3": {"options": [{"text": "忽视", "is_correct": false, "explanation": "语义：“不忽视说明内容”后接“就无法做出正确选择”，因果不通。"}, {"text": "明白", "is_correct": true, "explanation": "正确答案：“不明白说明内容”表示没有理解说明的内容，符合句意。"}, {"text": "解答", "is_correct": false, "explanation": "搭配：“解答”的对象是问题，不能说“解答说明内容”。"}, {"text": "撕毁", "is_correct": false, "explanation": "语义：“不撕毁说明内容”与后句的因果不通，句意荒谬。"}], "explanations": {"忽视": "语义：“不忽视说明内容”后接“就无法做出正确选择”，因果不通。", "明白": "正确答案：“不明白说明内容”表示没有理解说明的内容，符合句意。", "解答": "搭配：“解答”的对象是问题，不能说“解答说明内容”。", "撕毁": "语义：“不撕毁说明内容”与后句的因果不通，句意荒谬。"}, "sentence_index": 0, "correct_answer": "明白"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我明白他家的地址。", "explanation": "这里应该用〈知道〉。“明白”侧重理解意思或道理，记住地址这类事实要用“知道”。"}, {"text": "我明白他的生日。", "explanation": "这里应该用〈记得〉。“明白”表示理解，记住生日这类日期要用“记得”。"}, {"text": "我明白了这个电话号码。", "explanation": "这里应该用〈记住〉。“明白”不表示记住数字，记住号码要用“记住”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "计算", "is_correct": false, "explanation": "搭配：“计算”的对象是数字或费用，不能说“计算父母的辛苦”。"}, {"text": "明白", "is_correct": true, "explanation": "正确答案：“才会明白父母的辛苦”表示长大后才理解父母的付出，符合句意。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“才会”表示只有长大才会有某种认识，说“才会忘记”与句意相反。"}, {"text": "忍受", "is_correct": false, "explanation": "语义：“忍受”的承受者是自己，孩子不能“忍受”父母的辛苦。"}], "explanations": {"计算": "搭配：“计算”的对象是数字或费用，不能说“计算父母的辛苦”。", "明白": "正确答案：“才会明白父母的辛苦”表示长大后才理解父母的付出，符合句意。", "忘记": "语义：“才会”表示只有长大才会有某种认识，说“才会忘记”与句意相反。", "忍受": "语义：“忍受”的承受者是自己，孩子不能“忍受”父母的辛苦。"}, "sentence_index": 6, "correct_answer": "明白"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我明白了远处的那座山。", "explanation": "这里应该用〈看清〉。“明白”指理解道理或意思，不指用眼睛看清外形。"}, {"text": "妈妈明白了厨房里的香味。", "explanation": "这里应该用〈闻到〉。“明白”不表示用鼻子感知气味。"}, {"text": "他明白了门把手。", "explanation": "这里应该用〈摸到〉。“明白”的对象是事情或道理，不能用于接触具体物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明白了过这个道理。", "corrected_sentence": "我明白了这个道理。", "error_description": "体标错误：“了”与“过”不能同时用于同一动词之后，只能用其一；应为“我明白了这个道理。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他还没明白了这个问题。", "corrected_sentence": "他还没明白这个问题。", "error_description": "错误：“没”否定尚未发生的动作时，动词后不能加“了”。应为“他还没明白这个问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7c39780-8988-4b42-a3b5-6f702742c09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19886, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "形式", "is_correct": true, "explanation": "反义：“内容”与“形式”相对，是《现代汉语词典》所列的一对反义词。"}, {"text": "颜色", "is_correct": false, "explanation": "无关：“颜色”与“内容”没有反义关系。"}, {"text": "速度", "is_correct": false, "explanation": "无关：“速度”与“内容”没有反义关系。"}, {"text": "价格", "is_correct": false, "explanation": "无关：“价格”与“内容”没有反义关系。"}], "correct_answer": "形式", "explanations": {"形式": "反义：“内容”与“形式”相对，是《现代汉语词典》所列的一对反义词。", "颜色": "无关：“颜色”与“内容”没有反义关系。", "速度": "无关：“速度”与“内容”没有反义关系。", "价格": "无关：“价格”与“内容”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19886, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "形式", "is_correct": true, "explanation": "反义：“内容”与“形式”相对，是《现代汉语词典》所列的一对反义词。"}, {"text": "数量", "is_correct": false, "explanation": "无关：“数量”与“内容”没有反义关系。"}, {"text": "地点", "is_correct": false, "explanation": "无关：“地点”与“内容”没有反义关系。"}, {"text": "时间", "is_correct": false, "explanation": "无关：“时间”与“内容”没有反义关系。"}], "correct_answer": "形式", "explanations": {"形式": "反义：“内容”与“形式”相对，是《现代汉语词典》所列的一对反义词。", "数量": "无关：“数量”与“内容”没有反义关系。", "地点": "无关：“地点”与“内容”没有反义关系。", "时间": "无关：“时间”与“内容”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19886, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物内部所含的实质或意义。", "primary_collocate": null, "pronunciation": "nèi róng", "ipa": "neɪ˥˩ ɻʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "如果用户不明白说明内容，他们就无法做出正确选择。", "target_word": "内容", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这样用户能理解为什么看到某些内容。", "target_word": "内容", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "这份报告的内容我还没看完，但大致了解了。", "target_word": "内容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书的内容很有意思。", "target_word": "内容", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师讲的内容我都听懂了。", "target_word": "内容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能说一下这篇文章的主要内容吗？", "target_word": "内容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电影的内容不适合小孩子看。", "target_word": "内容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议的内容已经发给大家了。", "target_word": "内容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把今天学的内容写在本子上。", "target_word": "内容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要随便改变合同的内容。", "target_word": "内容", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "内容：文章、讲话、作品等所包含的实质或意义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8ddd3f-1e11-496c-a1ad-5495bc12503a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19886, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内容", "is_correct": true, "explanation": "正确：「说明内容」指解释所包含的信息，与“不明白……就无法做出正确选择”的语境相符。"}, {"text": "心情", "is_correct": false, "explanation": "语义：「心情」是人的情绪状态，不是需要说明给用户、让其理解后再做选择的信息，此处语境不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：「身高」是人的体貌特征，不是用户需要理解才能做选择的说明对象。"}, {"text": "表情", "is_correct": false, "explanation": "语义：「表情」指人脸上的神情，不是需要说明给用户的信息，「说明表情」此处语境不通。"}], "explanations": {"内容": "正确：「说明内容」指解释所包含的信息，与“不明白……就无法做出正确选择”的语境相符。", "心情": "语义：「心情」是人的情绪状态，不是需要说明给用户、让其理解后再做选择的信息，此处语境不通。", "身高": "体貌：「身高」是人的体貌特征，不是用户需要理解才能做选择的说明对象。", "表情": "语义：「表情」指人脸上的神情，不是需要说明给用户的信息，「说明表情」此处语境不通。"}, "sentence_index": 0, "correct_answer": "内容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的内容很高，值得一读。", "explanation": "这里应该用〈质量〉。说书的好坏用“质量高”，“内容”指所讲的材料和意义，不用“高”来形容。"}, {"text": "这个孩子的内容很可爱。", "explanation": "这里应该用〈外表〉。说人的样子用“外表”，“内容”指事物内部所含的实质或意义，不指人的样子。"}, {"text": "这条裙子的内容很长。", "explanation": "这里应该用〈长度〉。说衣物的长短用“长度”，“内容”指事物内部所含的实质或意义，不指长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内容", "is_correct": true, "explanation": "正确：「电影的内容」指影片所讲的东西，「不适合小孩子看」说的正是内容的适龄性。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「看」的对象应是画面、节目等，「价格」不能被看，「看价格」与此句不搭。"}, {"text": "票房", "is_correct": false, "explanation": "语义：「票房」指售票收入，与是否适合小孩子观看无关，句子意思不通。"}, {"text": "画质", "is_correct": false, "explanation": "语义：「画质」指画面清晰度，不涉及适龄问题，「画质不适合小孩子看」语义不通。"}], "explanations": {"内容": "正确：「电影的内容」指影片所讲的东西，「不适合小孩子看」说的正是内容的适龄性。", "价格": "搭配：「看」的对象应是画面、节目等，「价格」不能被看，「看价格」与此句不搭。", "票房": "语义：「票房」指售票收入，与是否适合小孩子观看无关，句子意思不通。", "画质": "语义：「画质」指画面清晰度，不涉及适龄问题，「画质不适合小孩子看」语义不通。"}, "sentence_index": 6, "correct_answer": "内容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学生的内容很高，老师很满意。", "explanation": "这里应该用〈水平〉。说人的学业或能力程度用“水平高”，“内容”不能用来说人的水平高。"}, {"text": "这个包裹的内容很鲜艳。", "explanation": "这里应该用〈颜色〉。说物体的色彩用“颜色”，“内容”指事物内部所含的实质或意义，不指色彩。"}, {"text": "这道菜的内容很咸。", "explanation": "这里应该用〈味道〉。说菜的咸淡用“味道”，“内容”指事物内部所含的实质或意义，不指咸淡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这内容都很丰富。", "corrected_sentence": "这些内容都很丰富。", "error_description": "错误：“都”要求指多个对象，“这内容”只指一个整体，与“都”不搭。应改为“这些内容”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几只内容我们都要学习。", "corrected_sentence": "这几项内容我们都要学习。", "error_description": "错误：量词“只”不能修饰抽象的“内容”。“内容”常用量词是“项”，应说“这几项内容”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
