INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19890, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "表示情理上必须如此或估计情况必然如此。", "primary_collocate": null, "pronunciation": "yīng gāi", "ipa": "iŋ˥ kaɪ˥", "syllable_count": 2, "sentences": [{"text": "另外，算法如何工作也应该有一定透明度。", "target_word": "应该", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "有些人认为，应该给失业的人提供更多的职业培训。", "target_word": "应该", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "另一些人觉得，应该为人工智能制定更严格的使用规则。", "target_word": "应该", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "你生病了，应该多休息。", "target_word": "应该", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生应该按时完成作业。", "target_word": "应该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "现在已经八点了，他应该到家了。", "target_word": "应该", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天应该会下雨，你带伞吧。", "target_word": "应该", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们应该帮助有困难的人。", "target_word": "应该", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题不难，你应该能做对。", "target_word": "应该", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子做错事，大人应该耐心地说明。", "target_word": "应该", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不应该", "label": "否定式"}], "register": "中性", "sense_fingerprint": "应该：情理上必须如此，或估计情况必然如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8ddd3f-1e11-496c-a1ad-5495bc12503a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "应该", "is_correct": true, "explanation": "正确：「也应该有一定透明度」表示情理上应当如此，与句意相符。"}, {"text": "敢", "is_correct": false, "explanation": "语义：「敢」表示有胆量去做某事，「也敢有一定透明度」不表示应当。"}, {"text": "肯", "is_correct": false, "explanation": "搭配：「肯」需要有意愿的主体，「算法」不能作「肯」的主语，搭配不当。"}, {"text": "被", "is_correct": false, "explanation": "语法：「被」要接动词构成被动，「也被有一定透明度」不成句，不能填入此处。"}], "explanations": {"应该": "正确：「也应该有一定透明度」表示情理上应当如此，与句意相符。", "敢": "语义：「敢」表示有胆量去做某事，「也敢有一定透明度」不表示应当。", "肯": "搭配：「肯」需要有意愿的主体，「算法」不能作「肯」的主语，搭配不当。", "被": "语法：「被」要接动词构成被动，「也被有一定透明度」不成句，不能填入此处。"}, "sentence_index": 0, "correct_answer": "应该"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我应该明天去北京，我还没决定。", "explanation": "这里应该用〈打算〉。说计划做某事用“打算”，“应该”表示情理上必须如此或估计必然，不表示计划；句中“还没决定”也与“应该”的必然义相矛盾。"}, {"text": "我应该明天天气好，我想去公园。", "explanation": "这里应该用〈希望〉。说盼望某事发生用“希望”，“应该”表示情理上必须如此，不表示盼望。"}, {"text": "我应该很想你，我们好久没见了。", "explanation": "这里应该用〈想〉。说思念某人用“想”，“应该”表示情理上必须如此，不表示思念；“应该很想你”也不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应该", "is_correct": true, "explanation": "正确：「明天应该会下雨」表示对将来情况的估计，与「你带伞吧」相符。"}, {"text": "必须", "is_correct": false, "explanation": "语义：「必须」表示必要或义务，不表示对将来情况的估计，「明天必须会下雨」语义不通。"}, {"text": "要", "is_correct": false, "explanation": "搭配：「要」与「会」连用不合语法，「明天要会下雨」不成立。"}, {"text": "得", "is_correct": false, "explanation": "语义：「得」表示必要或需要，不表示推测，「明天得会下雨」不通。"}], "explanations": {"应该": "正确：「明天应该会下雨」表示对将来情况的估计，与「你带伞吧」相符。", "必须": "语义：「必须」表示必要或义务，不表示对将来情况的估计，「明天必须会下雨」语义不通。", "要": "搭配：「要」与「会」连用不合语法，「明天要会下雨」不成立。", "得": "语义：「得」表示必要或需要，不表示推测，「明天得会下雨」不通。"}, "sentence_index": 6, "correct_answer": "应该"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我应该盼望你明天来，我们一起吃饭。", "explanation": "这里应该用〈希望〉。说盼望某事发生用“希望”，“应该”表示情理上必须如此，不表示盼望。"}, {"text": "我应该去北京，我还没定好行程。", "explanation": "这里应该用〈打算〉。说计划做某事用“打算”，“应该”表示情理上必须如此，不表示计划。"}, {"text": "我应该讨厌香菜，我每次都吃很多。", "explanation": "这里应该用〈爱吃〉。说口味偏好用“爱吃”，“应该”表示情理上必须如此，不表示偏好；“应该讨厌”与“每次都吃很多”也相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们没应该浪费粮食。", "corrected_sentence": "我们不应该浪费粮食。", "error_description": "错误：“没应该浪费”。正确：“不应该浪费”。情态动词“应该”的否定只能用“不”，不能用“没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生要应该尊重老师。", "corrected_sentence": "学生应该尊重老师。", "error_description": "错误：“要应该尊重”。正确：“应该尊重”。“应该”与“要”都是情态动词，不能连用，应去掉多余的“要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
