INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指技术方案或产品中具体的、细微的方面或环节。", "primary_collocate": null, "pronunciation": "jì shù xì jié", "ipa": "tɕi˥˩ ʂu˥˩ ɕi˥˩ tɕje˧˥", "syllable_count": 4, "sentences": [{"text": "虽然不需要公开所有技术细节，但要解释基本逻辑。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个项目的技术细节，工程师明天会详细说明。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理只关心结果，不想听太多技术细节。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里写了很多技术细节，我看不懂。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个产品的技术细节非常熟悉。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些技术细节需要工程师再检查一遍。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们先讲想法，再讲技术细节。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不愿意公开新手机的技术细节。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议上大家讨论了方案的技术细节。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章没有介绍技术细节，只说了用途。", "target_word": "技术细节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "技術細節", "label": "繁体"}], "register": "中性", "sense_fingerprint": "技术方案或产品中具体细微的环节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab6374f-e90b-4270-b9f3-bb44f316482a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "技术细节", "is_correct": true, "explanation": "正确：指技术方案中具体的环节，与后文“解释基本逻辑”形成对照。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“公开”的对象多为信息或方案，不说公开颜色。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的外貌特征，与公开技术方案的语境无关。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语闲谈，与“解释基本逻辑”的书面、技术语域冲突。"}], "explanations": {"技术细节": "正确：指技术方案中具体的环节，与后文“解释基本逻辑”形成对照。", "颜色": "搭配：“公开”的对象多为信息或方案，不说公开颜色。", "身高": "体貌：身高是人的外貌特征，与公开技术方案的语境无关。", "八卦": "语域：“八卦”是口语闲谈，与“解释基本逻辑”的书面、技术语域冲突。"}, "sentence_index": 0, "correct_answer": "技术细节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很注意朋友之间的技术细节。", "explanation": "这里应该用〈小事〉。技术细节专指技术方案或产品中的具体环节，朋友之间的普通小事不能这样说。"}, {"text": "这碗汤的技术细节很鲜。", "explanation": "这里应该用〈味道〉。技术细节指技术方案中的具体环节，不能用来描述食物的味道。"}, {"text": "我的技术细节很便宜。", "explanation": "这里应该用〈手机〉。技术细节指技术方案或产品中的具体环节，不能用来说价格便宜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "技术细节", "is_correct": true, "explanation": "正确：指讲解的具体内容，与前句“先讲想法”构成先后层次。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是身体特征，不是可以拿来讲解的内容。"}, {"text": "家务", "is_correct": false, "explanation": "语义：家务与“讲想法”的讲解主题不同，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的外貌特征，不是课堂上可以讲解的内容，句意不通。"}], "explanations": {"技术细节": "正确：指讲解的具体内容，与前句“先讲想法”构成先后层次。", "体重": "体貌：体重是身体特征，不是可以拿来讲解的内容。", "家务": "语义：家务与“讲想法”的讲解主题不同，句意不通。", "身高": "语义：身高是人的外貌特征，不是课堂上可以讲解的内容，句意不通。"}, "sentence_index": 6, "correct_answer": "技术细节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的技术细节很温和。", "explanation": "这里应该用〈性格〉。技术细节指技术方案或产品中的具体环节，不能用来描述人的性格。"}, {"text": "窗外的技术细节叫得很响。", "explanation": "这里应该用〈鸟〉。技术细节指技术方案中的具体环节，不能发出声音，应说“鸟叫得很响”。"}, {"text": "这次旅行是我最难忘的技术细节。", "explanation": "这里应该用〈经验〉。技术细节指技术方案中的具体环节，不能指亲身经历后的收获。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只技术细节很关键。", "corrected_sentence": "这个技术细节很关键。", "error_description": "量词错误：“技术细节”是抽象名词，应用“个”，“只”多用于动物或成对的东西，应说“这个技术细节”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很熟悉这个些技术细节。", "corrected_sentence": "他很熟悉这些技术细节。", "error_description": "数量词搭配错误：“这个”是单数，“些”是复数，二者不能同用，应说“这些技术细节”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
