INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19893, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把好的东西介绍给别人，让别人喜欢或接受。", "primary_collocate": null, "pronunciation": "tuī jiàn", "ipa": "tʰweɪ˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这本书很实用，我想向同事推荐。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友向我推荐了一本好书。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给你推荐一家很好吃的饭馆。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师推荐我们看这部电影。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把这首歌推荐给了所有同学。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理推荐小王参加这次比赛。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站向用户推荐新产品。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能为我推荐一个好用的手机吗？", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事一直向大家推荐这家咖啡店。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去过那家店，所以敢向你推荐。", "target_word": "推荐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推荐了", "label": "体标"}, {"form": "推荐过", "label": "体标"}, {"form": "推荐信", "label": "复合"}, {"form": "推薦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把好的东西介绍给别人让人接受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab6374f-e90b-4270-b9f3-bb44f316482a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19893, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推荐", "is_correct": true, "explanation": "正确：把好书介绍给同事，与“这本书很实用”相符。"}, {"text": "检测", "is_correct": false, "explanation": "语义：检测是查验质量或问题，不能用来向同事介绍一本书，句意不通。"}, {"text": "修复", "is_correct": false, "explanation": "语义：修复针对损坏的东西，与“这本书很实用”无关，句意不通。"}, {"text": "报销", "is_correct": false, "explanation": "语义：报销是报账，不能用来向同事介绍书，句意不通。"}], "explanations": {"推荐": "正确：把好书介绍给同事，与“这本书很实用”相符。", "检测": "语义：检测是查验质量或问题，不能用来向同事介绍一本书，句意不通。", "修复": "语义：修复针对损坏的东西，与“这本书很实用”无关，句意不通。", "报销": "语义：报销是报账，不能用来向同事介绍书，句意不通。"}, "sentence_index": 0, "correct_answer": "推荐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向老师推荐了一次失败。", "explanation": "这里应该用〈汇报〉。推荐表示把好东西介绍给别人，不能用来指告诉别人失败的结果。"}, {"text": "老师向我们推荐这部电影的背景。", "explanation": "这里应该用〈介绍〉。推荐用于把好东西推给别人，讲解背景要用介绍。"}, {"text": "他去办公室推荐加薪。", "explanation": "这里应该用〈申请〉。推荐需要有一个被推给别人的对象，表示自己提出请求要用申请。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19893, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推荐", "is_correct": true, "explanation": "正确：指把新产品介绍给用户，与句意相符。"}, {"text": "报销", "is_correct": false, "explanation": "语义：报销是报账的行为，网站不会向用户报销产品，句意不通。"}, {"text": "吵", "is_correct": false, "explanation": "配价：“吵”不能直接带“新产品”作宾语，搭配不成立。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”的对象应是人或帮助，不能说感谢产品。"}], "explanations": {"推荐": "正确：指把新产品介绍给用户，与句意相符。", "报销": "语义：报销是报账的行为，网站不会向用户报销产品，句意不通。", "吵": "配价：“吵”不能直接带“新产品”作宾语，搭配不成立。", "感谢": "配价：“感谢”的对象应是人或帮助，不能说感谢产品。"}, "sentence_index": 6, "correct_answer": "推荐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板推荐了小王的努力。", "explanation": "这里应该用〈赞扬〉。推荐表示把好东西介绍给别人，不能用来称赞某人的努力。"}, {"text": "他向我推荐了一次哭泣。", "explanation": "这里应该用〈哭〉。推荐表示把好东西介绍给别人，不能用来描述哭泣这种行为。"}, {"text": "妈妈推荐了我的错误。", "explanation": "这里应该用〈原谅〉。错误不是可以推荐的好东西，表示宽恕要说原谅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我向朋友推荐着一部好电影。", "corrected_sentence": "我向朋友推荐了一部好电影。", "error_description": "体标错误：“着”表示持续，推荐电影是一次性完成的动作，应用“了”，说“推荐了一部好电影”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这家餐厅推荐了给朋友。", "corrected_sentence": "我把这家餐厅推荐给了朋友。", "error_description": "补语与“了”的顺序错误：“推荐”后应先接补语“给”，再接“了”，应说“推荐给了朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
