INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19896, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向有关方面提出请求，希望得到批准或帮助。", "primary_collocate": null, "pronunciation": "shēn qǐng", "ipa": "ʂən˥ tɕʰiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "如果你想出国读书，就要先向学校申请。", "target_word": "申请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想申请一份奖学金。", "target_word": "申请", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他向学校申请了一间宿舍。", "target_word": "申请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "申请签证需要带护照和照片。", "target_word": "申请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她申请过三次，都没有成功。", "target_word": "申请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以在网上申请信用卡。", "target_word": "申请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他向公司申请休假一周。", "target_word": "申请", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们已经申请了新的营业执照。", "target_word": "申请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想申请助学贷款的同学，请先填表。", "target_word": "申请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他正在申请去美国留学。", "target_word": "申请", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "申请了", "label": "完成体"}, {"form": "申请过", "label": "经历体"}, {"form": "申请书", "label": "复合"}], "register": "中性", "sense_fingerprint": "向机构或部门正式提出请求，希望获得批准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab6374f-e90b-4270-b9f3-bb44f316482a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19896, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "申请", "is_correct": true, "explanation": "正确：shēn qǐng，向有关方面提出请求，希望得到批准或帮助。"}, {"text": "深情", "is_correct": false, "explanation": "声调不同：深情（shēn qíng）第二音节为阳平，与申请（shēn qǐng）的上声不同，意思是深厚的感情。"}, {"text": "神情", "is_correct": false, "explanation": "两个音节的声调都不同：神情（shén qíng）与申请（shēn qǐng）只差声调，意思是表情或神态。"}, {"text": "深井", "is_correct": false, "explanation": "声母不同：深井（shēn jǐng）第二音节为 j 开头，与申请的 q 不同，意思是很深的井。"}, {"text": "申明", "is_correct": false, "explanation": "声母与声调不同：申明（shēn míng）第二音节为 m 开头、阳平，与申请的 q 开头、上声不同，意思是公开说明。"}], "explanations": {"申请": "正确：shēn qǐng，向有关方面提出请求，希望得到批准或帮助。", "深情": "声调不同：深情（shēn qíng）第二音节为阳平，与申请（shēn qǐng）的上声不同，意思是深厚的感情。", "神情": "两个音节的声调都不同：神情（shén qíng）与申请（shēn qǐng）只差声调，意思是表情或神态。", "深井": "声母不同：深井（shēn jǐng）第二音节为 j 开头，与申请的 q 不同，意思是很深的井。", "申明": "声母与声调不同：申明（shēn míng）第二音节为 m 开头、阳平，与申请的 q 开头、上声不同，意思是公开说明。"}, "sentence_index": null, "correct_answer": "申请"}, "level_3": {"options": [{"text": "申请", "is_correct": true, "explanation": "正确：“先向学校申请”指向有关方面提出请求，符合出国读书需要办理手续的语境。"}, {"text": "太阳", "is_correct": false, "explanation": "语法：“太阳”是名词，不能填入动词的位置，“先向学校太阳”不成立。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：“微笑”不表示提出请求或办理手续，“先向学校微笑”句意不通。"}, {"text": "哥们", "is_correct": false, "explanation": "语法：“哥们”是名词，不能作谓语动词，不能填入这个空位。"}], "explanations": {"申请": "正确：“先向学校申请”指向有关方面提出请求，符合出国读书需要办理手续的语境。", "太阳": "语法：“太阳”是名词，不能填入动词的位置，“先向学校太阳”不成立。", "微笑": "语义：“微笑”不表示提出请求或办理手续，“先向学校微笑”句意不通。", "哥们": "语法：“哥们”是名词，不能作谓语动词，不能填入这个空位。"}, "sentence_index": 0, "correct_answer": "申请"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她向海关申请了随身携带的现金。", "explanation": "这里应该用〈申报〉。申报是如实向有关部门报告自己携带或拥有的物品，不是请求批准，所以不能用“申请”。"}, {"text": "老板申请每个人都准时上班。", "explanation": "这里应该用〈要求〉。“申请”是向有关方面请求批准或帮助，老板对员工提出规定应说“要求”。"}, {"text": "他在超市申请了三瓶牛奶。", "explanation": "这里应该用〈购买〉。“申请”是向有关方面提出请求，不用于买东西，买东西要说“购买”或“买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "申请", "is_correct": true, "explanation": "正确：“向公司申请”表示向有关方面请求批准，与“休假一周”搭配。"}, {"text": "完成", "is_correct": false, "explanation": "语义：“完成”表示做完某件事，不能说完成休假，句意不通。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”一般搭配活动、会议等，不说举办休假。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“休假一周”作宾语。"}], "explanations": {"申请": "正确：“向公司申请”表示向有关方面请求批准，与“休假一周”搭配。", "完成": "语义：“完成”表示做完某件事，不能说完成休假，句意不通。", "举办": "搭配：“举办”一般搭配活动、会议等，不说举办休假。", "散步": "配价：“散步”是不及物动词，不能带“休假一周”作宾语。"}, "sentence_index": 6, "correct_answer": "申请"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向老师申请了感谢。", "explanation": "这里应该用〈感谢〉。“申请”是向有关方面请求批准或帮助，不能用来表达谢意，表示感谢应说“感谢”。"}, {"text": "大家热烈申请他的到来。", "explanation": "这里应该用〈欢迎〉。“申请”不能用来表达对人到来的态度，表示欢迎应说“欢迎”。"}, {"text": "他向老板申请了工作进度。", "explanation": "这里应该用〈报告〉。“申请”是向有关方面请求批准，汇报工作进度应说“报告”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没有向银行申请了贷款。", "corrected_sentence": "我没有向银行申请贷款。", "error_description": "错误：“没有”与“了”同时使用，“申请”后多了“了”。正确：否定已发生的动作只用“没有”，应说“我没有向银行申请贷款”，不说“我没有向银行申请了贷款”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想向学校申请一把补助。", "corrected_sentence": "我想向学校申请一笔补助。", "error_description": "错误：量词“把”用于有柄或可握持的物品，不能修饰“补助”。正确：应说“一笔补助”，“笔”可用于计量款项。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87a84658-af8a-4322-bce7-fcff58dd6586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
