INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物产生的根源或出处。", "primary_collocate": null, "pronunciation": "lái yuán", "ipa": "lai˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "训练数据的来源也很重要。", "target_word": "来源", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "这条新闻的来源是哪里？", "target_word": "来源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要先查清楚消息的来源。", "target_word": "来源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的收入来源只有一份工作。", "target_word": "来源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水的来源是山上的雪。", "target_word": "来源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，这个成语的来源是一个古代故事。", "target_word": "来源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的资金来源不清楚，大家都很担心。", "target_word": "来源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写文章时，你要说明资料的来源。", "target_word": "来源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些水果的来源是南方的农场。", "target_word": "来源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上的信息来源很多，不一定都对。", "target_word": "来源", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "信息来源", "label": "复合"}, {"form": "收入来源", "label": "复合"}, {"form": "來源", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物产生的根源或出处，指信息、资料、资金等从哪里来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '248f5714-59ca-4c41-94f7-b47c7a28fb77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19898, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "来源", "is_correct": true, "explanation": "来源（lái yuán）：事物产生的根源或出处。"}, {"text": "裁员", "is_correct": false, "explanation": "cái 与 lái 声母不同（c/l），声调相同；裁员指减少员工，与“来源”无关。"}, {"text": "开源", "is_correct": false, "explanation": "kāi 与 lái 声母不同（k/l），声调也不同，意思是开拓资源或财源，不是“来源”。"}, {"text": "来院", "is_correct": false, "explanation": "yuàn 与 yuán 声调不同（第四声与第二声）；来院指到医院来，不是事物的出处。"}], "explanations": {"来源": "来源（lái yuán）：事物产生的根源或出处。", "裁员": "cái 与 lái 声母不同（c/l），声调相同；裁员指减少员工，与“来源”无关。", "开源": "kāi 与 lái 声母不同（k/l），声调也不同，意思是开拓资源或财源，不是“来源”。", "来院": "yuàn 与 yuán 声调不同（第四声与第二声）；来院指到医院来，不是事物的出处。"}, "sentence_index": null, "correct_answer": "来源"}, "level_3": {"options": [{"text": "来源", "is_correct": true, "explanation": "正确：“来源”指数据从哪里来，与“训练数据”搭配，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指外观，数据没有颜色，句子不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”只用于人或动物，不能说“训练数据的脾气”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或动物的重量，数据没有体重，句子不通。"}], "explanations": {"来源": "正确：“来源”指数据从哪里来，与“训练数据”搭配，符合句意。", "颜色": "语义：“颜色”指外观，数据没有颜色，句子不通。", "脾气": "搭配：“脾气”只用于人或动物，不能说“训练数据的脾气”。", "体重": "语义：“体重”指人或动物的重量，数据没有体重，句子不通。"}, "sentence_index": 0, "correct_answer": "来源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个陌生人的来源很神秘，没人知道他是谁。", "explanation": "这里应该用〈来历〉。来源指事物从哪里来，说人的身世、经历要用来历。"}, {"text": "她的来源很好，父母都是大学教授。", "explanation": "这里应该用〈出身〉。来源用于事物的出处，说人的家庭背景要用出身。"}, {"text": "这款手机的来源很突出，大家都很喜欢。", "explanation": "这里应该用〈特点〉。来源指事物的出处；说事物显著的特征、优点要用特点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来源", "is_correct": true, "explanation": "正确：“来源”指资金从哪里来，与“资金”搭配，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，资金没有味道，句子不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人或动物，不能说“资金的身高”。"}, {"text": "性别", "is_correct": false, "explanation": "语义：“性别”是人或动物的属性，资金没有性别，句子不通。"}], "explanations": {"来源": "正确：“来源”指资金从哪里来，与“资金”搭配，符合句意。", "味道": "语义：“味道”指气味或滋味，资金没有味道，句子不通。", "身高": "搭配：“身高”只用于人或动物，不能说“资金的身高”。", "性别": "语义：“性别”是人或动物的属性，资金没有性别，句子不通。"}, "sentence_index": 6, "correct_answer": "来源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人的来源是广东，他小时候就在那里长大。", "explanation": "这里应该用〈籍贯〉。来源指事物的出处；说人的祖籍、出生地要用籍贯。"}, {"text": "那个孩子的来源很可怜，父母很早就去世了。", "explanation": "这里应该用〈身世〉。来源指事物从哪里来；说人的遭遇、经历要用身世。"}, {"text": "这件衣服的来源很鲜艳，很多人都喜欢穿。", "explanation": "这里应该用〈颜色〉。来源指事物的出处；说衣服的颜色鲜艳要用颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的收入来源了一份工作。", "corrected_sentence": "他的收入来源于一份工作。", "error_description": "词性错误：“来源”是名词，不能直接带宾语；表示“从…来”应说“来源于”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张来源很可靠，大家都相信它。", "corrected_sentence": "这个来源很可靠，大家都相信它。", "error_description": "量词错误：“来源”前应用“个”，“张”用于纸张、桌子等平面物，不能修饰“来源”。正确形式为“这个来源”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19899, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违法", "is_correct": true, "explanation": "正确。“违法”与“合法”是反义词，指不符合法律规定。"}, {"text": "清楚", "is_correct": false, "explanation": "与“合法”无反义关系：“清楚”指明白、不模糊，与法律无关。"}, {"text": "便宜", "is_correct": false, "explanation": "与“合法”无反义关系：“便宜”说价格低，与法律无关。"}, {"text": "明亮", "is_correct": false, "explanation": "与“合法”无反义关系：“明亮”说光线或颜色，与法律无关。"}], "correct_answer": "违法", "explanations": {"违法": "正确。“违法”与“合法”是反义词，指不符合法律规定。", "清楚": "与“合法”无反义关系：“清楚”指明白、不模糊，与法律无关。", "便宜": "与“合法”无反义关系：“便宜”说价格低，与法律无关。", "明亮": "与“合法”无反义关系：“明亮”说光线或颜色，与法律无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19899, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "非法", "is_correct": true, "explanation": "正确。“非法”与“合法”是反义词，指违反法律规定。"}, {"text": "宽阔", "is_correct": false, "explanation": "与“合法”无反义关系：“宽阔”说空间大，与法律无关。"}, {"text": "温暖", "is_correct": false, "explanation": "与“合法”无反义关系：“温暖”说温度或感受，与法律无关。"}, {"text": "辛苦", "is_correct": false, "explanation": "与“合法”无反义关系：“辛苦”说劳累，与法律无关。"}], "correct_answer": "非法", "explanations": {"非法": "正确。“非法”与“合法”是反义词，指违反法律规定。", "宽阔": "与“合法”无反义关系：“宽阔”说空间大，与法律无关。", "温暖": "与“合法”无反义关系：“温暖”说温度或感受，与法律无关。", "辛苦": "与“合法”无反义关系：“辛苦”说劳累，与法律无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19899, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "符合法律规定或规则要求。", "primary_collocate": null, "pronunciation": "hé fǎ", "ipa": "xɤ˧˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司应确保数据是合法获取的，不包含敏感信息，如健康记录或身份号码。", "target_word": "合法", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家店有合法的营业执照。", "target_word": "合法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在中国，十八岁以后才能合法结婚。", "target_word": "合法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他靠合法的工作赚钱，不怕警察检查。", "target_word": "合法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买房子要签合法的合同，才能保护自己。", "target_word": "合法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网站卖的药不合法，警察已经关了它。", "target_word": "合法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师说，用别人的照片做广告是不合法的。", "target_word": "合法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有合法的出租车，才可以在机场接客人。", "target_word": "合法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱是他合法继承的，不是偷来的。", "target_word": "合法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院认为他的做法合法，没有判他有罪。", "target_word": "合法", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "合法性", "label": "复合"}, {"form": "合法化", "label": "复合"}], "register": "中性", "sense_fingerprint": "合法：符合法律规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33088bf9-1fe7-4ce5-b719-265e37e48a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19899, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合法", "is_correct": true, "explanation": "正确。“数据是合法获取的”符合句中“公司应确保”的要求。"}, {"text": "违法", "is_correct": false, "explanation": "语义：“违法”与“公司应确保”相矛盾，公司不会要求数据违法获取。"}, {"text": "不当", "is_correct": false, "explanation": "语义：“不当”指做法欠妥，与“应确保”的要求相矛盾。"}, {"text": "粗暴", "is_correct": false, "explanation": "搭配：“粗暴”形容人的态度或行为，不用来修饰获取数据的方式。"}], "explanations": {"合法": "正确。“数据是合法获取的”符合句中“公司应确保”的要求。", "违法": "语义：“违法”与“公司应确保”相矛盾，公司不会要求数据违法获取。", "不当": "语义：“不当”指做法欠妥，与“应确保”的要求相矛盾。", "粗暴": "搭配：“粗暴”形容人的态度或行为，不用来修饰获取数据的方式。"}, "sentence_index": 0, "correct_answer": "合法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个价格很合法，顾客都觉得满意。", "explanation": "这里应该用〈合理〉。价格是否公道要用合理，合法只说符合法律规定。"}, {"text": "这批产品的质量很合法，已经可以出厂了。", "explanation": "这里应该用〈合格〉。质量达到标准要用合格，合法只说符合法律规定。"}, {"text": "这件衣服的大小很合法，穿上去正好。", "explanation": "这里应该用〈合适〉。衣服的大小和款式要用合适，合法只说符合法律规定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19899, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合法", "is_correct": true, "explanation": "正确。“是不合法的”表示做法违反法律，符合律师的判断。"}, {"text": "准确", "is_correct": false, "explanation": "搭配：“准确”多用来说信息或数据，不用来说做广告这种行为。"}, {"text": "完整", "is_correct": false, "explanation": "搭配：“完整”多用来说内容或文件是否齐全，不用来说做广告这种行为。"}, {"text": "可能", "is_correct": false, "explanation": "语义：“是不可能的”说做广告不会发生，与现实相悖，句意不通。"}], "explanations": {"合法": "正确。“是不合法的”表示做法违反法律，符合律师的判断。", "准确": "搭配：“准确”多用来说信息或数据，不用来说做广告这种行为。", "完整": "搭配：“完整”多用来说内容或文件是否齐全，不用来说做广告这种行为。", "可能": "语义：“是不可能的”说做广告不会发生，与现实相悖，句意不通。"}, "sentence_index": 6, "correct_answer": "合法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们两个的性格很合法，常常一起出去玩。", "explanation": "这里应该用〈合拍〉。性情相投要用合拍，合法不能用来形容人的性格。"}, {"text": "这道菜的味道很合法，我每次都要多吃一碗。", "explanation": "这里应该用〈合口〉。味道合胃口要用合口，合法只说符合法律规定。"}, {"text": "这首诗的韵脚很合法，读起来很顺。", "explanation": "这里应该用〈合辙〉。押韵相合要用合辙，合法不能用来形容韵脚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19899, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他合法的赚钱，不怕警察检查。", "corrected_sentence": "他合法地赚钱，不怕警察检查。", "error_description": "错误：“合法”修饰动词“赚钱”时作状语，不能用“的”连接。正确应为“合法地赚钱”，也可说“合法赚钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19899, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店没合法，警察已经来查了。", "corrected_sentence": "这家店不合法，警察已经来查了。", "error_description": "错误：形容词“合法”的否定要用“不”，不用“没”。正确应为“不合法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
