INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19902, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指不正确、不符合事实或标准的事物或行为。", "primary_collocate": null, "pronunciation": "cuò wù", "ipa": "tsʰwo˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "定期检查数据质量，可以减少错误结果。", "target_word": "错误", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "老师帮我改正了这个错误。", "target_word": "错误", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不怕犯错误，因为可以从中学习。", "target_word": "错误", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你检查一下作业里有没有错误。", "target_word": "错误", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一个很大的错误，我们必须马上改正。", "target_word": "错误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的一个错误可能会影响病人的健康。", "target_word": "错误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他承认了自己的错误，并向大家道歉。", "target_word": "错误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同样的错误，你不要再犯第二次。", "target_word": "错误", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报告里有两个错误，请你再看一遍。", "target_word": "错误", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明发现自己的答案有错误。", "target_word": "错误", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "错误率", "label": "复合"}, {"form": "錯誤", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：不正确、不符合事实或标准的事物或行为，可以犯、改正、检查", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33088bf9-1fe7-4ce5-b719-265e37e48a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19902, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "错误", "is_correct": true, "explanation": "错误：作定语修饰“结果”，指不正确的结果，与“减少”搭配自然。"}, {"text": "成功", "is_correct": false, "explanation": "语义：“减少成功的结果”与句子想要减少错误的目的相反。"}, {"text": "正确", "is_correct": false, "explanation": "语义：“减少正确的结果”与“减少错误”的目的矛盾。"}, {"text": "收益", "is_correct": false, "explanation": "搭配：“收益”不能修饰“结果”，不说“收益结果”。"}], "explanations": {"错误": "错误：作定语修饰“结果”，指不正确的结果，与“减少”搭配自然。", "成功": "语义：“减少成功的结果”与句子想要减少错误的目的相反。", "正确": "语义：“减少正确的结果”与“减少错误”的目的矛盾。", "收益": "搭配：“收益”不能修饰“结果”，不说“收益结果”。"}, "sentence_index": 0, "correct_answer": "错误"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的错误比我高一头，大家都很羡慕。", "explanation": "这里应该用〈个子〉。说人的高矮要用个子或身高；错误指做错的事，不能用来说高矮。"}, {"text": "这顿饭的错误很香，我吃了两碗。", "explanation": "这里应该用〈香〉。说饭菜的香气要用香；错误指做错的事，不能形容气味。"}, {"text": "这支笔的错误很亮，看起来很漂亮。", "explanation": "这里应该用〈颜色〉。说亮不亮要用颜色；错误指做错的事，不能形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "错误", "is_correct": true, "explanation": "错误：名词，指做错的事，“承认”的对象正是这类事情。"}, {"text": "优点", "is_correct": false, "explanation": "语义：优点不需要道歉，与“承认……并向大家道歉”的语境矛盾。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“承认”不能带“礼物”作宾语，句子不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能被承认，也不需要道歉，“承认了自己的天气”句意不通。"}], "explanations": {"错误": "错误：名词，指做错的事，“承认”的对象正是这类事情。", "优点": "语义：优点不需要道歉，与“承认……并向大家道歉”的语境矛盾。", "礼物": "搭配：“承认”不能带“礼物”作宾语，句子不通。", "天气": "语义：“天气”不能被承认，也不需要道歉，“承认了自己的天气”句意不通。"}, "sentence_index": 6, "correct_answer": "错误"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的错误是安静。", "explanation": "这里应该用〈特点〉。特点指事物突出的性质；错误指做错的事或不对的内容，不能用来说明城市的性质。"}, {"text": "这次考试的错误很好。", "explanation": "这里应该用〈成绩〉。成绩指考试或工作的结果；错误指做错的事或不对的内容，不能说“错误很好”。"}, {"text": "这个房间的错误很整洁，大家都很喜欢。", "explanation": "这里应该用〈整洁〉。说房间干净利落要用整洁；错误指做错的事，不能形容房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直不承认这条错误，大家都很失望。", "corrected_sentence": "他一直不承认这个错误，大家都很失望。", "error_description": "错误形式：“这条错误”，“条”是长条形事物的量词，不能用于错误。正确形式：“这个错误”，“个”是通用量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份试卷上有一把小错误，老师已经改过来了。", "corrected_sentence": "这份试卷上有一个小错误，老师已经改过来了。", "error_description": "错误形式：“一把小错误”，“把”是带柄器具的量词，不能用于错误。正确形式：“一个小错误”，“个”是通用量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19903, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拒绝", "is_correct": true, "explanation": "正确：“拒绝”与“接受”构成反义，表示不同意并不收下。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细看，与“接受”不构成反义。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指随意走动，与“接受”不构成反义。"}, {"text": "整理", "is_correct": false, "explanation": "“整理”指把东西理顺、归位，与“接受”不构成反义。"}], "correct_answer": "拒绝", "explanations": {"拒绝": "正确：“拒绝”与“接受”构成反义，表示不同意并不收下。", "观察": "“观察”指仔细看，与“接受”不构成反义。", "散步": "“散步”指随意走动，与“接受”不构成反义。", "整理": "“整理”指把东西理顺、归位，与“接受”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19903, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拒绝", "is_correct": true, "explanation": "正确：“拒绝”与“接受”构成反义，表示不同意并不收下。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”指在水中运动，与“接受”不构成反义。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指发声演唱，与“接受”不构成反义。"}, {"text": "清洗", "is_correct": false, "explanation": "“清洗”指用水去除污物，与“接受”不构成反义。"}], "correct_answer": "拒绝", "explanations": {"拒绝": "正确：“拒绝”与“接受”构成反义，表示不同意并不收下。", "游泳": "“游泳”指在水中运动，与“接受”不构成反义。", "唱歌": "“唱歌”指发声演唱，与“接受”不构成反义。", "清洗": "“清洗”指用水去除污物，与“接受”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19903, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示对别人给予的事物或建议表示同意并收下。", "primary_collocate": null, "pronunciation": "jiē shòu", "ipa": "tɕjɛ˥ ʂoʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "员工需要接受培训，了解隐私保护的重要性，并知道违反规则的后果。", "target_word": "接受", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "最后，企业要制定明确的政策，并接受外部监督。", "target_word": "接受", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他接受了我的建议。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板接受了他的道歉。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个想法我一时很难接受。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她接受了那家公司的工作邀请。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要学会接受别人的批评。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不接受这样的结果，所以又试了一次。", "target_word": "接受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校接受了这笔捐赠。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我接受过两年专业训练。", "target_word": "接受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "接受了", "label": "体标"}, {"form": "接受过", "label": "体标"}, {"form": "接受着", "label": "体标"}, {"form": "接受者", "label": "复合"}], "register": "中性", "sense_fingerprint": "同意并收下别人给予的建议、安排、批评、监督等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '248f5714-59ca-4c41-94f7-b47c7a28fb77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19903, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接受", "is_correct": true, "explanation": "正确：“接受”表示同意并收下，与“培训”搭配，符合句意。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不接受，与“需要”和后文“了解重要性”的要求矛盾。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”表示不重视，与“了解重要性、知道后果”的要求矛盾。"}, {"text": "抵制", "is_correct": false, "explanation": "语义：“需要”之后接“抵制培训”，与“需要”的语气相矛盾，句意不通。"}], "explanations": {"接受": "正确：“接受”表示同意并收下，与“培训”搭配，符合句意。", "拒绝": "语义：“拒绝”表示不接受，与“需要”和后文“了解重要性”的要求矛盾。", "忽视": "语义：“忽视”表示不重视，与“了解重要性、知道后果”的要求矛盾。", "抵制": "语义：“需要”之后接“抵制培训”，与“需要”的语气相矛盾，句意不通。"}, "sentence_index": 0, "correct_answer": "接受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天接受了一封朋友寄来的信。", "explanation": "这里应该用〈收到〉。接受指同意并收下别人给的意见、礼物或安排，收信件要用收到。"}, {"text": "农民在地里接受了很多庄稼。", "explanation": "这里应该用〈收获〉。接受指同意收下别人给的东西或意见；收割地里的庄稼要用收获。"}, {"text": "他接受着剧烈的头痛，没有去医院。", "explanation": "这里应该用〈忍受〉。接受指同意收下，承受痛苦、难受的事要用忍受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19903, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接受", "is_correct": true, "explanation": "正确：“接受”表示同意并收下，与“别人的批评”搭配，符合句意。"}, {"text": "收拾", "is_correct": false, "explanation": "搭配：“收拾”的对象是物品或场地，不能说“收拾别人的批评”。"}, {"text": "说服", "is_correct": false, "explanation": "搭配：“说服”的宾语应是人，不能说“说服别人的批评”。"}, {"text": "播种", "is_correct": false, "explanation": "搭配：“播种”指撒种子，不能用于“批评”，句意不通。"}], "explanations": {"接受": "正确：“接受”表示同意并收下，与“别人的批评”搭配，符合句意。", "收拾": "搭配：“收拾”的对象是物品或场地，不能说“收拾别人的批评”。", "说服": "搭配：“说服”的宾语应是人，不能说“说服别人的批评”。", "播种": "搭配：“播种”指撒种子，不能用于“批评”，句意不通。"}, "sentence_index": 6, "correct_answer": "接受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校接受了一次全校比赛。", "explanation": "这里应该用〈举办〉。接受指同意收下或接纳别人的意见、人或物；组织比赛、活动要用举办。"}, {"text": "公司接受了一名工程师去国外。", "explanation": "这里应该用〈派遣〉。接受指同意收下；派人出差、驻外要用派遣。"}, {"text": "电视台接受了一段新闻。", "explanation": "这里应该用〈播放〉。接受指同意收下；把节目、新闻送上屏幕要用播放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19903, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天我会接受了他的道歉。", "corrected_sentence": "明天我会接受他的道歉。", "error_description": "“会”表示将来，不能与“了”同用；“接受”后不加“了”。正确形式为“明天我会接受他的道歉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19903, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来不接受过别人的批评。", "corrected_sentence": "我从来没接受过别人的批评。", "error_description": "否定词错误：表示从未有过某种经历，“过”前应用“没”，不能用“不”。正确形式为“从来没接受过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
