INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19904, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "通过教导和练习，使某人掌握某种知识或技能的过程。", "primary_collocate": null, "pronunciation": "péi xùn", "ipa": "pʰei˧˥ ɕyn˥˩", "syllable_count": 2, "sentences": [{"text": "员工需要接受培训，了解隐私保护的重要性，并知道违反规则的后果。", "target_word": "培训", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "公司给新同事做了两天培训。", "target_word": "培训", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次培训很有用，我学到了很多。", "target_word": "培训", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天上午有一个培训，请大家准时到。", "target_word": "培训", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新老师都要参加培训。", "target_word": "培训", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在培训中认识了很多朋友。", "target_word": "培训", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个培训一共有五节课，每周一节。", "target_word": "培训", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "参加培训之前，我什么都不会做。", "target_word": "培训", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "培训结束后，每个人都拿到了证书。", "target_word": "培训", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院每年都为护士安排培训。", "target_word": "培训", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "培训班", "label": "复合"}, {"form": "培训师", "label": "复合"}, {"form": "培訓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：为掌握知识或技能而参加的教导和练习过程，可以参加、接受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33088bf9-1fe7-4ce5-b719-265e37e48a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19904, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "培训", "is_correct": true, "explanation": "培训：指通过教导和练习使人掌握知识或技能的过程，符合“员工需要接受……”的语境。"}, {"text": "手术", "is_correct": false, "explanation": "语义：手术是医疗操作，与隐私保护和违反规则的后果无关，句意荒谬。"}, {"text": "疫苗", "is_correct": false, "explanation": "语义：疫苗是预防疾病的制剂，与“了解隐私保护的重要性”无关，句意荒谬。"}, {"text": "洗礼", "is_correct": false, "explanation": "语域：“洗礼”带宗教或比喻色彩，用在员工规章的语境中不合语域。"}], "explanations": {"培训": "培训：指通过教导和练习使人掌握知识或技能的过程，符合“员工需要接受……”的语境。", "手术": "语义：手术是医疗操作，与隐私保护和违反规则的后果无关，句意荒谬。", "疫苗": "语义：疫苗是预防疾病的制剂，与“了解隐私保护的重要性”无关，句意荒谬。", "洗礼": "语域：“洗礼”带宗教或比喻色彩，用在员工规章的语境中不合语域。"}, "sentence_index": 0, "correct_answer": "培训"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天培训肌肉，身材越来越好。", "explanation": "这里应该用〈训练〉。培训指传授知识或技能，对象是人；肌肉要靠训练增强，不能说“培训肌肉”。"}, {"text": "我今天参加了一台培训，学到了很多东西。", "explanation": "这里应该用量词〈次〉或〈个〉。“台”多用于机器、电视等，不能用来数“培训”这类活动。"}, {"text": "这场培训的冠军是我们班。", "explanation": "这里应该用〈比赛〉。冠军需要竞赛产生，培训是教导和练习，没有冠军。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "培训", "is_correct": true, "explanation": "培训：指通过教导和练习使人掌握知识或技能的过程，符合“这个……一共有五节课”的语境。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：比赛按场次或轮次计算，不以“节课”计数，句意不通。"}, {"text": "旅行", "is_correct": false, "explanation": "语义：旅行不能按“节课”计数，也不会“每周一节”，句意荒谬。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影按部或集计算，不能说“一共有五节课”，也不会“每周一节”，句意荒谬。"}], "explanations": {"培训": "培训：指通过教导和练习使人掌握知识或技能的过程，符合“这个……一共有五节课”的语境。", "比赛": "语义：比赛按场次或轮次计算，不以“节课”计数，句意不通。", "旅行": "语义：旅行不能按“节课”计数，也不会“每周一节”，句意荒谬。", "电影": "语义：电影按部或集计算，不能说“一共有五节课”，也不会“每周一节”，句意荒谬。"}, "sentence_index": 6, "correct_answer": "培训"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "果农每年培训很多树苗，成活率很高。", "explanation": "这里应该用〈培育〉。培育用于树苗、花木等植物，培训的对象是人，不能用于树苗。"}, {"text": "这家培训的菜很好吃。", "explanation": "这里应该用〈餐厅〉。餐厅才有菜品，培训不是饮食场所，不能说“菜很好吃”。"}, {"text": "他和同事一起工作了五年，培训了很深的感情。", "explanation": "这里应该用〈培养〉。感情要慢慢培养，“培训”指短期的传授知识或技能，不能用于感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我上周参加了一位培训。", "corrected_sentence": "我上周参加了一次培训。", "error_description": "量词错误：“培训”是活动，应用量词“次”。“位”只用于人，把“一次培训”写成“一位培训”不合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下周要去上海参加一张培训。", "corrected_sentence": "他下周要去上海参加一次培训。", "error_description": "量词错误：“培训”是活动，应用量词“次”。“张”用于纸张、票据、桌子等物件，不能用来数“培训”，“一张培训”不合语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
