INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19905, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不遵守规则或法律，做了不允许做的事。", "primary_collocate": null, "pronunciation": "wéi fǎn", "ipa": "weɪ˧˥ fan˨˩˦", "syllable_count": 2, "sentences": [{"text": "员工需要接受培训，了解隐私保护的重要性，并知道违反规则的后果。", "target_word": "违反", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "开车时打电话违反交通规则。", "target_word": "违反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他违反了学校的规定，老师批评了他。", "target_word": "违反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "违反法律的人要受到处罚。", "target_word": "违反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在图书馆大声说话违反规定。", "target_word": "违反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司不允许员工违反合同。", "target_word": "违反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样做违反了我们的约定。", "target_word": "违反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来没有违反过交通规则。", "target_word": "违反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判让违反规则的球员下场了。", "target_word": "违反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个做法违反了法律，所以不能用。", "target_word": "违反", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "违反了", "label": "体标"}, {"form": "违反过", "label": "体标"}, {"form": "違反", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：不遵守规则、法律、规定、合同，做了不允许的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33088bf9-1fe7-4ce5-b719-265e37e48a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19905, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "违反", "is_correct": true, "explanation": "违反：不遵守规则，做了不允许做的事，符合“知道……规则的后果”的语境。"}, {"text": "编写", "is_correct": false, "explanation": "语义：编写指撰写文字，与“规则的后果”无关，句意不通。"}, {"text": "收取", "is_correct": false, "explanation": "搭配：“收取”的宾语是费用、押金，不能说“收取规则”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱指发出乐音，“唱规则”的后果不成立，句意荒谬。"}], "explanations": {"违反": "违反：不遵守规则，做了不允许做的事，符合“知道……规则的后果”的语境。", "编写": "语义：编写指撰写文字，与“规则的后果”无关，句意不通。", "收取": "搭配：“收取”的宾语是费用、押金，不能说“收取规则”。", "唱": "语义：唱指发出乐音，“唱规则”的后果不成立，句意荒谬。"}, "sentence_index": 0, "correct_answer": "违反"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他故意违反了公共设施。", "explanation": "这里应该用〈破坏〉。违反的对象是规则或法律，公共设施是物件，只能破坏。"}, {"text": "他一气之下把那堵墙违反了。", "explanation": "这里应该用〈拆〉。违反的对象是规则或法律，墙是物件，应该说“拆”。"}, {"text": "士兵奋力违反敌人。", "explanation": "这里应该用〈抵抗〉。违反的对象是规则，不能是敌人，应该用〈抵抗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19905, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "违反", "is_correct": true, "explanation": "违反：不遵守规则或约定，做了不允许做的事，符合“这样做……了我们的约定”的语境。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”指把食物咽下去，与“约定”无关，句意荒谬。"}, {"text": "签订", "is_correct": false, "explanation": "搭配：“签订”多用于合同、协议，一般不说“签订约定”。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指赏识美好的事物，不能用来处理约定，句意不通。"}], "explanations": {"违反": "违反：不遵守规则或约定，做了不允许做的事，符合“这样做……了我们的约定”的语境。", "吃掉": "语义：“吃掉”指把食物咽下去，与“约定”无关，句意荒谬。", "签订": "搭配：“签订”多用于合同、协议，一般不说“签订约定”。", "欣赏": "语义：“欣赏”指赏识美好的事物，不能用来处理约定，句意不通。"}, "sentence_index": 6, "correct_answer": "违反"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用证据违反了自己的清白。", "explanation": "这里应该用〈证明〉。清白要靠证据证明，违反的对象是规则，不能是清白。"}, {"text": "警察应该违反市民的安全。", "explanation": "这里应该用〈保护〉。违反针对规则，警察应保护的是市民的安全。"}, {"text": "他违反了朋友的邀请。", "explanation": "这里应该用〈拒绝〉。拒绝的对象是邀请，违反针对规则，不能用于邀请。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他违反得学校的纪律。", "corrected_sentence": "他违反了学校的纪律。", "error_description": "补语错误：“违反”后应接动态助词“了”，表示动作完成。误用结构助词“得”，后面需要补语，不能直接带宾语。应改为“违反了学校的纪律”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在考试中作弊，严重违反得学校的纪律。", "corrected_sentence": "他在考试中作弊，严重违反了学校的纪律。", "error_description": "补语错误：“违反”后应接动态助词“了”，表示动作完成。写成“违反得”把它当成程度补语，不合语法，应改为“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5620aa9b-086b-46b2-96a5-0da3736dc0a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
