INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19906, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943a5350-b284-4306-888b-633c1a675559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19906, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情发展最后产生的结果，多指不好的结局。", "primary_collocate": null, "pronunciation": "hòu guǒ", "ipa": "xou˥˩ kuo˨˩˦", "syllable_count": 2, "sentences": [{"text": "员工需要接受培训，了解隐私保护的重要性，并知道违反规则的后果。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "做事以前，先想一想后果。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不听医生的话，后果很严重。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车喝酒会有什么后果？", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要为自己的错误负责，也要接受后果。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的后果，我们谁也没想到。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不写作业，后果是老师会生气。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早就知道迟到的后果，所以今天提前出门了。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不遵守交通规则，可能带来很坏的后果。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个错误造成的后果，一年后才看出来。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个后果", "label": "量词"}, {"form": "後果", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事情发展最终产生的不好的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17113f72-d326-456d-bb4f-e59bc63232d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19906, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后果", "is_correct": true, "explanation": "正确：后果指违反规则之后产生的不好结局，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与违反规则的结果无关，句意不通。"}, {"text": "优点", "is_correct": false, "explanation": "语义：优点是正面评价，与“违反规则”的负面语境相反。"}, {"text": "印象", "is_correct": false, "explanation": "搭配：“违反规则”之后接的是结果、处罚一类的名词，“印象”不能与“违反规则”搭配。"}], "explanations": {"后果": "正确：后果指违反规则之后产生的不好结局，与句意相符。", "颜色": "语义：颜色与违反规则的结果无关，句意不通。", "优点": "语义：优点是正面评价，与“违反规则”的负面语境相反。", "印象": "搭配：“违反规则”之后接的是结果、处罚一类的名词，“印象”不能与“违反规则”搭配。"}, "sentence_index": 0, "correct_answer": "后果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的后果很高，有一米八。", "explanation": "这里应该用〈身高〉。后果指事情发展产生的结果，不能用来说人的身高。"}, {"text": "他迟到的后果是路上堵车了。", "explanation": "后果指的是产生的结果，不是原因。这里堵车是迟到的原因，应该用〈原因〉。"}, {"text": "这部电影的后果很长，我看了三个小时。", "explanation": "这里应该用〈时长〉。后果指事情发展产生的结果，不能用来说影片的长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943a5350-b284-4306-888b-633c1a675559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后果", "is_correct": true, "explanation": "正确：后果指不写作业之后引出的结果，句中“是老师会生气”正好是这个结果。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音与孩子不写作业没有直接关系，句意不通。"}, {"text": "任务", "is_correct": false, "explanation": "语义：任务是需要完成的事，老师生气不是孩子要完成的任务。"}, {"text": "体会", "is_correct": false, "explanation": "搭配：“体会”一般接感受、经验，不能引出“老师会生气”这类后续结果。"}], "explanations": {"后果": "正确：后果指不写作业之后引出的结果，句中“是老师会生气”正好是这个结果。", "声音": "语义：声音与孩子不写作业没有直接关系，句意不通。", "任务": "语义：任务是需要完成的事，老师生气不是孩子要完成的任务。", "体会": "搭配：“体会”一般接感受、经验，不能引出“老师会生气”这类后续结果。"}, "sentence_index": 6, "correct_answer": "后果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次运动会的后果很长，我们玩了一整天。", "explanation": "这里应该用〈时长〉。后果指事情产生的结果，不能用来说活动持续的时间。"}, {"text": "我把这个后果送给了朋友。", "explanation": "后果指事情发展的结果，不能当作东西送人，这里应该用〈礼物〉。"}, {"text": "这件事的后果是用邮件通知大家的。", "explanation": "后果指事情造成的结果，不能指通知的方式，这里应该用〈方式〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943a5350-b284-4306-888b-633c1a675559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只后果谁都不想看到。", "corrected_sentence": "这种后果谁都不想看到。", "error_description": "量词错误：“后果”的量词应为“种”（或“个”）。“只”用于动物等，不能修饰“后果”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943a5350-b284-4306-888b-633c1a675559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不复习地后果很严重。", "corrected_sentence": "他不复习的后果很严重。", "error_description": "结构助词错误：修饰名词“后果”应用“的”，“地”用于修饰动词、形容词，写成“地后果”不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943a5350-b284-4306-888b-633c1a675559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
