INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19908, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指程式、系统、理论等中存在的缺陷或薄弱之处。", "primary_collocate": null, "pronunciation": "lòu dòng", "ipa": "lou˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "第三方审计可以帮助发现漏洞。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个软件有一个安全漏洞。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在修补系统的漏洞。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的说法有很多漏洞，没人相信。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行的管理制度存在漏洞。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑客利用漏洞进入了公司的网站。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律有漏洞，坏人就会钻空子。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查一遍计划，看看有没有漏洞。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套规则还有漏洞，需要再改一改。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机更新以后，旧的漏洞就没有了。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个漏洞", "label": "量词"}, {"form": "安全漏洞", "label": "复合"}], "register": "中性", "sense_fingerprint": "系统、制度或说法中的缺陷", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17113f72-d326-456d-bb4f-e59bc63232d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19908, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漏洞", "is_correct": true, "explanation": "正确：漏洞指系统、说法等中的缺陷，审计可以发现这类问题。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是审计要找的缺陷，不能被“发现”为问题。"}, {"text": "心情", "is_correct": false, "explanation": "语义：审计发现的是缺陷，“心情”不是可被审计发现的对象，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：审计要找的是缺陷，“味道”与发现问题无关，句意不通。"}], "explanations": {"漏洞": "正确：漏洞指系统、说法等中的缺陷，审计可以发现这类问题。", "颜色": "语义：颜色不是审计要找的缺陷，不能被“发现”为问题。", "心情": "语义：审计发现的是缺陷，“心情”不是可被审计发现的对象，句意不通。", "味道": "语义：审计要找的是缺陷，“味道”与发现问题无关，句意不通。"}, "sentence_index": 0, "correct_answer": "漏洞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛的漏洞是我们赢了三分。", "explanation": "漏洞指系统、理论中的缺陷，这里说的是比分，应该用〈比分〉。"}, {"text": "这道菜的漏洞很香，大家都抢着吃。", "explanation": "漏洞指缺陷或破损处，这里说的是菜的味道，应该用〈味道〉。"}, {"text": "这个城市的漏洞是交通很方便。", "explanation": "漏洞指缺陷，表示优点要用〈优点〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943a5350-b284-4306-888b-633c1a675559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "漏洞", "is_correct": true, "explanation": "正确：漏洞指法律中的缺陷，坏人可以利用它钻空子。"}, {"text": "故事", "is_correct": false, "explanation": "语义：法律不是故事，“法律有故事”与坏人钻空子的逻辑不相关。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“有脾气”要求有生命的主语，法律不能有脾气。"}, {"text": "胃口", "is_correct": false, "explanation": "语义：胃口说的是食欲，与法律无关，句意不通。"}], "explanations": {"漏洞": "正确：漏洞指法律中的缺陷，坏人可以利用它钻空子。", "故事": "语义：法律不是故事，“法律有故事”与坏人钻空子的逻辑不相关。", "脾气": "搭配：“有脾气”要求有生命的主语，法律不能有脾气。", "胃口": "语义：胃口说的是食欲，与法律无关，句意不通。"}, "sentence_index": 6, "correct_answer": "漏洞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个手机的漏洞能拍出很漂亮的照片。", "explanation": "漏洞指缺陷，这里说的是手机的功能，应该用〈功能〉。"}, {"text": "这本小说的漏洞写得很生动。", "explanation": "漏洞指缺陷，描写生动的故事情节要用〈情节〉。"}, {"text": "我把这个漏洞扔进了垃圾桶。", "explanation": "漏洞指系统中的缺陷，是抽象的问题，不是能扔掉的实物，这里应该说〈删除〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943a5350-b284-4306-888b-633c1a675559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套系统还有一只严重的漏洞。", "corrected_sentence": "这套系统还有一个严重的漏洞。", "error_description": "量词错误：“漏洞”的量词应为“个”，“只”不能修饰“漏洞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943a5350-b284-4306-888b-633c1a675559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套规则漏洞，大家都能看出来。", "corrected_sentence": "这套规则有漏洞，大家都能看出来。", "error_description": "漏掉动词：“漏洞”作宾语，需要动词“有”引出，应为“有漏洞”；写成“规则漏洞”句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943a5350-b284-4306-888b-633c1a675559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
