INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19911, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在完成某个任务或过程中，起到决定性作用的一个步骤。", "primary_collocate": null, "pronunciation": "guān jiàn bù zhòu", "ipa": "kwan˥ tɕjɛn˥˩ pu˥˩ ʈʂoʊ̯˥˩", "syllable_count": 4, "sentences": [{"text": "总的来看，公开数据做法和算法原则，不是负担，而是建立长期信任的关键步骤。", "target_word": "关键步骤", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "洗手是预防生病的关键步骤。", "target_word": "关键步骤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做菜时，先准备材料是关键步骤。", "target_word": "关键步骤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个实验有三个关键步骤，不能做错。", "target_word": "关键步骤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，检查答案是考试中的关键步骤。", "target_word": "关键步骤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们已经完成了计划的第一个关键步骤。", "target_word": "关键步骤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学外语时，开口说话是关键步骤。", "target_word": "关键步骤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修好机器的关键步骤是先关电源。", "target_word": "关键步骤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把这个关键步骤再说一遍。", "target_word": "关键步骤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缺少这个关键步骤，工作就会失败。", "target_word": "关键步骤", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个关键步骤", "label": "量词"}, {"form": "關鍵步驟", "label": "繁体"}], "register": "中性", "sense_fingerprint": "关键步骤|完成任务或过程中起决定作用的步骤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17113f72-d326-456d-bb4f-e59bc63232d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19911, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关键步骤", "is_correct": true, "explanation": "指建立长期信任中起决定作用的环节，与“不是负担，而是……”的判断相符。"}, {"text": "负担", "is_correct": false, "explanation": "语义：句中已说“不是负担”，再填“负担”就自相矛盾。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与本句的书面语体不合，也不能指建立信任的环节。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与公开数据、算法原则无关，不能是建立长期信任的环节。"}], "explanations": {"关键步骤": "指建立长期信任中起决定作用的环节，与“不是负担，而是……”的判断相符。", "负担": "语义：句中已说“不是负担”，再填“负担”就自相矛盾。", "玩意儿": "语域：“玩意儿”是口语，与本句的书面语体不合，也不能指建立信任的环节。", "天气": "语义：天气与公开数据、算法原则无关，不能是建立长期信任的环节。"}, "sentence_index": 0, "correct_answer": "关键步骤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位同学是班里的关键步骤。", "explanation": "这里应该用〈关键人物〉。“步骤”指做事情的环节，不能用来指人。"}, {"text": "老师给我们讲了一把关键步骤。", "explanation": "这里应该用〈一个〉或〈一道〉。“把”用于有柄的器具，不用于步骤。"}, {"text": "比赛进入了关键步骤，球员们很紧张。", "explanation": "这里应该用〈关键时刻〉。“步骤”指做事的环节，比赛到了紧要关头要说“时刻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943a5350-b284-4306-888b-633c1a675559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19911, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关键步骤", "is_correct": true, "explanation": "指学习外语中决定进步的一步，与“开口说话”的语境相符。"}, {"text": "美食", "is_correct": false, "explanation": "语义：“开口说话”不是美食，句子无法成立。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身材，与开口说话无关。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“开口说话”不能是颜色，句子无法成立。"}], "explanations": {"关键步骤": "指学习外语中决定进步的一步，与“开口说话”的语境相符。", "美食": "语义：“开口说话”不是美食，句子无法成立。", "身高": "体貌：“身高”指人的身材，与开口说话无关。", "颜色": "语义：“开口说话”不能是颜色，句子无法成立。"}, "sentence_index": 6, "correct_answer": "关键步骤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在剧中扮演了关键步骤。", "explanation": "这里应该用〈关键角色〉。步骤是做事的环节，不能被扮演，应说“扮演关键角色”。"}, {"text": "这份报告里有三部关键步骤。", "explanation": "这里应该用〈个〉。“部”用于书籍、电影等作品，不用于步骤。"}, {"text": "她把关键步骤吃掉了。", "explanation": "这里应该用〈完成〉。步骤是做事的环节，不能被吃掉，应说“完成关键步骤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943a5350-b284-4306-888b-633c1a675559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19911, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是修电脑的一把关键步骤。", "corrected_sentence": "这是修电脑的一个关键步骤。", "error_description": "“一把”用于有柄的器具，不能修饰“关键步骤”，应改为“一个关键步骤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943a5350-b284-4306-888b-633c1a675559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19911, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是做蛋糕时关键步骤。", "corrected_sentence": "这是做蛋糕时的关键步骤。", "error_description": "时间短语修饰名词时要加“的”，应为“做蛋糕时的关键步骤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943a5350-b284-4306-888b-633c1a675559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
