INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19916, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "知道某件事的内情或真相。", "primary_collocate": null, "pronunciation": "zhī qíng", "ipa": "ʈʂɻ̩˥ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "首先，训练数据的采集与使用需满足“知情—同意”框架的实质要求，这意味着企业不能仅依赖用户协议中的概括性条款，而应通过分层披露机制，清晰说明数据将被用于模型训练的具体场景、类别及潜在影响，尤其在涉及个人敏感信息或生成式内容时，须实现可验证的用户授权路径。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这件事我完全不知情。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是唯一知情的人。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的人对此并不知情。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察想问问知情的邻居。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知情却不说，这样不好。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们对家里的困难不知情。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时只有两个人知情。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己事先并不知情。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "知情的同事都不愿意说话。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不知情", "label": "否定"}, {"form": "知情人", "label": "复合"}, {"form": "知情权", "label": "复合"}], "register": "中性", "sense_fingerprint": "知道某件事的内情或真相", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32cca9b7-00be-47a2-8603-0c4deb9a2c2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19916, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "知情", "is_correct": true, "explanation": "正确：知情 zhī qíng，指知道某件事的内情或真相。"}, {"text": "知青", "is_correct": false, "explanation": "知青 zhī qīng 与 知情 第二音节声调不同（阴平与阳平），意思是知识青年。"}, {"text": "痴情", "is_correct": false, "explanation": "痴情 chī qíng 与 知情 声母不同（ch 与 zh），意思是深切的感情。"}, {"text": "诗情", "is_correct": false, "explanation": "诗情 shī qíng 与 知情 声母不同（sh 与 zh），意思是诗意的情感。"}, {"text": "知名", "is_correct": false, "explanation": "知名 zhī míng 与 知情 第二音节声母不同（m 与 q），意思是有名气。"}], "explanations": {"知情": "正确：知情 zhī qíng，指知道某件事的内情或真相。", "知青": "知青 zhī qīng 与 知情 第二音节声调不同（阴平与阳平），意思是知识青年。", "痴情": "痴情 chī qíng 与 知情 声母不同（ch 与 zh），意思是深切的感情。", "诗情": "诗情 shī qíng 与 知情 声母不同（sh 与 zh），意思是诗意的情感。", "知名": "知名 zhī míng 与 知情 第二音节声母不同（m 与 q），意思是有名气。"}, "sentence_index": null, "correct_answer": "知情"}, "level_3": {"options": [{"text": "知情", "is_correct": true, "explanation": "正确：“知情—同意”是固定术语，指在知悉相关信息的前提下作出的同意。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：句中要求“分层披露”和“清晰说明”，与“隐瞒”的意思相反。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：句中明确要求企业不能仅依赖概括性条款，忽略与此矛盾。"}, {"text": "猜测", "is_correct": false, "explanation": "搭配：“猜测—同意”不构成术语，句中要求的是可验证的授权路径，不能靠猜测。"}], "explanations": {"知情": "正确：“知情—同意”是固定术语，指在知悉相关信息的前提下作出的同意。", "隐瞒": "语义：句中要求“分层披露”和“清晰说明”，与“隐瞒”的意思相反。", "忽略": "语义：句中明确要求企业不能仅依赖概括性条款，忽略与此矛盾。", "猜测": "搭配：“猜测—同意”不构成术语，句中要求的是可验证的授权路径，不能靠猜测。"}, "sentence_index": 0, "correct_answer": "知情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我知情他的电话号码，所以能随时打给他。", "explanation": "这里应该用〈知道〉。知情不能直接带“电话号码”这样的宾语，要说“知道他的电话号码”。"}, {"text": "他这次考试很知情，成绩一定很好。", "explanation": "这里应该用〈认真〉。知情指知道内情，不能用来形容学习的态度。"}, {"text": "我很知情你的性格，所以才这样说。", "explanation": "这里应该用〈了解〉。知情不带“性格”这类宾语，表示了解一个人要用“了解”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19916, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "知情", "is_correct": true, "explanation": "正确：知情 zhī qíng，指知道某件事的内情或真相。"}, {"text": "知行", "is_correct": false, "explanation": "知行 zhī xíng 与 知情 第二音节声母不同（x 与 q），意思是认识与实践。"}, {"text": "事情", "is_correct": false, "explanation": "事情 shì qíng 与 知情 第一音节声母与声调都不同（sh 与 zh，第四声与第一声），意思是事件或情况。"}, {"text": "实情", "is_correct": false, "explanation": "实情 shí qíng 与 知情 第一音节声母与声调不同（sh 与 zh，第二声与第一声），意思是实际的情况。"}, {"text": "真情", "is_correct": false, "explanation": "真情 zhēn qíng 与 知情 第一音节韵母不同（en 与 i），意思是真实的感情。"}, {"text": "深情", "is_correct": false, "explanation": "深情 shēn qíng 与 知情 第一音节声母与韵母都不同（sh、en 与 zh、i），意思是深厚的感情。"}, {"text": "私情", "is_correct": false, "explanation": "私情 sī qíng 与 知情 第一音节声母不同（s 与 zh），意思是私人的感情或私下的交情。"}], "explanations": {"知情": "正确：知情 zhī qíng，指知道某件事的内情或真相。", "知行": "知行 zhī xíng 与 知情 第二音节声母不同（x 与 q），意思是认识与实践。", "事情": "事情 shì qíng 与 知情 第一音节声母与声调都不同（sh 与 zh，第四声与第一声），意思是事件或情况。", "实情": "实情 shí qíng 与 知情 第一音节声母与声调不同（sh 与 zh，第二声与第一声），意思是实际的情况。", "真情": "真情 zhēn qíng 与 知情 第一音节韵母不同（en 与 i），意思是真实的感情。", "深情": "深情 shēn qíng 与 知情 第一音节声母与韵母都不同（sh、en 与 zh、i），意思是深厚的感情。", "私情": "私情 sī qíng 与 知情 第一音节声母不同（s 与 zh），意思是私人的感情或私下的交情。"}, "sentence_index": null, "correct_answer": "知情"}, "level_3": {"options": [{"text": "知情", "is_correct": true, "explanation": "正确：“不知情”指不了解内情，与句中“家里的困难”所指的情况相合。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”含有喜爱、愉悦之意，“对困难不享受”与句意相悖。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象多为作品、风景，不能说“欣赏困难”。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”的对象是人或事物的优点，不能用于“困难”。"}], "explanations": {"知情": "正确：“不知情”指不了解内情，与句中“家里的困难”所指的情况相合。", "享受": "语义：“享受”含有喜爱、愉悦之意，“对困难不享受”与句意相悖。", "欣赏": "搭配：“欣赏”的对象多为作品、风景，不能说“欣赏困难”。", "赞美": "搭配：“赞美”的对象是人或事物的优点，不能用于“困难”。"}, "sentence_index": 6, "correct_answer": "知情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我知情他的生日，所以提前准备了礼物。", "explanation": "这里应该用〈记得〉。知情指知道内情或真相，不能带“生日”这类个人信息作宾语，应说“记得他的生日”。"}, {"text": "她知情地笑了笑。", "explanation": "这里应该用〈会心〉。知情指知道内情，不表示会意的神情，描写笑的样子要说“会心地笑”。"}, {"text": "这台电脑很知情，用起来很顺手。", "explanation": "这里应该用〈智能〉。知情指知道内情，不能用来形容物品的功能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都对这件事了知情。", "corrected_sentence": "大家都对这件事知情。", "error_description": "错误：“了”放在“知情”之前，不能说“了知情”。“知情”是动词，“了”不能放在动词前面，此处应说“大家都对这件事知情”，去掉动词前的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事孩子们都了不知情。", "corrected_sentence": "这件事孩子们都不知情。", "error_description": "错误：“了”放在否定词“不”之前，不能说“都了不知情”，应说“都不知情”，去掉“不”前面多余的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19917, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "正确：反对与同意（表示认可、赞成）构成反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "与同意无反义关系，“散步”是一种活动。"}, {"text": "打扫", "is_correct": false, "explanation": "与同意无反义关系，“打扫”指清理场所。"}, {"text": "购买", "is_correct": false, "explanation": "与同意无反义关系，“购买”指付钱获得物品。"}], "correct_answer": "反对", "explanations": {"反对": "正确：反对与同意（表示认可、赞成）构成反义关系。", "散步": "与同意无反义关系，“散步”是一种活动。", "打扫": "与同意无反义关系，“打扫”指清理场所。", "购买": "与同意无反义关系，“购买”指付钱获得物品。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
