INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19917, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指对某件事情或某个看法表示认可、赞成，双方意见一致。", "primary_collocate": null, "pronunciation": "tóng yì", "ipa": "tʰʊŋ³⁵ i⁵¹", "syllable_count": 2, "sentences": [{"text": "首先，训练数据的采集与使用需满足“知情—同意”框架的实质要求，这意味着企业不能仅依赖用户协议中的概括性条款，而应通过分层披露机制，清晰说明数据将被用于模型训练的具体场景、类别及潜在影响，尤其在涉及个人敏感信息或生成式内容时，须实现可验证的用户授权路径。", "target_word": "同意", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "妈妈同意我周末去朋友家玩。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不同意我们明天考试。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理同意了我的请假申请。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你同意这个办法吗？", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直不同意搬到别的城市住。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生同意他明天出院。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房东同意把房租少收一百块。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问了爸爸，他很快就同意了。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的计划，公司已经同意了。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "同意了", "label": "体标"}, {"form": "不同意", "label": "否定"}, {"form": "同意书", "label": "复合"}], "register": "中性", "sense_fingerprint": "对事情或看法表示认可、赞成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 房东 (Zipf 3.86), 房租 (Zipf 3.92), 一百块 (Zipf 3.13)']::text[], '32cca9b7-00be-47a2-8603-0c4deb9a2c2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19917, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同意", "is_correct": true, "explanation": "正确：同意 tóng yì，指对某件事或某个看法表示认可、赞成。"}, {"text": "同事", "is_correct": false, "explanation": "同事 tóng shì 与 同意 第二音节声母不同（sh 与 y），意思是共事的人。"}, {"text": "同一", "is_correct": false, "explanation": "同一 tóng yī 与 同意 第二音节声调不同（第一声与第四声），意思是相同的。"}, {"text": "中意", "is_correct": false, "explanation": "中意 zhōng yì 与 同意 第一音节声母与声调不同（zh 与 t，第一声与第二声），意思是满意、喜欢。"}, {"text": "同理", "is_correct": false, "explanation": "同理 tóng lǐ 与 同意 第二音节声母与声调不同（l 与 y，第三声与第四声），意思是同样的道理。"}, {"text": "同日", "is_correct": false, "explanation": "同日 tóng rì 与 同意 第二音节声母不同（r 与零声母），意思是同一天。"}], "explanations": {"同意": "正确：同意 tóng yì，指对某件事或某个看法表示认可、赞成。", "同事": "同事 tóng shì 与 同意 第二音节声母不同（sh 与 y），意思是共事的人。", "同一": "同一 tóng yī 与 同意 第二音节声调不同（第一声与第四声），意思是相同的。", "中意": "中意 zhōng yì 与 同意 第一音节声母与声调不同（zh 与 t，第一声与第二声），意思是满意、喜欢。", "同理": "同理 tóng lǐ 与 同意 第二音节声母与声调不同（l 与 y，第三声与第四声），意思是同样的道理。", "同日": "同日 tóng rì 与 同意 第二音节声母不同（r 与零声母），意思是同一天。"}, "sentence_index": null, "correct_answer": "同意"}, "level_3": {"options": [{"text": "同意", "is_correct": true, "explanation": "正确：“知情—同意”是固定术语，指在知情的基础上表示认可。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“知情—删除”不成术语，与句中的授权路径不相合。"}, {"text": "分析", "is_correct": false, "explanation": "语义：句意是规定用户授权，而不是对数据做分析。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，与授权框架无关。"}], "explanations": {"同意": "正确：“知情—同意”是固定术语，指在知情的基础上表示认可。", "删除": "搭配：“知情—删除”不成术语，与句中的授权路径不相合。", "分析": "语义：句意是规定用户授权，而不是对数据做分析。", "翻译": "语义：“翻译”指转换语言，与授权框架无关。"}, "sentence_index": 0, "correct_answer": "同意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司同意了他的能力。", "explanation": "这里应该用〈认可〉。同意用于请求、计划、意见，不能用于“能力”这类属性。"}, {"text": "他同意了这个错误。", "explanation": "这里应该用〈承认〉。同意是接受请求或建议，不能用来指承认错误。"}, {"text": "我同意你的帮助。", "explanation": "这里应该用〈感谢〉。同意不能用于“帮助”这类人际行为的回应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19917, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同意", "is_correct": true, "explanation": "正确：“医生同意他明天出院”表示医生认可他出院。"}, {"text": "游览", "is_correct": false, "explanation": "语义：“游览”指参观景物，与医生决定患者出院无关。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是作品或风景，不能用于“出院”这样的事件。"}, {"text": "收割", "is_correct": false, "explanation": "语义：“收割”指收取农作物，与医生的决定毫不相关。"}], "explanations": {"同意": "正确：“医生同意他明天出院”表示医生认可他出院。", "游览": "语义：“游览”指参观景物，与医生决定患者出院无关。", "欣赏": "搭配：“欣赏”的对象是作品或风景，不能用于“出院”这样的事件。", "收割": "语义：“收割”指收取农作物，与医生的决定毫不相关。"}, "sentence_index": 6, "correct_answer": "同意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司同意了这个月的天气。", "explanation": "这里应该用〈预报〉。同意不能用于天气这类客观情况。"}, {"text": "我同意了这个梦。", "explanation": "这里应该用〈梦见〉。同意指赞成、接受请求或计划，不指做梦，“梦”的内容要说“梦见”。"}, {"text": "老师同意了他的脾气。", "explanation": "这里应该用〈忍受〉。同意不能用于“脾气”这类性格特点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19917, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们俩都了同意他的说法。", "corrected_sentence": "我们俩都同意他的说法。", "error_description": "错误：“了”放在“同意”之前，不能说“都了同意他的说法”，应说“都同意他的说法”，“了”不能放在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19917, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生已经了同意他出院。", "corrected_sentence": "医生已经同意他出院。", "error_description": "错误：“了”放在“同意”之前，不能说“已经了同意他出院”，应说“已经同意他出院”，“了”不能放在动词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19918, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "具体性", "is_correct": true, "explanation": "具体性与概括性相对：概括性指归纳共同点，具体性指细节明确、针对个别事物。"}, {"text": "连续性", "is_correct": false, "explanation": "与概括性无反义关系：连续性指时间或空间上不间断的特性。"}, {"text": "时效性", "is_correct": false, "explanation": "与概括性无反义关系：时效性指在一定时间内有效的特性。"}, {"text": "可靠性", "is_correct": false, "explanation": "与概括性无反义关系：可靠性指值得信赖、不易出错的特性。"}], "correct_answer": "具体性", "explanations": {"具体性": "具体性与概括性相对：概括性指归纳共同点，具体性指细节明确、针对个别事物。", "连续性": "与概括性无反义关系：连续性指时间或空间上不间断的特性。", "时效性": "与概括性无反义关系：时效性指在一定时间内有效的特性。", "可靠性": "与概括性无反义关系：可靠性指值得信赖、不易出错的特性。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19918, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "具体性", "is_correct": true, "explanation": "具体性与概括性相对：概括性指归纳共同点，具体性指细节明确、针对个别事物。"}, {"text": "流动性", "is_correct": false, "explanation": "与概括性无反义关系：流动性指事物能够移动、变化的特性。"}, {"text": "独立性", "is_correct": false, "explanation": "与概括性无反义关系：独立性指不依附他人或事物的特性。"}, {"text": "稳定性", "is_correct": false, "explanation": "与概括性无反义关系：稳定性指不易发生变化的特性。"}], "correct_answer": "具体性", "explanations": {"具体性": "具体性与概括性相对：概括性指归纳共同点，具体性指细节明确、针对个别事物。", "流动性": "与概括性无反义关系：流动性指事物能够移动、变化的特性。", "独立性": "与概括性无反义关系：独立性指不依附他人或事物的特性。", "稳定性": "与概括性无反义关系：稳定性指不易发生变化的特性。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19918, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指对事物共同特征进行归纳和总结的特性。", "primary_collocate": null, "pronunciation": "gài kuò xìng", "ipa": "kaɪ⁵¹ kʰuɔ⁵¹ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "首先，训练数据的采集与使用需满足“知情—同意”框架的实质要求，这意味着企业不能仅依赖用户协议中的概括性条款，而应通过分层披露机制，清晰说明数据将被用于模型训练的具体场景、类别及潜在影响，尤其在涉及个人敏感信息或生成式内容时，须实现可验证的用户授权路径。", "target_word": "概括性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个标题的概括性很强。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的发言很有概括性。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话太有概括性了，没有细节。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这篇文章的概括性不够。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总结要有概括性，不能写得太长。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词的概括性比较强，能说很多东西。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的回答概括性太强，我没听懂细节。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告缺少概括性，读起来很乱。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的题目一般都有概括性。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "概括", "label": "词根"}], "register": "书面", "sense_fingerprint": "归纳总结共同特征的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32cca9b7-00be-47a2-8603-0c4deb9a2c2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "概括性", "is_correct": true, "explanation": "概括性修饰条款，指条款写得笼统、覆盖面宽，符合句意。"}, {"text": "口头性", "is_correct": false, "explanation": "语义：用户协议是书面文件，「口头性条款」与协议的书面形式相矛盾。"}, {"text": "情感性", "is_correct": false, "explanation": "语域：条款是法律文本，用「情感性」形容不合规范，也与「清晰说明」的要求相反。"}, {"text": "图像性", "is_correct": false, "explanation": "搭配：「图像性」多修饰图形、画面，不能修饰条款。"}], "explanations": {"概括性": "概括性修饰条款，指条款写得笼统、覆盖面宽，符合句意。", "口头性": "语义：用户协议是书面文件，「口头性条款」与协议的书面形式相矛盾。", "情感性": "语域：条款是法律文本，用「情感性」形容不合规范，也与「清晰说明」的要求相反。", "图像性": "搭配：「图像性」多修饰图形、画面，不能修饰条款。"}, "sentence_index": 0, "correct_answer": "概括性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位医生的概括性很强，每次诊断都有依据。", "explanation": "这里应该用〈严谨性〉。概括性指归纳共同点的特性，不指医生做事是否严密；形容医生做事严谨，应说“严谨性很强”。"}, {"text": "这张桌子的概括性很强。", "explanation": "这里应该用〈结实〉。概括性指归纳共同点的特性，不指家具的牢固程度；形容桌子牢固，应说“很结实”。"}, {"text": "我家的猫很有概括性。", "explanation": "这里应该用〈可爱〉。概括性指归纳共同点的特性，不用来形容动物；形容猫，应说“很可爱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "概括性", "is_correct": true, "explanation": "概括性指能归纳很多事物的共同点，与「能说很多东西」相符。"}, {"text": "单一性", "is_correct": false, "explanation": "语义：单一性指只有一种，与「能说很多东西」的含义相反。"}, {"text": "具体性", "is_correct": false, "explanation": "语义：具体性指细节明确，与「能说很多东西」的广泛含义不符。"}, {"text": "唯一性", "is_correct": false, "explanation": "语义：唯一性指只有一个，与「能说很多东西」的广泛含义相反。"}], "explanations": {"概括性": "概括性指能归纳很多事物的共同点，与「能说很多东西」相符。", "单一性": "语义：单一性指只有一种，与「能说很多东西」的含义相反。", "具体性": "语义：具体性指细节明确，与「能说很多东西」的广泛含义不符。", "唯一性": "语义：唯一性指只有一个，与「能说很多东西」的广泛含义相反。"}, "sentence_index": 6, "correct_answer": "概括性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把尺子的概括性很高，能量到毫米。", "explanation": "这里应该用〈精确性〉。概括性指归纳共同点的特性，不指测量的准确程度；尺子能量到毫米，应说精确性高。"}, {"text": "这家银行的概括性很高，存款很安全。", "explanation": "这里应该用〈可靠性〉。概括性指归纳共同点的特性，不指银行的信用程度；存款安全，应说可靠性高。"}, {"text": "他的译文概括性很好，读起来很顺。", "explanation": "这里应该用〈流畅性〉。概括性指归纳共同点的特性，不指译文是否通顺；读起来很顺，应说流畅性好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告有一把很强的概括性，读起来很清楚。", "corrected_sentence": "这份报告有一种很强的概括性，读起来很清楚。", "error_description": "量词错误：「概括性」是抽象名词，应用「种」；「把」用于有柄的器具，不能用来修饰概括性。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的回答很概括性，抓住了重点。", "corrected_sentence": "他的回答很有概括性，抓住了重点。", "error_description": "搭配错误：「概括性」是名词，不能直接用「很」修饰，应说「很有概括性」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
