INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19920, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指戏剧、电影、电视剧等中的场面，也泛指某种情形或情景。", "primary_collocate": null, "pronunciation": "chǎng jǐng", "ipa": "tʂʰɑŋ˨˩˦ tɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "首先，训练数据的采集与使用需满足“知情—同意”框架的实质要求，这意味着企业不能仅依赖用户协议中的概括性条款，而应通过分层披露机制，清晰说明数据将被用于模型训练的具体场景、类别及潜在影响，尤其在涉及个人敏感信息或生成式内容时，须实现可验证的用户授权路径。", "target_word": "场景", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这部电影的最后一个场景让我很感动。", "target_word": "场景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的雪地场景非常漂亮。", "target_word": "场景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在故事里写了一个下雨的场景。", "target_word": "场景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机可以用在很多生活场景里。", "target_word": "场景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们在课堂上练习购物场景。", "target_word": "场景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个场景我小时候见过，所以很熟悉。", "target_word": "场景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演想重新拍一遍海边的场景。", "target_word": "场景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在开会这样的场景里，说话要小心。", "target_word": "场景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁里的拥挤场景每天都能看到。", "target_word": "场景", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个场景", "label": "量词"}, {"form": "应用场景", "label": "复合"}, {"form": "生活场景", "label": "复合"}], "register": "中性", "sense_fingerprint": "场景：戏剧影视中的场面，或泛指某种情形情景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '793f12b2-1a45-4e9f-b63f-7c7c045ff77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "场景", "is_correct": true, "explanation": "正确。这里指数据用于训练的具体情境，与“具体”搭配，与“类别”“潜在影响”并列。"}, {"text": "场面", "is_correct": false, "explanation": "语义：场面指看得见的热闹景象，数据的使用情境不能说成场面。"}, {"text": "情节", "is_correct": false, "explanation": "语义：情节指故事中事件的发展，与数据的使用方式无关。"}, {"text": "光景", "is_correct": false, "explanation": "语域：“光景”偏旧式口语，不适合这种正式的合规条款。"}], "explanations": {"场景": "正确。这里指数据用于训练的具体情境，与“具体”搭配，与“类别”“潜在影响”并列。", "场面": "语义：场面指看得见的热闹景象，数据的使用情境不能说成场面。", "情节": "语义：情节指故事中事件的发展，与数据的使用方式无关。", "光景": "语域：“光景”偏旧式口语，不适合这种正式的合规条款。"}, "sentence_index": 0, "correct_answer": "场景"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议的场景定在一百元。", "explanation": "这里应该用〈价格〉。“定在一百元”说的是金额，场景指戏剧、电影中的场面或某种情形，不能用来定价。"}, {"text": "我们在体育馆打场景。", "explanation": "这里应该用〈球〉。“打”后接球类活动，场景指戏剧、电影中的场面或某种情形，不能被“打”。"}, {"text": "他一口气喝完了这个场景。", "explanation": "这里应该用〈茶〉。“喝”的对象是饮品，场景是画面或情形，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "场景", "is_correct": true, "explanation": "正确。“这个场景”指看过、熟悉的情形或画面，与“见过”“熟悉”搭配。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“见过”针对看到的东西，歌曲要说“听过”，不能说“见过”。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间看不见，“这个时间我小时候见过”不能成立。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：味道要靠闻或尝来感知，不能说“见过”。"}], "explanations": {"场景": "正确。“这个场景”指看过、熟悉的情形或画面，与“见过”“熟悉”搭配。", "歌曲": "搭配：“见过”针对看到的东西，歌曲要说“听过”，不能说“见过”。", "时间": "语义：时间看不见，“这个时间我小时候见过”不能成立。", "味道": "搭配：味道要靠闻或尝来感知，不能说“见过”。"}, "sentence_index": 6, "correct_answer": "场景"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "演员说场景时很自然。", "explanation": "这里应该用〈台词〉。“说”的对象是台词，场景是画面或情形，不能用“说”。"}, {"text": "这个场景跳得很高。", "explanation": "这里应该用〈运动员〉。“跳得很高”的主语须是人，场景指戏剧、电影中的场面或某种情形，不能用来描述跳跃。"}, {"text": "这首歌的场景很好听。", "explanation": "这里应该用〈声音〉。“好听”形容声音，场景是看见的情形，不能形容听觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电影里有一只很感人的场景。", "corrected_sentence": "电影里有一个很感人的场景。", "error_description": "量词错误：“场景”应用通用量词“个”，不能用“只”。“只”多用于动物或成对物件中的一个，与“场景”不搭。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条场景拍得很美。", "corrected_sentence": "这个场景拍得很美。", "error_description": "量词错误：“场景”应用通用量词“个”，不能用“条”。“条”多用于河流、消息、规定等事物，与“场景”不搭。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
