INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19921, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物具有的共同特点所形成的种类或等级。", "primary_collocate": null, "pronunciation": "lèi bié", "ipa": "lei˥˩ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "首先，训练数据的采集与使用需满足“知情—同意”框架的实质要求，这意味着企业不能仅依赖用户协议中的概括性条款，而应通过分层披露机制，清晰说明数据将被用于模型训练的具体场景、类别及潜在影响，尤其在涉及个人敏感信息或生成式内容时，须实现可验证的用户授权路径。", "target_word": "类别", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家书店的书按类别摆放。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先选择你想买的商品类别。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆把书分成了很多类别。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们按年龄把学生分成三个类别。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果和蔬菜是两个不同的类别。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站的音乐分为好几个类别。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题属于同一个类别。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的商品类别很多。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以在这个类别里找到所有的帽子。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "類別", "label": "繁体"}], "register": "中性", "sense_fingerprint": "类别：按共同特点分出的种类或等级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d5cc799-3df8-4bb6-b844-1bd220175944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19921, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "类别", "is_correct": true, "explanation": "正确：与“具体场景”并列，指数据用途所属的种类，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：说明数据用途时没有“颜色”这一项，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的外形特征，不能与“场景”并列说明数据的使用。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指食物或气味的性质，不能作为数据用途的说明项。"}], "explanations": {"类别": "正确：与“具体场景”并列，指数据用途所属的种类，符合句意。", "颜色": "语义：说明数据用途时没有“颜色”这一项，句意不通。", "身高": "体貌：“身高”指人的外形特征，不能与“场景”并列说明数据的使用。", "味道": "语义：“味道”指食物或气味的性质，不能作为数据用途的说明项。"}, "sentence_index": 0, "correct_answer": "类别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "疼痛的类别很轻。", "explanation": "这里应该用〈程度〉。类别指按共同特点分出的种类，不表示轻重；描述疼痛的轻重要用程度。"}, {"text": "班里学生的类别是三十人。", "explanation": "这里应该用〈数目〉。类别不表示人或东西的数量，说明有多少人要用数目。"}, {"text": "这部电影的类别是一百二十分钟。", "explanation": "这里应该用〈片长〉。类别指事物共同特点形成的种类或等级，不能表示时间的长短；说电影有多长要用片长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19921, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "类别", "is_correct": true, "explanation": "正确：指音乐被分成的几类，与“分为好几个”搭配，符合句意。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”指一个地区的人数总和，不能与“分为好几个”搭配。"}, {"text": "体重", "is_correct": false, "explanation": "语义：音乐不能按“体重”来分类，句意不通。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：“海拔”指地面高出海平面的高度，与音乐的分类无关。"}], "explanations": {"类别": "正确：指音乐被分成的几类，与“分为好几个”搭配，符合句意。", "人口": "搭配：“人口”指一个地区的人数总和，不能与“分为好几个”搭配。", "体重": "语义：音乐不能按“体重”来分类，句意不通。", "海拔": "语义：“海拔”指地面高出海平面的高度，与音乐的分类无关。"}, "sentence_index": 6, "correct_answer": "类别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书店里有五张类别。", "explanation": "量词错误：类别应该用“个”。“张”多用于纸张、桌子等，不用来数类别。"}, {"text": "我们学校有三台类别。", "explanation": "量词错误：“台”用于机器、电脑等，类别应该用“个”。"}, {"text": "这个仓库里有两颗类别。", "explanation": "量词错误：类别应该用“个”。“颗”多用于圆形的小颗粒或果实，不用来数类别，这里的量词用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19921, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些书可以分成三只类别。", "corrected_sentence": "这些书可以分成三个类别。", "error_description": "量词错误：类别的量词应该用“个”，不能用“只”（“只”多用于动物）。正确的说法是“三个类别”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19921, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们这个类别里找到了所有的帽子。", "corrected_sentence": "我们在这个类别里找到了所有的帽子。", "error_description": "介词缺失：表示“在某个类别之中”要用“在……里”，此处漏掉了“在”。正确的说法是“在这个类别里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
