INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19925, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "计算机程序的原始文本，由编程语言编写，人类可读，需编译或解释后才能运行。", "primary_collocate": null, "pronunciation": "yuán dài mǎ", "ipa": "ɥɛn˧˥ taɪ̯˥˩ ma˨˩˦", "syllable_count": 3, "sentences": [{"text": "其次，算法透明度并非要求公开源代码或核心商业机密，而是通过“可解释性报告”“影响评估文档”等形式，向监管机构与公众传达系统的关键决策逻辑、偏差缓解措施及风险控制机制。", "target_word": "源代码", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个软件的源代码是公开的。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都要写很多源代码。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程序员检查了源代码里的错误。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不愿意公开源代码。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把源代码发给我看看。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "源代码需要编译才能运行。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段源代码有两百行。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上下载了开源软件的源代码。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看不懂这份源代码。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段源代码", "label": "量词"}, {"form": "一份源代码", "label": "量词"}, {"form": "开放源代码", "label": "复合"}, {"form": "源代碼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "程序员用编程语言写成、需编译或解释后才能运行的程序原始文本", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d5cc799-3df8-4bb6-b844-1bd220175944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19925, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "源代码", "is_correct": true, "explanation": "正确：算法透明度要求公开的是源代码，即程序的原始文本，与“公开”的对象相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以公开的文件或信息，与“公开”的对象不符。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“公开”多用于信息、资料，不说公开心情。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是自然环境，不是可以公开的技术内容。"}], "explanations": {"源代码": "正确：算法透明度要求公开的是源代码，即程序的原始文本，与“公开”的对象相符。", "天气": "语义：天气不是可以公开的文件或信息，与“公开”的对象不符。", "心情": "搭配：“公开”多用于信息、资料，不说公开心情。", "空气": "语义：空气是自然环境，不是可以公开的技术内容。"}, "sentence_index": 0, "correct_answer": "源代码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的源代码是用英文写的。", "explanation": "这里应该用“原文”。源代码指写电脑程序的文本，不能指书的底本；书的外文底本应说原文。"}, {"text": "这个源代码可以直接在手机上运行。", "explanation": "这里应该用“程序”。源代码是需编译或解释后才能运行的文本，不能直接运行，能直接运行的是程序。"}, {"text": "这条河的源代码在西部的大山里。", "explanation": "这里应该用“源头”。源代码指写程序的文本，不能指河流的起点；河流的起点应说源头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19925, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "源代码", "is_correct": true, "explanation": "正确：源代码需要编译或解释后才能运行，与句意相符。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是查阅用的工具书，不是需要编译才能运行的程序文本。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐是声音作品，不是需要编译的程序文本。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“编译”只用于程序、代码，不能说编译花朵。"}], "explanations": {"源代码": "正确：源代码需要编译或解释后才能运行，与句意相符。", "字典": "语义：字典是查阅用的工具书，不是需要编译才能运行的程序文本。", "音乐": "语义：音乐是声音作品，不是需要编译的程序文本。", "花朵": "搭配：“编译”只用于程序、代码，不能说编译花朵。"}, "sentence_index": 6, "correct_answer": "源代码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的源代码写在一张旧纸上。", "explanation": "这里应该用“配方”。源代码指写程序的文本，不能指做菜的方法；写在纸上的做菜方法应说配方。"}, {"text": "这首曲子的源代码很难看懂。", "explanation": "这里应该用“乐谱”。源代码指写程序的文本，不能指曲子的记谱；曲子的记谱应说乐谱。"}, {"text": "他忘了邮箱的源代码，只好重新设置。", "explanation": "这里应该用“密码”。源代码指写程序的文字和符号，不能用来登录邮箱；登录邮箱的应是密码。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19925, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程师把一只源代码交给了测试团队。", "corrected_sentence": "工程师把一段源代码交给了测试团队。", "error_description": "错误：“一只源代码”，应为“一段源代码”。“只”用于动物，源代码的量词是段、份。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19925, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一辆源代码打印出来，一页一页地看。", "corrected_sentence": "他把一段源代码打印出来，一页一页地看。", "error_description": "错误：“一辆源代码”，应为“一段源代码”。“辆”用于车辆，源代码的量词是段、份。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19926, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "公开", "is_correct": true, "explanation": "正确：“公开”与“机密”意思相反，指让大家知道的信息。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”说明明白，与“机密”的保密含义无关。"}, {"text": "普通", "is_correct": false, "explanation": "语义：“普通”说明一般，与“机密”的保密含义无关。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”说明场面喧闹，与“机密”的保密含义无关。"}], "correct_answer": "公开", "explanations": {"公开": "正确：“公开”与“机密”意思相反，指让大家知道的信息。", "清楚": "语义：“清楚”说明明白，与“机密”的保密含义无关。", "普通": "语义：“普通”说明一般，与“机密”的保密含义无关。", "热闹": "语义：“热闹”说明场面喧闹，与“机密”的保密含义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19926, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "公开", "is_correct": true, "explanation": "正确：“公开”与“机密”意思相反，指让大家知道的信息。"}, {"text": "简单", "is_correct": false, "explanation": "语义：“简单”说明不复杂，与“机密”的保密含义无关。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”说明光线充足，与“机密”的保密含义无关。"}, {"text": "普遍", "is_correct": false, "explanation": "语义：“普遍”说明范围广，与“机密”的保密含义无关。"}], "correct_answer": "公开", "explanations": {"公开": "正确：“公开”与“机密”意思相反，指让大家知道的信息。", "简单": "语义：“简单”说明不复杂，与“机密”的保密含义无关。", "明亮": "语义：“明亮”说明光线充足，与“机密”的保密含义无关。", "普遍": "语义：“普遍”说明范围广，与“机密”的保密含义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19926, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指重要且需要保密的文件、信息或事情。", "primary_collocate": null, "pronunciation": "jī mì", "ipa": "tɕi˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "其次，算法透明度并非要求公开源代码或核心商业机密，而是通过“可解释性报告”“影响评估文档”等形式，向监管机构与公众传达系统的关键决策逻辑、偏差缓解措施及风险控制机制。", "target_word": "机密", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这份文件是公司的机密。", "target_word": "机密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他泄露了国家机密。", "target_word": "机密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "员工不能向外人透露公司机密。", "target_word": "机密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一项重要的军事机密。", "target_word": "机密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划是最高机密。", "target_word": "机密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者想打听政府的机密。", "target_word": "机密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向外国人出卖了国家机密。", "target_word": "机密", "complexity_tier": "T3", "furigana": "tā xiàng wài guó rén chū mài le guó jiā jī mì", "sentence_source": "generated"}, {"text": "保守机密是每个员工的责任。", "target_word": "机密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他知道很多公司的机密。", "target_word": "机密", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份机密", "label": "量词"}, {"form": "一项机密", "label": "量词"}, {"form": "国家机密", "label": "复合"}, {"form": "商业机密", "label": "复合"}, {"form": "機密", "label": "繁体"}], "register": "正式", "sense_fingerprint": "国家、军事、商业等方面重要而必须保密的信息或事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d5cc799-3df8-4bb6-b844-1bd220175944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19926, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机密", "is_correct": true, "explanation": "正确：“核心商业机密”是固定说法，“机密”指需要保密的重要信息，与句意相符。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵是植物的一部分，不是商业上需要保密的信息。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是商业上需要保密的重要信息。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“核心商业”后接的是需要保密的信息，不说核心商业面包。"}], "explanations": {"机密": "正确：“核心商业机密”是固定说法，“机密”指需要保密的重要信息，与句意相符。", "花朵": "语义：花朵是植物的一部分，不是商业上需要保密的信息。", "天气": "语义：天气不是商业上需要保密的重要信息。", "面包": "搭配：“核心商业”后接的是需要保密的信息，不说核心商业面包。"}, "sentence_index": 0, "correct_answer": "机密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机密运转得很快。", "explanation": "这里应该用“机器”。机密指需要保密的重要文件或信息，不是机器；“台”可以用于机器，但“机密”不能指机器。"}, {"text": "他忘了邮箱的机密，只好重新设置。", "explanation": "这里应该用“密码”。机密是需要保密的重要信息，不能用来登录邮箱；登录邮箱的应是密码。"}, {"text": "这道题的机密很难，我们都做不出来。", "explanation": "这里应该用“难点”。机密指需要保密的信息，不能用来形容题目的难度；题目的难处应说难点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机密", "is_correct": true, "explanation": "正确：“机密”指政府需要保密的重要信息，是“打听”的对象。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不是政府需要保密的信息，不能打听。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐是声音作品，不是政府的保密内容。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“打听”用于消息、情况，不说打听汽车。"}], "explanations": {"机密": "正确：“机密”指政府需要保密的重要信息，是“打听”的对象。", "花朵": "语义：花朵不是政府需要保密的信息，不能打听。", "音乐": "语义：音乐是声音作品，不是政府的保密内容。", "汽车": "搭配：“打听”用于消息、情况，不说打听汽车。"}, "sentence_index": 6, "correct_answer": "机密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙藏进了那个机密里，我们找了一整天。", "explanation": "这里应该用“密室”。机密指需要保密的重要文件、信息或事情，不是能装东西的地方；能藏钥匙的应是密室。"}, {"text": "这份机密可以在图书馆借阅。", "explanation": "这里应该用“资料”。机密是需要保密的重要文件或信息，不能对外借阅；图书馆可以借阅的应是资料。"}, {"text": "他把这个机密拿来挡雨。", "explanation": "这里应该用“雨伞”。机密指需要保密的信息，不能拿来挡雨；挡雨的应是雨伞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只机密已经被列入保密名单。", "corrected_sentence": "这份机密已经被列入保密名单。", "error_description": "错误：“这只机密”，应为“这份机密”。“只”用于动物或成对器官，机密文件、信息的量词是份、项。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这棵机密只能由少数人查阅。", "corrected_sentence": "这份机密只能由少数人查阅。", "error_description": "错误：“这棵机密”，应为“这份机密”。“棵”用于树木，机密文件、信息的量词是份、项。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
