INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19929, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为实现特定目标而建立的组织或部门，如政府机构、科研机构。", "primary_collocate": null, "pronunciation": "jī gòu", "ipa": "tɕi˥ kou˥˩", "syllable_count": 2, "sentences": [{"text": "这家科研机构有很多专家。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府机构要为人民服务。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家金融机构工作。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机构成立了十年。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请联系有关机构了解情况。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家建立了专门的检查机构。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家机构的研究员每年做一次调查。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医疗机构要保护病人的信息。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想去国际机构实习。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些机构都由政府管理。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "政府机构", "label": "复合"}, {"form": "科研机构", "label": "复合"}, {"form": "金融机构", "label": "复合"}, {"form": "機構", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "为实现特定目标而建立的组织或部门", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '057e6d26-3654-4b17-8f8c-867298f547be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19929, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机构", "is_correct": true, "explanation": "正确：“机构”指为实现特定目标而设立的组织，“科研机构”是常见搭配，与“有很多专家”相符。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：“餐厅”是吃饭的地方，不是科研单位，“科研餐厅”说不通。"}, {"text": "铺子", "is_correct": false, "explanation": "语域：“铺子”是口语，指小买卖的店，与书面语“科研”不协调，也不是研究单位。"}, {"text": "宾馆", "is_correct": false, "explanation": "语义：“宾馆”是住宿的地方，与“科研”无关，“科研宾馆”说不通。"}], "explanations": {"机构": "正确：“机构”指为实现特定目标而设立的组织，“科研机构”是常见搭配，与“有很多专家”相符。", "餐厅": "语义：“餐厅”是吃饭的地方，不是科研单位，“科研餐厅”说不通。", "铺子": "语域：“铺子”是口语，指小买卖的店，与书面语“科研”不协调，也不是研究单位。", "宾馆": "语义：“宾馆”是住宿的地方，与“科研”无关，“科研宾馆”说不通。"}, "sentence_index": 0, "correct_answer": "机构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个句子的机构很复杂。", "explanation": "这里应该用〈结构〉。“机构”指组织或部门，句子内部的组合方式要用“结构”，不能用“机构”。"}, {"text": "这位机构成立了十年。", "explanation": "这里应该用〈个〉或〈家〉。“位”用于人，不用来数组织，“机构”要用“个”或“家”。"}, {"text": "我们几个朋友组成了一个小机构，每周一起爬山。", "explanation": "这里应该用〈团体〉。“机构”指为实现特定目标而设立的正式组织，几个朋友自发组成的小群体要用“团体”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19929, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机构", "is_correct": true, "explanation": "正确：“机构”指组织，可以每年开展调查，与“这家”和“做一次调查”相符。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店没有研究员，“理发店的研究员”说不通。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不设研究员，“花园的研究员”说不通。"}, {"text": "小店", "is_correct": false, "explanation": "语义：小店一般没有研究员，“小店的研究员”说不通。"}], "explanations": {"机构": "正确：“机构”指组织，可以每年开展调查，与“这家”和“做一次调查”相符。", "理发店": "语义：理发店没有研究员，“理发店的研究员”说不通。", "花园": "语义：花园不设研究员，“花园的研究员”说不通。", "小店": "语义：小店一般没有研究员，“小店的研究员”说不通。"}, "sentence_index": 6, "correct_answer": "机构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的猫是一个机构。", "explanation": "这里应该用〈动物〉。“机构”指为实现特定目标而设立的组织，不能用来指一只猫，猫属于动物。"}, {"text": "这只检查机构每年都抽查一次。", "explanation": "这里应该用〈个〉或〈家〉。“只”多用于动物或成对物品之一，不用来数机构。"}, {"text": "这个机构有五口人。", "explanation": "这里应该用〈家庭〉。“五口人”是用来数家庭成员的说法，“机构”是组织，不能这样计算人口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去了一只大型研究机构。", "corrected_sentence": "他去了一家大型研究机构。", "error_description": "量词错误：“机构”应该用量词“家”或“个”，不能用“只”。“只”多用于动物或成对物品之一，如“一只猫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19929, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前在一把国际机构工作过。", "corrected_sentence": "我以前在一家国际机构工作过。", "error_description": "量词错误：“机构”应该用量词“家”，不能用“把”。“把”多用于有柄的东西，如“一把椅子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
