INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19930, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19930, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对重要事情做出选择和判断。", "primary_collocate": null, "pronunciation": "jué cè", "ipa": "tɕye˧˥ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "代理不仅执行任务，还能对自身决策过程进行反思性建模，通过多层级反馈回路调整目标函数。", "target_word": "决策", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种潜在的技术异化，迫使我们必须重新审视图灵测试之后的智能评估体系：是否应建立“自主性-责任性”双轴评价框架，以衡量代理在自由决策与社会嵌入之间的平衡能力？", "target_word": "决策", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其次，算法透明度并非要求公开源代码或核心商业机密，而是通过“可解释性报告”“影响评估文档”等形式，向监管机构与公众传达系统的关键决策逻辑、偏差缓解措施及风险控制机制。", "target_word": "决策", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "经理在会上做出了一项重要决策。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的决策需要足够的信息。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个决策让全公司的人都很吃惊。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对这次决策负全部责任。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "错误的决策会让公司损失很多钱。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市长的决策影响了整个城市。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的重大决策要由董事会讨论。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "决策者", "label": "复合"}, {"form": "決策", "label": "繁体"}], "register": "书面", "sense_fingerprint": "决策|名词|对重要事情做出的选择和判断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deaa3fc3-7c1a-43a4-81dd-1b732cf27d0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "决策", "is_correct": true, "explanation": "正确。“决策过程”指做选择和判断的过程，正是句中反思建模的对象。"}, {"text": "答案", "is_correct": false, "explanation": "语义：“答案”是结果，不是可以被建模的决策过程，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“过程”前不能用“颜色”这类表示属性的名词来修饰。"}, {"text": "事儿", "is_correct": false, "explanation": "语域：“事儿”是口语词，与这句书面语的语域不符。"}], "explanations": {"决策": "正确。“决策过程”指做选择和判断的过程，正是句中反思建模的对象。", "答案": "语义：“答案”是结果，不是可以被建模的决策过程，句意不通。", "颜色": "搭配：“过程”前不能用“颜色”这类表示属性的名词来修饰。", "事儿": "语域：“事儿”是口语词，与这句书面语的语域不符。"}, "sentence_index": 0, "correct_answer": "决策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题有四个决策。", "explanation": "这里应该用〈选项〉。“决策”指做选择和判断的行为，题目里供挑选的备选答案要说“选项”。"}, {"text": "他喝了一杯决策。", "explanation": "这里应该用〈茶〉。“杯”用来计量饮品，“决策”是做选择和判断的行为，不能喝。"}, {"text": "这首歌的决策很动听。", "explanation": "这里应该用〈旋律〉。“决策”指对事情做选择和判断，不能用来形容歌曲的好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "决策", "is_correct": true, "explanation": "正确。“对这次决策负全部责任”中，决策是承担责任的对象。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“负全部责任”只能用于能由人承担的事项，不能说对天气负全部责任。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，不是人可以承担责任的决定，句意不通。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是一段时间，不是可以负责的行为或判断，与句意冲突。"}], "explanations": {"决策": "正确。“对这次决策负全部责任”中，决策是承担责任的对象。", "天气": "搭配：“负全部责任”只能用于能由人承担的事项，不能说对天气负全部责任。", "地震": "语义：地震是自然灾害，不是人可以承担责任的决定，句意不通。", "节日": "语义：节日是一段时间，不是可以负责的行为或判断，与句意冲突。"}, "sentence_index": 6, "correct_answer": "决策"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他下定了决策要减肥。", "explanation": "这里应该用〈决心〉。“下定决心”表示意志，“决策”指对事情做选择和判断，不能用于此处。"}, {"text": "他做事很有决策。", "explanation": "这里应该用〈决断〉。“有决断”描述人的果断性格，“决策”是事件，不能用来形容人。"}, {"text": "这片海的决策很蓝。", "explanation": "这里应该用〈颜色〉。“决策”指对重要事情做选择和判断，不能用来形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项重大的决策们需要董事会批准。", "corrected_sentence": "这项重大的决策需要董事会批准。", "error_description": "错误：“们”只能加在指人的名词后面，“决策”是抽象名词，不能说“决策们”，应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "领导们做出了一只重大的决策。", "corrected_sentence": "领导们做出了一项重大的决策。", "error_description": "错误：量词“只”用于动物等，不能用于“决策”。正确的量词是“项”，应说“一项重大的决策”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
