INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19932, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19932, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公平性指事物在处理或分配过程中，不偏袒任何一方，公正平等的特性。", "primary_collocate": null, "pronunciation": "gōng píng xìng", "ipa": "kʊŋ˥ pʰiŋ˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这种透明应具备功能性，即足以支持外部对算法公平性、非歧视性及结果可预测性的合理评估。", "target_word": "公平性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老师很重视考试的公平性。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在讨论比赛的公平性。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法能保证分配的公平性。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怀疑这次选拔的公平性。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要提高评分的公平性。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院的工作要保证公平性。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规则不清楚，就没有公平性可言。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们很在意分蛋糕的公平性。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项政策的公平性受到了质疑。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "算法公平性", "label": "复合"}], "register": "书面", "sense_fingerprint": "处理或分配时不偏袒、公正平等的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '057e6d26-3654-4b17-8f8c-867298f547be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19932, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公平性", "is_correct": true, "explanation": "正确。「算法公平性」与「非歧视性」「结果可预测性」并列，指算法处理时不偏袒任何一方的特性。"}, {"text": "美观性", "is_correct": false, "explanation": "体貌：句中强调功能性与合理评估，外观是否美观不是算法评估的标准。"}, {"text": "娱乐性", "is_correct": false, "explanation": "语义：娱乐性指使人愉快，与透明、可预测的评估要求无关。"}, {"text": "随意性", "is_correct": false, "explanation": "语义：随意性指任意、不按规则办事，与「合理评估」正好相反。"}], "explanations": {"公平性": "正确。「算法公平性」与「非歧视性」「结果可预测性」并列，指算法处理时不偏袒任何一方的特性。", "美观性": "体貌：句中强调功能性与合理评估，外观是否美观不是算法评估的标准。", "娱乐性": "语义：娱乐性指使人愉快，与透明、可预测的评估要求无关。", "随意性": "语义：随意性指任意、不按规则办事，与「合理评估」正好相反。"}, "sentence_index": 0, "correct_answer": "公平性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台洗衣机的公平性很高。", "explanation": "这里应该用〈效率〉。「效率很高」说机器做事的快慢和产出；「公平性」指对待的不偏不倚，不能用来形容洗衣机。"}, {"text": "这座桥的公平性很强。", "explanation": "这里应该用〈承重能力〉。「承重能力很强」说桥能承受的重量；「公平性」指对待的不偏不倚，不能形容桥。"}, {"text": "这幅画的公平性很好。", "explanation": "这里应该用〈构图〉。「构图很好」评价画面的布局；「公平性」指对待的不偏不倚，不能用来评价一幅画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公平性", "is_correct": true, "explanation": "正确。法院工作要保证的是公平，这正是「公平性」的本义。"}, {"text": "戏剧性", "is_correct": false, "explanation": "语义：戏剧性指情节夸张、带有表演色彩，与法院依法办事的要求不合。"}, {"text": "偶然性", "is_correct": false, "explanation": "语义：偶然性与依规则、可靠办事相反，法院工作不能依靠偶然。"}, {"text": "观赏性", "is_correct": false, "explanation": "体貌：观赏性侧重供人欣赏、好看，与法院的公正要求无关。"}], "explanations": {"公平性": "正确。法院工作要保证的是公平，这正是「公平性」的本义。", "戏剧性": "语义：戏剧性指情节夸张、带有表演色彩，与法院依法办事的要求不合。", "偶然性": "语义：偶然性与依规则、可靠办事相反，法院工作不能依靠偶然。", "观赏性": "体貌：观赏性侧重供人欣赏、好看，与法院的公正要求无关。"}, "sentence_index": 6, "correct_answer": "公平性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的公平性很宽。", "explanation": "这里应该用〈宽度〉。「河面很宽」说河的宽窄；「公平性」指对待的不偏不倚，不能形容河。"}, {"text": "他把杯子装满了公平性。", "explanation": "这里应该用〈水〉。「装满」用于容器里的液体或具体物品；「公平性」是抽象的对待方式，不能装进杯子。"}, {"text": "这位老人的公平性很洪亮。", "explanation": "这里应该用〈声音〉。「声音洪亮」形容声音的大小；「公平性」指对待的不偏不倚，不能形容人的声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "改革要保证分配的公平性们。", "corrected_sentence": "改革要保证分配的公平性。", "error_description": "错误：「公平性」是抽象名词，不能加「们」表示复数。正确形式是「公平性」，去掉「们」即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "规则地公平性很重要。", "corrected_sentence": "规则的公平性很重要。", "error_description": "错误：「规则的公平性」中的「的」误写成了「地」。「地」用于修饰动词、形容词，修饰名词「公平性」要用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
