INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19933, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指对待他人时，因为某些特征（如种族、性别、年龄等）而给予不公平、不公正的区别对待。", "primary_collocate": null, "pronunciation": "qí shì xìng", "ipa": "tɕʰi˧˥ ʂʐ̩˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "若训练数据存在偏差，这种算法可能会对不同性别的申请人给出歧视性的结果。", "target_word": "歧视性", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这条广告里有歧视性的话。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不能有歧视性的规定。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题带有歧视性，很不礼貌。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他批评了那份有歧视性的通知。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律禁止歧视性的做法。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这种歧视性的玩笑不好笑。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有人发表歧视性的意见。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "招聘要求写年龄，有歧视性。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词听起来很有歧视性。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "非歧视性", "label": "复合"}, {"form": "歧視性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "因种族、性别、年龄等特征而不公平地区别对待", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '057e6d26-3654-4b17-8f8c-867298f547be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19933, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歧视性", "is_correct": true, "explanation": "正确。「给出……的结果」前面说的是因性别而不公平地区别对待，「歧视性」正合语境。"}, {"text": "美观性", "is_correct": false, "explanation": "体貌：结果美不美观与训练数据是否有偏差无关，句意说的是对人的不公平。"}, {"text": "娱乐性", "is_correct": false, "explanation": "语义：娱乐性指使人愉快，不能用来描述算法给出的结果。"}, {"text": "观赏性", "is_correct": false, "explanation": "体貌：观赏性侧重好看、供人欣赏，与申请人被不公平对待的语境不符。"}], "explanations": {"歧视性": "正确。「给出……的结果」前面说的是因性别而不公平地区别对待，「歧视性」正合语境。", "美观性": "体貌：结果美不美观与训练数据是否有偏差无关，句意说的是对人的不公平。", "娱乐性": "语义：娱乐性指使人愉快，不能用来描述算法给出的结果。", "观赏性": "体貌：观赏性侧重好看、供人欣赏，与申请人被不公平对待的语境不符。"}, "sentence_index": 0, "correct_answer": "歧视性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头很有歧视性。", "explanation": "这里应该用〈特色〉。「很有特色」说事物与众不同的地方；「歧视性」指因特征而不公平地区别对待，不能用来形容石头。"}, {"text": "这盏灯的歧视性很高。", "explanation": "这里应该用〈亮度〉。「亮度很高」说灯的明亮程度；「歧视性」指对人的不公平区别对待，不能形容灯。"}, {"text": "他写作业很有歧视性。", "explanation": "这里应该用〈认真〉。「写作业很认真」形容态度；「歧视性」指对人的不公平区别对待，不能用来形容写作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
